\begin{algorithm}[htbp]
\caption{Bayesian Optimization for Main Reward Weight Tuning}
\label{alg:bo_tuning}
\begin{algorithmic}[1]
\Require Search space $\mathcal{W}$ for $\mathbf{w}=[w_{\mathrm{QoS}}, w_{\mathrm{Stab}}]$
\Require Objective function $f(\mathbf{w})$ (executes MARL train+eval, returns composite score)
\Require Number of initial samples $N_{\mathrm{init}}$
\Require Total number of BO iterations $N_{\mathrm{trials}}$
\Require Acquisition function $\alpha(\mathbf{w})$
\Ensure Optimized main weights $\mathbf{w}^*$

\State \textbf{Initialization:} Sample $N_{\mathrm{init}}$ points $\{\mathbf{w}_1, ..., \mathbf{w}_{N_{\mathrm{init}}}\}$ from $\mathcal{W}$
Evaluate $y_i = f(\mathbf{w}_i)$ for $i = 1, ..., N_{\mathrm{init}}$. Initialize dataset $D = \{(\mathbf{w}_i, y_i)\}_{i=1}^{N_{\mathrm{init}}}$.
\State \textbf{Optimization Loop:}
\For{$t = N_{\mathrm{init}}$ to $N_{\mathrm{trials}}-1$}
    \State Fit/Update Gaussian Process model using data $D$.
    \State Find $\mathbf{w}_{t+1} = \arg\max_{\mathbf{w} \in \mathcal{W}} \alpha(\mathbf{w} | D)$.
    \State Evaluate $y_{t+1} = f(\mathbf{w}_{t+1})$. \Comment{Requires full MARL train+eval}
    \State Augment dataset $D \leftarrow D \cup \{(\mathbf{w}_{t+1}, y_{t+1})\}$.
\EndFor
\State \textbf{Return Best:} Find $\mathbf{w}^* = \arg\max_{\mathbf{w}_i | (\mathbf{w}_i, y_i) \in D} y_i$.
\end{algorithmic}
\end{algorithm}


