    \label{fig:linear_tree}
\end{figure}

In order to represent $\bu \in \ell_2(\cG)$ in the hierarchical tensor format associated to $\T$, we consider matricizations $\cM_{\alpha}(\mathbf{u})$
for each node $\alpha \in \T$. With $\alpha^c= \hat{\cI} \backslash \alpha$, we define $\cM_{\alpha}(\mathbf{u})$ as a Hilbert-Schmidt operator
\[
    \cM_{\alpha}(\mathbf{u}): \ell_2(\times_{i \in \alpha^c}\mathcal{G}_i) \mapsto \ell_2(\times_{i \in \alpha}\mathcal{G}_i)
\]
induced by $\bu$ regarded as a bi-infinite matrix, where the modes in $\alpha$ are taken as row indices and those in $\alpha^c$ as column indices.
Note that $\rank(\cM_{\alpha}(\bu)) = \rank(\cM_{\alpha^c}(\bu))$. We define the set of \emph{effective edges} of the tensor format
\[
    \mathbb{E} = \bigl\{ \{ \alpha, \alpha^c\}: \alpha \in \T \backslash \hat{\cI} \bigr\}.
\]
The elements of $\mathbb{E}$ correspond to the matricizations resulting from $\T$ that are not the same up to transposition; in other words, these are the edges in $\T$, with the exception that the two edges below the root element $\hat{\cI}$ are a single effective edge. 
It is then easy to verify that for $E = \# \mathbb{E}$, we have $E = 2J - 1$. 

In what follows, we assume a fixed enumeration $(\{\alpha_t, \alpha_t^c\})_{t=1,\dots,E}$ of $\mathbb{E}$ such that $\alpha_t \in \T$ for $t = 1,\dots, E$. We abbreviate $\cM_t(\bu)= \cM_{\alpha_t}(\bu)$, denote the singular values of $\cM_t(\bu)$ by $\sigma_t(\bu)$, and write
\[
  \rank_t(\bu) = \rank \cM_t(\bu) =  \#\{k \in \N:\sigma_{t,k}\neq 0\} .
\] 
The hierarchical rank of $\bu$ corresponding to the hierarchical format with dimension tree $\T$ is then given by the tuple
\[
    \rank(\bu) = \bigl(\rank_t(\bu) \bigr)_{t=1,\dots,E} .
\]

In the case of the linear dimension tree \eqref{linear_tree}, we obtain an explicit recursive decomposition of $\mathbf{a}_{k_0,k_1,\dots,k_J}$ in \eqref{Tucker-Tensor-coefficients}. With
\[
    \tilde{r}_i = \rank \bigl( \mathcal{M}_{\{i,\dots,J\}}(\bu_{\varepsilon}) \bigr), \quad i = 1,\dots,J,
\]
we obtain (see, e.g., \cite[Sec.~2.5]{Bachmayr:23}) that $\ba_{k_0,k_1,\dots,k_J}$ can be decomposed in the form
\[
    \ba_{k_0,k_1,\dots,k_J} = \sum_{l_1=1}^{\tilde{r}_1} \mathbf{C}^{(1)}_{k_0,l_1} \sum_{l_2=1}^{\tilde{r}_2} \mathbf{C}^{(2)}_{k_1,l_2,l_1} \cdots 
    \sum_{l_{J}=1}^{\tilde{r}_{J}} \mathbf{C}^{(J)}_{k_{J-1},l_J,l_{J-1}},
\]
with component tensors $\mathbf{C}^{(i)}$, $i = 1,\ldots, J$, of order at most three. Finally, we represent the approximate solution coefficients $\bu_{\varepsilon}$ in hierarchical tensor format with sparse expansions in the form
\begin{multline}
    \label{HT-Sparse-coefficients}
        (\bu_{\varepsilon})_{(\bar{\nu},\lambda),\nu_1,\dots,\nu_J}  = \sum_{k_0=1}^{r_0}\sum_{k_1=1}^{r_1}\cdots \sum_{k_J=1}^{r_J} \sum_{l_1=1}^{\tilde{r}_1} \cdots \sum_{l_J=1}^{\tilde{r}_J}  \mathbf{C}^{(1)}_{k_0,l_1}  \mathbf{C}^{(2)}_{k_1,l_2,l_1} \cdots  \\
     \cdots    \times \mathbf{C}^{(J)}_{k_{J-1},l_J,l_{J-1}} \mathbf{U}^{(0)}_{(\bar{\nu},\lambda),k_0} \mathbf{U}^{(1)}_{\nu_1,k_1} \cdots \mathbf{U}^{(J)}_{\nu_J,k_J},
\end{multline}
supported on $\Lambda = \Lambda_0 \times \Lambda_1 \times \cdots \times \Lambda_J \subset \cG$. 

Note that this type of tensor representation does not involve any explicit truncation of the parametric dimension: The sparse polynomial approximations corresponding to $\Lambda_0$ can depend on any of the tail parametric variables $y_{J+1}, y_{J+2}, \ldots$; this is in contrast to standard approaches to low-rank approximations to this problem, which usually start from a separation of spatial and parametric variables as in \eqref{eq:lrstandardform}. For example, in the methods in \cite{EPS:17,EMPS:20}, the parametric variables are restricted to a subset $y_1, \ldots, y_{J_\mathrm{trunc}}$ with sufficiently large $J_{\mathrm{trunc}}$, and each of these remaining parametric dimensions is assigned to a separate tensor mode in the hierarchical format.


\subsubsection{Stochastic Galerkin discretization}

We now cast the operator equation 
\begin{equation}
    \label{operator-equation}
    \bA \bu = \bbf
\end{equation}
in a form that is compatible with the above tensor approximation format, where the solution $\bu \in \ell_2(\cG)$ is represented in a hierarchical tensor format with a sparse polynomial expansion. We observe that the operator $\bA$ can be written in the form
\begin{equation}
    \label{operator-TT-form}
    \bA = \bar{\bA} \otimes \bI_1 \otimes \cdots \otimes \bI_J + \bB_1 \otimes \bN_1 \otimes \bI_2 \otimes \cdots \otimes \bI_J + \cdots + \bB_J \otimes \bI_{1} \otimes \cdots \bI_{J-1} \otimes \bN_J,
\end{equation}
where $\bar\bA \colon \ell_2(\cG_{0}) \mapsto \ell_2(\cG_{0})$, $\bB_j \colon \ell_2(\cG_{0}) \mapsto \ell_2(\cG_{0})$, $j \in \{1,\dots,J\}$ are defined by
\begin{equation}
    \bar{\bA} = \bM_0 \otimes \bA_0 + \sum_{i = J+1}^\infty (\bM_i \otimes \bA_i), \quad \bB_{j} = \bM_0 \otimes \bA_j,
    \label{def_A_tensor}
\end{equation}
with $\bM_i$ and $\bA_i$ defined as \eqref{def_Mi} and \eqref{def_Ai}, respectively. In addition, $\bI_j$ is the identity operator on $\ell_2(\cG_j)$ and $\bN_j : \ell_2(\cG_{j}) \mapsto \ell_2(\cG_j)$ are given by
\begin{equation}
    \label{def_M_tensor}
    \bN_j =\left(\int_{-1}^{1} y_j L_{\nu_j}(y_j) L_{\nu_j^{\prime}}(y_j) \sdd \sigma(y_j)\right)_{\nu_j, \nu_j^{\prime} \in \cG_j}, \quad j \in \{1,\dots,J\}.
\end{equation}

For any given error tolerance $\varepsilon$, we aim to derive an approximation $\bu_{\varepsilon}$ such that $\norm{\bu - \bu_\varepsilon}\leq \varepsilon$ in the form \eqref{HT-Sparse-coefficients} with quasi-optimal ranks and quasi-optimal discretization sizes $\sum_{j=0}^J \#\Lambda_j$. We will realize this by an adaptive Galerkin method with residual-based discretization refinement, where the Galerkin problem in each step is solved by an iterative scheme operating on the low-rank representations in hierarchical format introduced above.




\section{Soft-thresholding low-rank solver for parametric problems}\label{sec:softthresh}

\label{Sect:soft}
We briefly review the iterative method based on soft thresholding of hierarchical tensors introduced in \cite{BachmayrSchneider:17}. This approach combines convergent iterative schemes in low-rank format with an adaptive adjustment of thresholding parameters, such that the arising ranks of the approximations remain quasi-optimal. 
In our context, we use this method as a solver for Galerkin discretizations that arise in steps of an adaptive scheme, which requires some minor modifications. For $\bv \in \ell_2(\cG)$, we use the notation $\norm{ \bv } = \norm{\bv}_{\ell_2}$.

\subsection{Soft thresholding of hierarchical tensors} 

We first introduce soft thresholding operators for sequences and matrices. Operator for hierarchical tensors is then defined by applying soft thresholding operator successively to each matricization.

For $\mathbf{x} \in \ell_2(\mathcal{I}_1 \times \mathcal{I}_2)$ with countable index sets $\mathcal{I}_1, \mathcal{I}_2$, we denote by  $(\sigma_i(\mathbf{x})) \in \ell_2(\N)$ the non-increasing, non-negative sequence of singular values of $\mathbf{x}$. The singular value decomposition of $\mathbf{x}$ takes the form
\[
\mathbf{x} =\sum_{k=1}^\infty \sigma_k(\mathbf{x}) \mathbf{U}^{(1)}_k \otimes  \mathbf{U}^{(2)}_k
\]
with orthonormal systems $\{ \mathbf{U}^{(i)}_k \}_{k\in\N}$ in $\ell_2(\mathcal{I}_i)$ for $i=1,2$.
Soft thresholding with parameter $\tau \geq 0$ is defined by applying the soft thresholding operation to its singular values, that is,
\begin{equation}
    \label{eq:softmat}
    \ST_{\tau}(\mathbf{x}) = \sum_{k=1}^\infty \max\{ \sigma_k(\mathbf{x}) - \tau, 0 \} \mathbf{U}^{(1)}_k \otimes  \mathbf{U}^{(2)}_k.
\end{equation}

For a hierarchical tensor $\bw$ with suitably numbered effective edges $\{\alpha_t, \alpha_t^c\} \in \mathbb{E}, \, t = 1,\dots,E$, the hierarchical tensor soft thresholding operator $\ST_{\tau}$ as introduced in \cite{BachmayrSchneider:17} is defined as the application of $\ST_{\tau}$ to each matricization, that is,
\begin{equation}
    \label{eq:softtensor}
    \ST_{\tau}(\bw)=\left(\ST_{E, \tau} \circ \cdots \circ \ST_{1, \tau}\right)(\bw),
\end{equation}
where $\ST_{t, \tau}(\bw) = \left( \cM_t^{-1} \circ S_{\tau} \circ \cM_t \right)(\bw)$, and $\cM^{-1}_t$ is the mapping that converts the corresponding matricization back to a tensor. 
Thus soft thresholding is applied to the singular values of matricizations, for which we use the abbreviation
\[
  \sigma_t(\bw) = \sigma\bigl( \cM_t(\bw) \bigr).
\]
For  details on the implementation of the operation \eqref{eq:softtensor}, with its efficiency depending also on a suitable enumeration of the effective edges, we refer to \cite[Sect. 3]{BachmayrSchneider:17}.

Different from hard thresholding, soft thresholding also decreases entries with absolute value above the threshold, which incurs an additional error. However, this operation is non-expansive, as shown in \cite[Proposition 3.2]{BachmayrSchneider:17}: for all $\bv, \bw \in \ell_2(\cG)$ and all $\tau \geq 0$, we have
\[
\norm{ \ST_{\tau}(\bw) - \ST_{\tau}(\bv) } \leq  \norm{ \bw - \bv }.
\]
As a consequence of this property, the composition of $\ST_{\tau}$ with a contractive mapping still yields a convergent fixed-point iteration with a modified fixed point.

In the case of the linear operator equation \eqref{operator-equation}, we consider a contractive mapping $\cT(\bw) = \bw - \omega \left(\bA \bw - \bbf \right)$ with a suitable scaling parameter $\omega > 0$ such that $\norm{ \Id - \omega \bA } \leq \rho < 1$, which implies
\begin{equation}
    \label{eq:contractive}
    \|\cT(\bw) - \cT(\bv)\| \leq \rho \|\bw - \bv\|, \quad \text{for all $\bw, \bv \in \ell_2(\cG)$.}
\end{equation}

As shown in \cite[Lemma 4.1]{BachmayrSchneider:17}, for any $\cT$ as in \eqref{eq:contractive} with unique fixed point $\bu$,
and for any $\tau >0$, there exists a unique $\bu_\tau \in \ell_2(\cG)$ such that $\bu_{\tau} = \ST_{\tau} \left(\cT(\bu_{\tau})\right)$, which satisfies
    \begin{equation}
        \label{eq:bound_soft_contractive}
        (1+\rho)^{-1}\|\ST_{\tau}(\bu) - \bu\| \leq \| \bu_{\tau} - \bu \| \leq (1-\rho)^{-1}\|\ST_{\tau}(\bu) - \bu\|.
    \end{equation}
Moreover, for any $\bw_0 \in \ell_2(\cG)$, for the thresholded fixed-point iteration
\begin{equation}
    \label{eq:soft_iter_basic}
    \bw_{k+1} = \ST_{\tau} \bigl(\cT(\bw_{k})\bigr),
\end{equation}
we have
    \[
        \|\bw_{k} - \bu_{\tau}\| \leq \rho^k \|\bw_0 - \bu_{\tau}\|,
    \]
that is, for any threshold $\tau$, the iteration converges at the same rate as the one for $\cT$ without thresholding, but to a modified fixed point.

To obtain convergence to $\bu$, we thus consider the non-stationary iteration
\begin{equation}
    \label{eq:soft_iter}
    \bw_{k+1} = \ST_{\tau_k} \bigl(\cT(\bw_k)\bigr),
\end{equation}
with a suitable choice of $\tau_k \rightarrow 0$. Evidently, a slow decrease in $\tau_k$ will impede the convergence of the iteration, whereas a rapid reduction in $\tau_k$ may result in iterates with very large tensor ranks. One could choose $\tau_k$ based on the decay of the singular value sequences $\sigma_t(\bu)$ of $\cM_t(\bu)$. In \cite[Theorem 4.4]{BachmayrSchneider:17}, an explicit choice for $\tau_k$ based on knowledge of this decay that yields quasi-optimal rank bounds is provided.
However, the precise decay of the sequences $\sigma_t(\bu)$ is typically not known, and \cite[Algorithm 2]{BachmayrSchneider:17} yields an a posteriori choice of $\tau_k$ that preserves the quasi-optimality of ranks.

\subsection{Application to Galerkin discretizations}

For $\Lambda \subset \cG$, we define the restriction operator $\Restr_{\Lambda} :\ell_2(\cG) \mapsto \ell_2(\cG)$ as pointwise multiplication by the indicator function of $\Lambda$, that is, $\Restr_\Lambda \bv$ equals $\bv$ on $\Lambda$ and vanishes on $\cG\setminus \Lambda$.

The Galerkin approximation of the solution $\bu$ of $\bA \bu = \bbf$ is defined as the unique solution $\bu_{\Lambda} \in \ell_2(\cG)$ with $\supp \bu_\Lambda \subseteq \Lambda$ of
\begin{equation}
   \bA_\Lambda  \bu_{\Lambda}  = \Restr_\Lambda \bbf.
\end{equation}
with the notation
\begin{equation}
 \bA_\Lambda = \Restr_\Lambda  \bA \Restr_\Lambda, \quad \bbf_\Lambda =  \Restr_\Lambda \bbf.
\end{equation}
As a consequence of the ellipticity and boundedness of operator $\bA$, the Galerkin discretization $\bA_\Lambda$ is again elliptic and bounded with the same constants on the subspace $\operatorname{range} (\Restr_\Lambda)$. Thus $\cT_\Lambda(\bw) = \bw - \omega \left(\bA_\Lambda \bw - \bbf_\Lambda \right)$ on this subspace also satisfies the contractivity property \eqref{eq:contractive} for the same values of $\omega$. Specifically, the spectrum of $\bA_{\Lambda}$ is contained in $[\gamma, \Gamma]$. 
with 
\begin{equation}
 \gamma = c_{\Psi}^2 r, \quad  \Gamma = C_{\Psi}^2 (2\|\bar{a}\|_{L_{\infty}} - r),
\end{equation}
with $r$ as in \eqref{UEA} and $c_\Psi, C_\Psi$ as in \eqref{Riesz_basis}. The choice $\omega = 2/(\gamma + \Gamma)$ then yields
\begin{equation}
    \label{eq:omega}
    \norm{ \Restr_\Lambda - \omega \bA_{\Lambda}  }   \leq \frac{\Gamma - \gamma}{\Gamma + \gamma} =: \rho < 1
\end{equation}
independently of $\Lambda$.
The corresponding iterative scheme with $\cT$ replaced by $\cT_\Lambda$,
\begin{equation}
    \label{eq:soft_iter_subspace}
    \bw_{k+1}  = \ST_{\tau_k} \bigl(\cT_\Lambda(\bw_k )\bigr),
\end{equation}
with $\tau_k \to 0$ thus converges to $\bu_\Lambda$ for any $\bw_0$ with $\supp \bw_0 \subseteq \Lambda$.

For finite $\Lambda \subset \cG$ of Cartesian product form $\Lambda = \Lambda_0 \times \cdots \times \Lambda_J$, we have
\begin{equation}\label{eq:cartesianrestr}
  \Restr_\Lambda = \Restr_{\Lambda_0} \otimes \cdots \otimes \Restr_{\Lambda_J},
\end{equation}
so that $\bA_\Lambda$ has the same low-rank structure as $\bA$. It is not difficult to see that also $\sigma_{t,k}( \Restr_\Lambda \bu) \leq \sigma_{t,k}(\bu)$ for $t = 1,\ldots,E$ and $k \in \N$. Note, however, that generally $\Restr_\Lambda \bu \neq \bu_\Lambda$, that is, the restriction of the exact solution $\bu$ need not be equal to the Galerkin solution $\bu_\Lambda$. In particular, the relation between $\sigma_t(\bu_\Lambda)$ and $\sigma_t(\bu)$ is less immediate.


Algorithm \ref{alg_GalerkinSolver} gives the realization of \eqref{eq:soft_iter_subspace} with adaptive adjustment of the thresholding parameter as in \cite[Algorithm 2]{BachmayrSchneider:17}. This scheme does not use a priori knowledge on the low-rank approximability of $\bu$, requiring only a tensor representation of $\bbf$, the action of $\bA$ on such representations, and the bounds $\gamma, \Gamma$ on the spectrum of $\bA$.

\begin{algorithm}
    \caption{$\STSolve(\bA_\Lambda,\bbf_\Lambda, \varepsilon)$}
    \label{alg_GalerkinSolver}
    \begin{flushleft}
        parameters: $\gamma$, $\Gamma$ as in \eqref{UEA_operator}, $\omega$, $\rho$ as in \eqref{eq:omega}, arbitrary $\nu, \theta \in (0,1)$ and $\tau_0 \geq E^{-1}\omega \|\bbf\|$. \\
        output: $\bw_{\Lambda}$ satisfying $\| \bA_{\Lambda} \bw_{\Lambda} - \bbf_{\Lambda} \| \leq \varepsilon$, final iteration counter $I$        
    \end{flushleft}
    \begin{algorithmic}[1]
        \State $\bw_0 := 0$, $\mathbf{s}_0 := \bA_{\Lambda}\bw_0 - \bbf_{\Lambda}$, $i:=0$
        \While {$\|\mathbf{s}_{i} \| > \varepsilon$}
            \State $\bw_{i+1} = \mathrm{ST}_{\tau_i}(\bw_i - \omega \mathbf{s}_i)$
            \State \label{alg_GalerkinSolver_residual} $\mathbf{s}_{i+1} := \bA_{\Lambda}\bw_{i+1} - \bbf_{\Lambda}$
            \If {$\| \bw_{i+1} - \bw_{i} \| \leq \frac{(1-\rho)\nu}{\Gamma \rho} \norm{\mathbf{s}_{i+1}}$}
                \State $\tau_{i+1} := \theta \tau_i$
            \Else
                \State $\tau_{i+1} := \tau_i$
            \EndIf
            \State $i \leftarrow i+1$
        \EndWhile
        \State $\bw_{\Lambda} := \bw_i$, $I := i$
    \end{algorithmic}
\end{algorithm}


The following result is a direct adaptation of \cite[Theorem 5.1]{BachmayrSchneider:17} to our present case of Galerkin discretizations.

\begin{theorem}
    \label{thm:stsolve}
    For a given finite support set $\Lambda \subset \cG$, the procedure $\STSolve$ given in Algorithm \ref{alg_GalerkinSolver} produces $\bw_{\Lambda} \in \ell_2(\cG)$ satisfying $\norm{ \bA_{\Lambda} \bw_{\Lambda} - \bbf_{\Lambda} } \leq \varepsilon$ in finitely many steps. In addition, if $\bu$ is the solution to \eqref{operator-equation}, then for the iterates $\bw_i$ for $i =1, \ldots, I$ of Algorithm \ref{alg_GalerkinSolver} we have the following:
    \begin{enumerate}[{\rm(i)}]
        \item If there exist $M>0$ and $0<p<2$ such that $\sigma_{t,j}(\bu_\Lambda) \leq M j^{-\frac1p}$ for $j \in \N$, $t=1,\dots,E$, then for a $\tilde{\rho} \in (0,1)$, with $\varepsilon_i = \tilde{\rho}^i$ and $s = \frac{1}{p}-\frac{1}{2}$, we have
            \[
                \|\bA_{\Lambda}\bw_i - \bbf_{\Lambda}\| \lesssim (J+1)\varepsilon_i, \quad
                \max\limits_{t=1,\dots,E}\rank_t (\bw_i) \lesssim (J+1)^2 M^{\frac{1}{s}} \varepsilon_i^{-\frac{1}{s}}
            \]
            for $i = 1,\ldots, I$.
            The constants depend on $\gamma, \Gamma, \nu, \theta$, $\tau_0$, and $p$.    
        \item If $\sigma_{t,j}(\bu_\Lambda) \leq Ce^{-cj^\beta}$, for $j\in \N$ and $t=1,\dots,E$, with $C,c,\beta>0$, then for a $\tilde{\rho} \in (0,1)$, with $\varepsilon_i = \tilde{\rho}^i$ we have 
            \[
                \|\bA_{\Lambda}\bw_i - \bbf_{\Lambda}\| \lesssim (J+1)\varepsilon_i, \quad
                \max\limits_{t=1,\dots,E}\rank_t (\bw_i ) \lesssim (J+1)^2 \bigl(1+\abs{ \ln\varepsilon_i} \bigr)^{\frac{1}{\beta}}
            \]
            for $i = 1,\ldots, I$.
            The constants depend on $\gamma, \Gamma, \nu, \theta$, $\tau_0$, and on $C$, $c$ and $\beta$.    
    \end{enumerate} 
\end{theorem}

\begin{remark}
As noted in \cite[Remark~5.6]{BachmayrSchneider:17}, for the effective convergence rates $\tilde \rho$ in Theorem \ref{thm:stsolve}, we have $\tilde\rho \leq \hat \rho^{1/\log (J+1)} < 1$ with $\hat\rho$ independent of $J$. As a consequence, the number of iterations required for achieving the residual threshold $\varepsilon >0$ in Theorem \ref{thm:stsolve} scales with respect to $\varepsilon$ and $J$ as $\mathcal{O}((\abs{\log \varepsilon} + \log J) \log J)$.
\end{remark}

\begin{remark}
The Galerkin residuals required in line \ref{alg_GalerkinSolver_residual} of Algorithm \ref{alg_GalerkinSolver} are finitely supported and can thus in principle be evaluated exactly. However, to obtain optimal computational costs, these residuals need to be evaluated inexactly so that $ \|\mathbf{s}_{i} - (\bA_\Lambda \bw_{i} - \bbf_\Lambda)\| \leq \delta_i$ with suitable tolerances $\delta_i > 0$. Algorithm \ref{alg_GalerkinSolver} can be modified \cite[Algorithm 3]{BachmayrSchneider:17} to accommodate such inexact residuals and then leads to the same results as in Theorem \ref{thm:stsolve}; we do not go into details at this point to avoid technicalities. Suitable residual approximations that can also be applied to Galerkin discretizations are discussed in Section \ref{sec:resapprox}.
\end{remark}




\section{Adaptive low-rank Galerkin method and optimality}\label{sec:adaptgalerkin}

\label{Sect:adaptive}

In this section, we first introduce the basic idea of the adaptive low-rank Galerkin method to solve the operator equation \eqref{operator-equation} on $\ell_2(\cG)$, then detail its ingredients and analyze convergency and complexity. 

In what follows, for $\bv \in \ell_2(\cG)$ we continue to use the abbreviation $\norm{ \bv } = \norm{\bv}_{\ell_2}$ and introduce the energy norm $\norm{ \bv }_{\bA} = \sqrt{ \langle \bA \bv, \bv \rangle}$, for which we have the norm equivalence
\begin{equation}
    \label{UEA_operator}
    \gamma \|\bu\|^2 \leq \|\bu\|^2_\bA \leq \Gamma \|\bu\|^2, \quad \forall \bu \in \ell_2(\cG),
\end{equation}
where $\gamma = c_{\Psi}^2 r,\, \Gamma = C_{\Psi}^2 (2\|\bar{a}\|_{L_{\infty}} - r)$, with $r$ as in \eqref{UEA} and $c_\Psi, C_\Psi$ as in \eqref{Riesz_basis}.

\subsection{Adaptive Galerkin method}
The idealized adaptive Galerkin scheme is constructed by solving successive Galerkin problems on a sequence of nested finite index sets $\Lambda^k \subset \cG$, $k\geq 0$. Starting from some $\Lambda^0$ that may be empty, these are generated by solving for each $k$ the Galerkin problem on $\Lambda^k$ to obtain $\bu_{k} \in \ell_2(\cG)$ with $\supp\bu_k \subseteq \Lambda^k$ satisfying $ \bA_{\Lambda^{k}} \bu_k = \bbf_{\Lambda^{k}} $. Then $\Lambda^{k+1} \subset \cG$ with $\Lambda^{k} \subset \Lambda^{k+1}$ is chosen to satisfy $\norm{\Restr_{\Lambda^{k+1}} (\bA \bu_k - \bbf)} \geq \mu \norm{ \bA \bu_k - \bbf }$, where $0 < \mu \leq 1$ is fixed and sufficiently small.
Convergence of this idealized scheme is ensured by the following well-known result, see \cite[Lemma 4.1]{CohenDahmenDeVore:01}.

\begin{lemma}
    Let $\mu \in (0,1]$, $\bw \in \ell_2(\cG)$ with $\supp \bw \subseteq \Lambda$, and $\Lambda \subset \tilde{\Lambda} \subset \cG$ such that
    \begin{equation}
        \norm{ \Restr_{\tilde \Lambda} (\bA \bw - \bbf) }  \geq \mu \norm{ \bA \bw - \bbf } .
    \end{equation}
    Let $\bu_{\tilde{\Lambda}}$ be the solution to the Galerkin problem $\bA_{\tilde\Lambda} \bu_{\tilde{\Lambda}} = \bbf_{\tilde \Lambda}$, then
    \begin{equation}
        \| \bu - \bu_{\tilde{\Lambda}} \|_\bA \leq (1-\mu^2\kappa(\bA)^{-1})^{\frac{1}{2}} \| \bu - \bw \|_\bA.
    \end{equation}
\end{lemma}

From a practical point of view, required Galerkin approximations $\bu_k$ in the first step can only be computed up to certain error tolerances that need to be accounted for. Furthermore, a main difficulty is that residuals $\bA \bu_k - \bbf$ generally have infinite support. Therefore, in each step this residual needs to be replaced by a finitely supported approximation $\br_k$ of $\bA \bu_k - \bbf$.

Taking these additional aspects into account, in \cite{GantumurHarbrechtStevenson:07} this basic adaptive scheme is analysed in the context of direct sparse approximations of $\bu$, where arbitrary subsets of $\cG$ can be selected. 
In this case, the performance of the method is compared to best $N$-term approximations of $\bu$, which is obtained by selecting $N$ indices corresponding to entries of largest absolute value of $\bu$. Their convergence can be quantified in terms of the approximation classes
\begin{equation}
    \label{eq:approximation_space}
   \cA^s(\cG)  = \bigl\{  \bv \in \ell_2(\cG) \colon \norm{\bv}_{\cA^s(\cG)} := \sup_{N \in \mathbb{N}_0}(N+1)^s \inf_{\#\supp \bv_N \leq N}\| \bv- \bv_N\| < \infty \bigr\}
\end{equation}
for $s>0$, so that for all $\bv \in \cA^s(\cG)$ and $\varepsilon > 0$, there exists $\tilde\bv$ with $\| \bv- \tilde\bv\| \leq \varepsilon$ and
\[
   \# \supp \tilde\bv  \leq  \varepsilon^{-\frac1s} \norm{\bv}_{\cA^s(\cG)}^{\frac1s} \,.
\]

With appropriately adjusted error tolerances, and provided that $\mu$ is chosen sufficiently small and $\Lambda^{k+1}\supseteq \Lambda^k$ is chosen as the smallest index set such that $\norm{ \Restr_{\Lambda^{k+1}} (\bA \bu_k - \bbf)} \geq \mu \norm{ \bA \bu_k - \bbf }$, the method in \cite{GantumurHarbrechtStevenson:07} is shown to produce quasi-optimal selections of $\Lambda^k$ in relation to the achieved error proportional to $\norm{ \bA \bu_k - \bbf }$, that is, for each given tolerance $\varepsilon>0$, the method produces a $\bu_k$ supported on $\Lambda^k$ such that 
\[
 \norm{\bu_k - \bu} \eqsim \norm{\bA \bu_k - \bbf} \lesssim \varepsilon , \qquad \#\Lambda^k \lesssim \varepsilon^{-\frac1{s} } \norm{\bu}_{\cA^s}^{\frac1{s}} \,.
\]


However, for low-rank approximation, we need to construct $\Lambda^{k}$ of Cartesian product form $\Lambda^k = \Lambda^k_0 \times \cdots\times\Lambda^k_J$ as in \eqref{eq:cartesianrestr}. When all operations are performed in low-rank format, both the storage required for approximations and the complexity of the entire scheme depend not on the product, but on the \emph{sum} of mode sizes $\sum_{j=0}^{J}\#\Lambda^{k}_j$, and we accordingly aim to obtain quasi-optimal bounds on these quantities.
While this is achieved by the adaptive low-rank method developed in \cite{BachmayrDahmen:14}, there this requires an intermittent coarsening of discretizations that removes extraneous degrees of freedom. 
As a main contribution in this paper, we exploit the particular structure of our novel approximation format for parametric problems to achieve quasi-optimality of discretizations without coarsening.

In addition to the restriction to product index sets, identifying them by direct comparison of absolute values of entries would be too inefficient, and following \cite{BachmayrDahmen:14}, we thus instead identify product index sets from lower-dimensional quantities termed \emph{contractions}.
We next recall the relevant definitions from \cite[Sec.~3.2.1]{BachmayrDahmen:14} and introduce the required notation. 

For $j = 1,\ldots,J$, let $\nu = (\nu_1,\ldots,\nu_J) \in \cG_1 \times \cdots \times \cG_J$ and $\Lambda_1 \times \cdots \times \Lambda_J \subset \cG_1 \times \cdots \times \cG_J$, we define
\begin{gather}
    \label{eq:check_nu}
    \check{\nu}_j = (\nu_1,\dots,\nu_{j-1},\nu_{j+1},\dots,\nu_J), \\
    \label{eq:check_Lambda}
    \check{\Lambda}_j = \Lambda_1 \times \cdots \times \Lambda_{j-1} \times \Lambda_{j+1} \times \cdots \times \Lambda_J,
\end{gather}
to refer to the corresponding multi-index and product set with component $i$ deleted, respectively. We emphasize that index \eqref{eq:check_nu} and set \eqref{eq:check_Lambda} correspond only to the parametric tensor modes. Since the index $(\bar{\nu},\lambda)$ and set $\Lambda_0$ corresponding to the sparse expansion mode differ from those of the parametric modes, we write them separately. For $\bv \in \ell_2(\cG)$, contractions are defined as 
\begin{equation}
    \label{eq:contraction}
    \begin{aligned}
        & \pi^{(0)}(\bv) = \left(\pi^{(0)}_{(\bar\nu,\lambda)}(\bv)\right)_{(\bar\nu,\lambda) \in \cG_0} = \Biggl( \biggl(\sum_{\nu  \in \cG_1 \times \cdots\times \cG_J} \abs{\bu_{(\bar\nu,\lambda),\nu}}^2 \biggr)^{\frac{1}{2}} \Biggr)_{(\bar\nu,\lambda) \in \cG_0}, \\
        & \pi^{(j)}(\bv) = \left(\pi^{(j)}_{\nu_j}(\bv)\right)_{\nu_j \in \cG_j} = \Biggl( \biggl(\sum_{(\bar\nu,\lambda) \in \cG_0}\sum_{\check{\nu}_j \in \check{\cG}_j}\abs{\bu_{(\bar\nu,\lambda),\nu}}^2 \biggr)^{\frac{1}{2}} \Biggr)_{\nu_j \in \cG_j}, \quad j \in \{1,\dots,J\}.
    \end{aligned}
\end{equation}
These quantities can be computed efficiently from singular value decompositions of matricizations of $\bv$ at costs proportional to $\#\Lambda_j \rank\cM_{\{j\}}(\bv)$, see \cite[Prop.~2]{BachmayrDahmen:14}.

For $\bv \in \ell_2(\cG)$ such that $\pi^{(j)}(\bv) \in \cA^{s_j}(\cG_j)$ with $s_j >0$ for $j= 0,\ldots,J$, for $\varepsilon>0$ we thus aim to identify product index sets $\Lambda = \Lambda_0 \times \cdots \times \Lambda_J$ such that $\norm{\bv - \bv_{\Lambda_\varepsilon}} \leq \varepsilon$ that satisfy the quasi-optimal bound
\[
    \sum_{j=0}^{J} \#\Lambda_{\varepsilon,j} \lesssim \sum_{j=0}^{J}  \bignorm{\pi^{(j)}(\bv)}_{\cA^{s_j}}^{\frac{1}{s_j}} \varepsilon^{-\frac{1}{s_j}} \,.
\]

An adaptive low-rank Galerkin method that does not use coarsening of discretizations is given in Algorithm \ref{alg_adaptive}. It comprises three fundamental components specifically designed for the hierarchical tensor format and adapted to the present class of parametric problems:
\begin{enumerate}[{\rm(I)}]
    \item \emph{Galerkin solver:} Provide a Galerkin approximation $\bu_k \in \ell_2(\cG)$ supported on $\Lambda^k$ such that for the given error tolerance $\eta$, 
        \begin{equation}
            \label{eq:Galerkin_error_estimate}
            \| \bA_{\Lambda^k} \bu_{k} - \bbf_{\Lambda^k} \| \leq \eta.
        \end{equation}
    \item \emph{Residual approximation:} Return a finitely supported approximation $\br_{k}$ of $\bA  \bu_{k} - \bbf$ with a given tolerance $\xi$ and $\tilde{\Lambda}^{k}$, such that $\supp \br_k \subset \tilde{\Lambda}^{k}$ and
        \begin{equation}
            \label{eq:resi_appro_error_estimate}
            \| \br_{k} - (\bA \bu_{k} - \bbf) \| \leq \xi .
        \end{equation}
    \item \emph{Discretization refinement in tensor modes:} For a given parameter $\alpha \in (0,1)$, return a product index set $\Lambda^{k+1}$ with $\Lambda^{k} \subset \Lambda^{k+1} \subset \operatorname{supp}(\br_{k})$, such that
        \begin{gather}
        	\label{update_rule}
            \norm{  \Restr_{\Lambda^{k+1}} \br_{k} } \geq \alpha \norm{ \br_{k}  } , \\
            \label{update_rule_optimality}
            \sum_{j=0}^{J}\#(\Lambda^{k+1}_j \backslash \Lambda^{k}_j) \lesssim \sum_{j=0}^{J} \bignorm{\bA \bu_k - \bbf}^{-\frac{1}{s_j}} \bignorm{\pi^{(j)}(\bu)}_{\cA^{s_j}}^{\frac{1}{s_j}} .
        \end{gather}
\end{enumerate}

To achieve \eqref{eq:Galerkin_error_estimate}, we use the Galerkin solver based on the Richardson iterative method with a soft thresholding operator for rank reduction in hierarchical tensors described in Algorithm \ref{alg_GalerkinSolver}. 
We provide a detailed analysis of the further components in the following subsections.

\begin{algorithm}
    \caption{Adaptive low-rank approximation method}
    \label{alg_adaptive}
    \begin{flushleft}
        parameters: $\delta \in (0,\alpha)$, $\mu= \frac{\alpha+\delta}{1-\delta} < \kappa(\bA)^{-\frac{1}{2}}$ and 
        $0<\eta < \frac{(1-\delta)(\alpha-\delta)}{1+\delta}\kappa(\bA)^{-1}$.\\
        output: $\bu_{\varepsilon}$ satisfying $\|\bA \bu_{\varepsilon} - \bbf\| \leq \varepsilon$
    \end{flushleft}
    \begin{algorithmic}[1]
    \State $k:=0$, $\Lambda^0 := \emptyset$, $\bu_0 := 0$, $\varepsilon_{-1} := \|\bbf\|$
    \State $\xi:= \theta \varepsilon_{-1}$
    \While {$\xi > \delta \|\br_0\|$}
        \State $\xi := \xi/2$
        \State $\br_0, \tilde{\Lambda}^0 := \ResApprox(\bu_0,\bA,\bbf,\Lambda^0, \xi)$
    \EndWhile
    \While {$\varepsilon_k := \| \br_{k} \| + \xi > \varepsilon$}
        \State $\Lambda^{k+1} := \Expand(\br_k,\Lambda^k,\tilde{\Lambda}^{k},\alpha)$ \label{alg:Adap_expand}
        \State $\bu_{k+1} := \STSolve(\bA_{\Lambda^{k+1}}, \bbf_{\Lambda^{k+1}}, \eta \|\br_k\|)$ \label{alg:Adap_solve_relative_error}
        \State $\xi := \theta \varepsilon_k$
        \While {$\xi > \delta \|\br_{k+1}\|$} \label{alg:Adap_resi_relative_error}
            \State $\xi := \xi/2$
            \State $\br_{k+1}, \tilde{\Lambda}^{k+1} := \ResApprox(\bu_{k+1},\bA,\bbf,\Lambda^{k+1}, \xi)$
        \EndWhile
        \State $k \leftarrow k+1$
    \EndWhile
    \State $\bu_{\varepsilon} := \bu_k$
    \end{algorithmic}
\end{algorithm}


\subsection{Residual approximation}\label{sec:resapprox}


Let $\bw_{\Lambda}$ with $\supp \bw_\Lambda \subseteq \Lambda$ be an approximate solution to $\bA_\Lambda \bu_\Lambda =\bbf_\Lambda$ with Galerkin error $\norm{\bA_\Lambda \bw_\Lambda - \bbf_\Lambda} \leq \eta$. In order to find a finitely supported approximation to $\bA\bw_{\Lambda}-\bbf$, we determine an extended product index set $\tilde{\Lambda} \supset \Lambda$ based on a fixed residual tolerance $\xi$ and construct an approximation $\br_\Lambda$ of $\bA_{\tilde{\Lambda}}\bw_\Lambda - \bbf_{\tilde{\Lambda}}$ such that $\supp \br_\Lambda \subset \tilde{\Lambda}$ and $\norm{ \br_{\Lambda} - (\bA \bw_{\Lambda} - \bbf) } \leq \xi$. This procedure is referred to as
$\ResApprox(\bw_{\Lambda}, \bA, \bbf, \Lambda, \xi)$. 

By iteratively halving the value of $\xi$ in $\ResApprox(\bw_{\Lambda}, \bA, \bbf, \Lambda, \xi)$ until $\xi \leq \delta \norm{\br_{\Lambda}}$ for a given $\delta$, we obtain the desired approximation $\br_{\Lambda}$ which satisfies \eqref{eq:resi_appro_error_estimate} and thus also the relative error bound
\[  \norm{\br_\Lambda - (\bA\bw_{\Lambda}-\bbf)} \leq \delta \norm{\br_\Lambda}  \]
as required in Algorithm \ref{alg_adaptive}.

We recall the hierarchical tensor decomposition of $\bA$ as in \eqref{operator-TT-form} and \eqref{def_A_tensor} in terms of the components
\[
    \bA = \bar{\bA} \otimes \bI_1 \otimes \cdots \otimes \bI_J + \bB_1 \otimes \bN_1 \otimes \bI_2 \otimes \cdots \otimes \bI_J + \cdots + \bB_J \otimes \bI_{1} \otimes \cdots \bI_{J-1} \otimes \bN_J,
\]
with the components associated to the spatial-parametric zeroth mode given by
\[  
\bar{\bA} = \bM_0 \otimes \bA_0 + \sum_{i = J+1}^\infty (\bM_i \otimes \bA_i), \qquad \bB_{j} = \bM_0 \otimes \bA_j, \quad j=1,\dots,J.
\]
The set product set $\tilde{\Lambda}$ is built by identifying its factors $\tilde{\Lambda}_j \subset \cG_j$, $j=0,\ldots,J$, using the contractions $\pi^{(j)}(\bw_\Lambda)$, $j = 0, \ldots,J$ for controlling error tolerances, as described in \cite[Sec.~4.1]{BachmayrDahmen:14}.

We first consider the index sets $\tilde{\Lambda}_j$ for the parametric modes $j=1,\ldots,J$. Due to the three-term recursion for the orthonormal Legendre polynomials \eqref{eq:threeterm},
the matrix $\bN_j$ is bidiagonal for $j = 1,\dots,J$. Specifically, the entry of $\br_{\Lambda}$ with index $\big((\bar{\nu}',\lambda'),\nu'_1,\ldots,\nu'_J\big)$ can be non-zero only when there exists a $j \in \{1,\ldots,J\}$ and a $\nu_j \in \Lambda_j$ such that $\nu^{\prime}_j = \nu_j \pm 1$. Consequently, this allows for the simple construction of $\tilde{\Lambda}_j$ as 
\begin{equation}
    \label{tilde_Lambda_j}
    \tilde{\Lambda}_j = \{\nu_j \pm 1 : \nu_j \in \Lambda_j\}\cap \N_0, \quad j = 1,\dots,J.
\end{equation}

The main difficulty lies in the construction of $\tilde{\Lambda}_0$ corresponding to the sparse expansion mode, which involves enriching both spatial discretizations and the product Legendre polynomial expansions. 
In view of \cite[Sec.~4.1]{BachmayrDahmen:14}, this requires approximating the action of $\bar\bA$ and $\bB_j$, $j=1,\ldots, J$, on the contraction $\pi^{(0)}(\bw_\Lambda)$.
There exist different methods for performing this approximation and identifying $\tilde\Lambda_0$ that are applicable in particular under different assumptions on the functions $\theta_j$, $j \in \cI$, in the expansion \eqref{eq:affine}. The choice of the method for producing $\#\tilde\Lambda_0$ is not essential for the developments in the present work, but has an impact on the total computational costs of $\ResApprox$. We will investigate this point in more detail in future work, and here we thus only outline several available constructions.

A standard framework for sparse approximation of residuals is based on \emph{$s^*$-compressibility} of operators \cite{CohenDahmenDeVore:01}. The compressibility of $\bB_j$ then follows directly from that of the spatial component $\bA_j$ for $j=1,\ldots,J$, which is provided by standard results; see, for example, \cite{CohenDahmenDeVore:01,Stevenson:02}. For $\{ \theta_j \}$ with global supports on $D$ (as, for example, in Karhunen-Lo\`eve expansions of random fields), compressibility of $\bar\bA$ can be deduced from the results in \cite{Gittelson:13,Gittelson:14}. In general, however, in this setting one does not obtain optimal computational costs, except when the order is limited by the spatial discretization.

Better compressibility of $\bar\bA$ and accordingly improved computational costs can be obtained for $\theta_j$ with multilevel structure as in Assumption \ref{multilevel_structure}. The following observation from \cite{BachmayrCohenDahmen:18} is the basis for the improved approximations of $\bar\bA$.

\begin{prop}
    \label{Prop:semi_residual_appro}
    Let Assumption \ref{multilevel_structure} hold. Then for $\ell \in \N$,
    \begin{equation}
        \label{eq:semi_residual_appro}    
         \biggnorm{ \bar{\bA} - \sum_{\substack{(\ell,k) \in \bigcup_{n < L} \{ n\} \times \mathcal I_n \\ j(\ell,k) > J}} \mathbf{M}_{j(\ell,k)} \otimes \mathbf{A}_{ j(\ell,k) } } \lesssim  2^{- \alpha L }
     \end{equation}
    with constant depending on those in Assumption \ref{multilevel_structure} and on $c_{\Psi}$, $C_{\Psi}$ in \eqref{Riesz_basis}.
\end{prop}

This leads to approximations of $\bar\bA$ by levelwise truncation of the sum in \eqref{eq:affine}, which in  \cite{BachmayrCohenDahmen:18} is combined with standard compression for the operators $\bA_0$ and $\bA_j$, $j>J$, to show $s^*$-compressibility of $\bar\bA$. However, this does not lead to optimal computational costs and requires strong smoothness requirements on the functions $\theta_j$ and the spatial wavelet basis.

An alternative approach based on Assumption \ref{multilevel_structure} is developed in \cite{BachmayrVoulis:22}, based on the observation that a semi-discrete approximation in the parametric variables based on Proposition \ref{Prop:semi_residual_appro} can be combined with a fixed level of local spatial refinement in the spatial wavelet discretizations to achieve any desired relative error. This scheme leads to a method of optimal computational complexity. In \cite{BachmayrVoulis:22}, the additional assumption that the wavelet basis functions are in $H^2(D)$ is used; more recent results in \cite{BEEV:24}, however, show that this requirement can be removed.

For our numerical tests, we use a simplified version of the method described in \cite[Sect. 4]{BachmayrVoulis:22} to generate $\tilde\Lambda_0$ and then directly approximate $\mathbf{A}_{\tilde\Lambda} \mathbf{w}_\Lambda - \bbf_{\tilde \Lambda}$ based on Proposition \ref{Prop:semi_residual_appro} by directly applying the spatial discretization matrices. While this leads to the same $\tilde\Lambda$ as the method from \cite{BachmayrVoulis:22}, for optimal computational costs the latter additionally requires tree-based refinement of wavelet discretizations and that all operations are carried out hierarchically using this tree structure. Since the incorporation of these further techniques into the present adaptive low-rank method are not essential for what follows, we address this point in a forthcoming work.


\subsection{Discretization refinement}
Let $\bu \in \ell_2(\cG)$ be the solution to \eqref{operator-equation} and let $\pi^{(0)}(\bu) \in \cA^{s_1}$, $\pi^{(j)}(\bu) \in \cA^{s_2}$ for $j=1,\dots,J$, which quantify the approximabilities of sparse expansion mode frame and parametric mode frames, respectively. Let $\bw_{\Lambda}$ with $\supp \bw_\Lambda \subseteq \Lambda$ be an approximate Galerkin solution $\norm{\bA_\Lambda \bw_\Lambda - \bbf_\Lambda} \leq \eta$. Moreover, let $\br_\Lambda \in \ell_2(\cG)$ with finite support $\tilde{\Lambda}$ satisfy $\norm{\br_\Lambda - (\bA\bw_{\Lambda}-\bbf)} \leq \delta \norm{\br_\Lambda}$, where $0<\delta<\alpha$ and $\alpha > 0$ as in \eqref{update_rule_sect4}. We aim to construct a quasi-optimal product set $\bar{\Lambda}$ with $ \Lambda \subset \bar{\Lambda} \subset \tilde{\Lambda}$, such that
\begin{equation}
    \label{update_rule_sect4}
    \norm{\Restr_{\bar{\Lambda}}\br_{\Lambda} } \geq \alpha\norm{\br_{\Lambda}},
\end{equation}
and simultaneously bound the total number of added indices in all tensor modes, that is, we aim to show an estimate of the form
\begin{equation}
    \label{update_rule_optimality_sect4}    
    \sum_{j=0}^{J}\#(\bar\Lambda_j \backslash \Lambda_j) \lesssim \bignorm{\bA \bw_\Lambda - \bbf}^{-\frac{1}{s_1}} \, \bignorm{\pi^{(0)}(\bu)}_{\cA^{s_1}}^{\frac{1}{s_1}} + \sum_{j=1}^{J}  \bignorm{\bA \bw_\Lambda - \bbf}^{-\frac{1}{s_2}} \, \bignorm{\pi^{(j)}(\bu)}_{\cA^{s_2}}^{\frac{1}{s_2}}.
\end{equation}

In the framework of sparse approximations without tensor product structure as in \cite{CohenDahmenDeVore:01, GantumurHarbrechtStevenson:07}, the natural approach to refine $\Lambda$ is adding the minimal number of indices corresponding to the largest entries of $\br_\Lambda$ to $\Lambda$, such that \eqref{update_rule_sect4} is satisfied. This process of discarding basis indices from approximate solutions is called \emph{coarsening}. 
In \cite{CohenDahmenDeVore:01}, recurrent coarsening steps are added after a certain number of refinements. In \cite{GantumurHarbrechtStevenson:07}, the authors give a modified adaptive Galerkin method that is quasi-optimal without requiring coarsening by choosing sufficiently small $\alpha < \kappa(\bA)^{-\frac{1}{2}}$.

In cases where $\Lambda = \Lambda_0 \times \cdots \times \Lambda_J$ has a Cartesian product structure, we are thus interested in iteratively refining $\Lambda$ while guaranteeing quasi-optimality without recurrent coarsening.
In \cite{BachmayrDahmen:14}, another type of adaptive algorithm based on inexact Richardson iteration is considered that after several steps of refinement performs a coarsening based on contractions. 
While the construction ensures quasi-optimal sizes of the discretization in the tensor modes, coarsening with a sufficiently large error tolerance is required, which in turn can be done only when a certain error reduction has been achieved. Especially for large numbers of tensor modes, this interplay leads to quantitatively unfavorable performance. Moreover, an adaptive Galerkin method for hierarchical tensor format was introduced in \cite{AliUrban:20}, where recurrent coarsening also played a crucial role for optimality of discretizations. 

In what follows, we first introduce the expansion method given in Algorithm \ref{alg_expand} in details that refines $\Lambda$ to $\bar{\Lambda}$ in a tensor product structure, which is based on contractions of approximate residual $\br_\Lambda$. In Theorem \ref{thm:bound_bar_Lambda} we then prove that the total number of added indices in all tensor modes, $\sum_{j=0}^{J} \#(\bar{\Lambda}_j \backslash \Lambda_j)$, can be related to that of the optimal product set $\widehat\Lambda$ in the sense that it satisfies \eqref{update_rule_sect4} while it has a near-minimal number of added indices in all tensor modes. In Theorem \ref{thm:optimal_set_size}, with setting $\alpha < \kappa(\bA)^{-\frac{1}{2}}$, we show the quasi-optimality of set $\Lambda^*$, where $\Lambda^* = \Lambda_0^* \times \cdots \times \Lambda_J^* \subset \cG$ is a minimizer of $\sum_{j=0}^J \#(\Lambda_j^* \backslash \Lambda_j)$ among the product sets such that
\[
    \norm{\Restr_{\Lambda^*}(\bA \bw_\Lambda -\bbf)} \geq \alpha \norm{\bA \bw_\Lambda - \bbf} .
\]
Altogether, these results establish quasi-optimality of $\bar{\Lambda}$ as constructed by Algorithm \ref{alg_expand}, which is illustrated in Theorem \ref{thm:complexity}.

We recall the following proposition from \cite[Prop.~2]{BachmayrDahmen:14}, which illustrates some properties of contractions that are crucial for our expansion method. Property (ii) bounds coarsening errors in terms of contractions, while property (iii) provides a way of computing contractions from singular value decompositions of matricizations without high-dimensional summations.
\begin{prop}
    \label{prop:contractions}
    Let $\bv \in \ell_2(\cG)$.
    \begin{enumerate}[{\rm(i)}]
        \item We have $\|\bv\| = \| \pi^{(j)}(\bv) \|$, $j = 0,1,\dots,J$.
        \item Let $\Lambda \subset \cG$; then \[ \|\bv - \Restr_{\Lambda}\bv \|^2 \leq \sum_{(\bar\nu_,\lambda) \in \cG_0 \backslash \Lambda_0}|\pi^{(0)}_{(\bar\nu,\lambda)}(\bv)|^2 + \sum_{j=1}^{J} \sum_{\nu_j \in \cG_j \backslash \Lambda_j} |\pi^{(j)}_{\nu_j}(\bv)|^2, \]
        \item For $j=0,1,\ldots,J$, let $\mathbf{U}^{(j)}$ be the mode frames of a higher-order singular value decomposition, and let $\sigma^{(j)}$ be the corresponding sequences of singular values. Then 
        \begin{gather}
            \pi^{(0)}_{(\bar\nu,\lambda)}(\bv) = \biggl( \sum_{k} |\mathbf{U}^{0}_{(\bar\nu,\lambda),k}|^2 |\sigma^{(0)}_k|^2 \biggr)^{\frac{1}{2}}, \quad  (\bar\nu,\lambda) \in \cG_0, \\
            \pi^{(j)}_{\nu_j}(\bv) = \biggl( \sum_{k} |\mathbf{U}^{(j)}_{\nu_j,k}|^2 |\sigma^{(j)}_k|^2 \biggr)^{\frac{1}{2}}, \quad \nu_j \in \cG_j, \quad j \in \{1,\dots,J\}.
        \end{gather}
    \end{enumerate}
\end{prop}

