\begin{definition}[Existential Constraints]
\label{def:existantial constraints}
An \emph{existential constraint} is a pair $\langle \vec{x},
\varphi \rangle$ of a sequence of variables $\vec{x}$ and a constraint
$\varphi$, written as $\ECO{\vec{x}}{\varphi}$, 
such that $\SET{\vec{x}} \subseteq \Var(\varphi)$.
We define
sets of \emph{free} and \emph{bound} variables of $\ECO{\vec{x}}{\varphi}$
as follows:
%\begin{enumerate}
%\item 
\Bfnum{1}
$\FVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \setminus \SET{\vec{x}}$, and
%\item 
\Bfnum{2}
$\BVar(\ECO{\vec{x}}{\varphi}) = \SET{\vec{x}}$.
%\end{enumerate}
\end{definition}

\begin{example}
\label{ex:existential constraints}
%%
For example
$\ECO{x}{(x \ge 3) \land (y = x * z)}$ is an existential constraint. So are
$\ECO{x,y,z}{(y = x * z)}$, $(y = x * z)$, and $\m{true}$.
However, neither $(\ECO{x}{y = 4 * z}) \land (\ECO{z}{y = 3 * z})$ 
(cannot be of the form $\langle \vec{x}, \varphi \rangle$)
nor $\ECO{y}{x \ge 3}$ ($\SET{y} \not\subseteq \SET{x} =  \Var(x \ge 3)$) is.
%\JS{satisfy the requirements of existential constraints}. 
We have
$\FVar(\ECO{x}{(x \ge 3) \land (y = x * z)}) = \SET{y,z}$ and $\BVar(\ECO{x}{(x
\ge 3) \land (y = x * z)}) = \SET{x}$.
%%
\end{example}

Remark here that, despite its name and form, $\ECO{\vec{x}}{\varphi}$ is not
defined as a usual existentially quantified formula, so that it
is not identified modulo renaming of the bound variables $\vec{x}$, ensuring
that $\BVar$ is well-defined. In fact, ``existential quantification'' is only
considered when the constraint is interpreted in the model.

\begin{restatable}{lemma}{LemmaIIIii}
\label{lem:property existential constraints}
%\textcolor{red}{TA: Since almost the same property is rephrased in a lemma below, 
%we can move it to Appendix (and delete two sentences after Definition 3.4).}
Let $s$ be a term and $\ECO{\vec{x}}{\varphi}$ an existential constraint.
Then, the following statements are equivalent:
%\begin{enumerate}
%    \item 
\Bfnum{1}
    $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq \Var(s)$ and $\BVar(\ECO{\vec{x}}{\varphi}) \cap \Var(s) = \varnothing$
%    \item
\Bfnum{2}
    $\BVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \setminus \Var(s)$
%    \item
\Bfnum{3}
    $\FVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \cap \Var(s)$
%\end{enumerate}
\end{restatable}

\begin{proof}[Sketch]
Show \Bfnum{1} $\implies$ \Bfnum{2}, \Bfnum{2} $\iff$ \Bfnum{3}, and
\Bfnum{3} $\implies$ \Bfnum{1}.
\qed
\end{proof}


As the name suggests, the existential quantifier in existential constraints
is interpreted on the model as in the predicate logic. Since constants in 
our model $\xM$ appear as constants (values) in our signature, we define validity and satisfiability as follows.

\begin{definition}[Validity and Satisfiablity of Existential Constraints]
Let $\ECO{\vec{x}}{\varphi}$ be an existential constraint,
and $\rho$ a valuation.
Then, we write $\vDash_{\xM,\rho} \ECO{\vec{x}}{\varphi}$ if 
there exists $\vec{v} \in \Val^*$ such that $\vDash_{\xM,\rho} \varphi\kappa$,
where $\kappa = \SET{\vec{x} \mapsto \vec{v}}$.
%
An existential constraint $\ECO{\vec{x}}{\varphi}$ is said to be \emph{valid}, 
written as $\vDash_{\xM} \ECO{\vec{x}}{\varphi}$, if 
$\vDash_{\xM,\rho} \ECO{\vec{x}}{\varphi}$ for any valuation $\rho$.
%
An existential constraint $\ECO{\vec{x}}{\varphi}$ is said to be \emph{satisfiable} if 
$\vDash_{\xM,\rho} \ECO{\vec{x}}{\varphi}$ for some valuation $\rho$.
%
%A standard terminology of constraints-respected substitutions is also 
%extended to existential constraints in a natural way:
For any substitution $\sigma$,
we write $\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$ 
(and say $\sigma$ respects $\ECO{\vec{x}}{\varphi}$) 
if $\sigma(\FVar(\ECO{\vec{x}}{\varphi})) \subseteq \Val$
and $\vDash_\xM (\ECO{\vec{x}}{\varphi})\sigma$.
Here, $(\ECO{\vec{x}}{\varphi})\sigma$ denotes the application of 
substitution for predicate formula (thus, in particular, substitution to bound variables
should be avoided).
% \NN{: $(\ECO{\vec{x}}{\varphi})\sigma 
% := \ECO{\vec{x}}{(\varphi\sigma|_{\FVar(\ECO{\vec{x}}{\varphi})})}$.}}

\end{definition}
