\begin{example}[Cont'd from \Cref{ex:existential constraints}]
\label{ex:constraint respect substitution}
Let $\mathbb{Z}$ be the standard integer model
and $\rho$ a valuation such that $\rho(y) = 6$ and $\rho(z) = 2$.
Then $\vDash_{\mathbb{Z},\rho} \ECO{x}{(x \ge 3) \land (y = x \times z)}$,
because by taking $\kappa = \SET{x \mapsto 3}$
we obtain $\vDash_{\mathbb{Z},\rho} (3 \ge 3) \land (y = 3 \times z)$.
Thus, $\ECO{x}{(x \ge 3) \land (y = x \times z)}$ is satisfiable.
Note that it is not valid---as witness consider a valuation $\rho'$ 
with $\rho'(y) = 5$ and $\rho'(z) = 2$.
%\JS{Moreover}, 
For other examples $\ECO{x}{(x \ge 3) \land (y \le 3) \land (x < y)}$ is not satisfiable,
%\JS{but} 
while $\ECO{x}{(x \ge 3) \land (y \le x)}$ is valid.
Let $\sigma = \SET{y \mapsto 3+3, z \mapsto 2}$ be a substitution.
Then $\sigma \not\vDash_\mathbb{Z} \ECO{x}{(x \ge 3) \land (y = x \times z)}$,
as $\sigma(y) \notin \Val$.
On the other hand,
we have $\sigma' \vDash_\mathbb{Z} \ECO{x}{(x \ge 3) \land (y = x \times z)}$
for a substitution $\sigma' = \SET{x \mapsto 1, y \mapsto 6, z \mapsto 2}$
as $\SET{y,z} \subseteq \VDom(\sigma')$ and 
the application of $\sigma'$ gives $(\ECO{x}{(x \ge 3) \land (6 = x \times 2)})$.
\end{example}

Now, we use existential constraints to define existentially constrained terms.

\begin{definition}[Existentially Constrained Term] % from PPL
\label{def:constrained-term}
%An \emph{existentially quantified constraint} is a  pair $\langle \SET{\vec{x}},
%\varphi \rangle$, written as $\ECO{\vec{x}}{\varphi}$\JS{,} such that
%$\SET{\vec{x}} \subseteq \Var(\varphi)$ and $\varphi$ is a constraint. The sets
%of \emph{free} and \emph{bound} variables of $\ECO{\vec{x}}{\varphi}$ are
%defined as follows:
%$\FVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \setminus \SET{\vec{x}}$,
%        and
%$\BVar(\ECO{\vec{x}}{\varphi}) = \SET{\vec{x}}$.
An \emph{existentially constrained term} is a 
triple $\langle X, s, \ECO{\vec{x}}{\varphi} \rangle$, written as $\CTerm{X}{s}{\vec{x}}{\varphi}$, 
of a set $X$ of variables,
a term $s$, and an existentially constraint $\ECO{\vec{x}}{\varphi}$,
such that
%\begin{enumerate}
%    \item $X$ is a set of variables---variables in $X$ are called \emph{logical variables}, 
%    \item $s$ is a term,
%    \item $\ECO{\vec{x}}{\varphi}$ is an existentially quantified constraint, 
%    \item
\Bfnum{1}
    $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq X \subseteq \Var(s)$,
        and
%    \item 
\Bfnum{2}
    $\BVar(\ECO{\vec{x}}{\varphi}) \cap \Var(s) = \varnothing$.
%\end{enumerate}
Variables in $X$ are called \emph{logical variables} (of $\CTerm{X}{s}{\vec{x}}{\varphi}$).
\end{definition}


\begin{example} 
\label{ex:existential-Constrained-Term}
Let $\mathsf{f},\mathsf{g} \in \xFTe$.
From this we construct the three existentially constrained terms
$\CTerm{\SET{x}}{\mathsf{g}(x)}{y}{x = 3 \times y}$, 
%$\CTerm{\SET{x,y}}{\mathsf{f}(x+2,\mathsf{g}(y))}{z}{x = y \times z}$, 
%and 
$\CTerm{\SET{x}}{\mathsf{f}(x+2,\mathsf{g}(y))}{z}{x = 2 \times z}$,
and 
$\CTerm{\varnothing}{\mathsf{g}(x)}{}{\m{true}}$.
The last one is abbreviated as $\CTerm{\varnothing}{\mathsf{g}(x)}{}{}$.
%The \JS{following} are \JS{no} existentially constrained terms:
None of the following expressions are existentially constrained terms:
$\CTerm{\SET{y}}{\mathsf{g}(x)}{z}{z \ge y}$
($y$ does not appear in $\mathsf{g}(x)$),
$\CTerm{\SET{y}}{\mathsf{g}(x)}{x}{x \ge y}$
(the bound variable $x$ appears in $\mathsf{g}(x)$), and
$\CTerm{\SET{x}}{\mathsf{f}(x,y)}{z}{z \ge y}$
($y$ is not %\JS{part of} 
a member of the set $\SET{x}$).
\end{example}


Note that the conditions~\Bfnum{1},\,\Bfnum{2} of existentially constrained terms
equals the condition~\Bfnum{1} of \Cref{lem:property existential constraints}
including the condition on $X$ (i.e., $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq X \subseteq \Var(s)$).
Thus, \Cref{lem:property existential constraints}
states useful equivalences w.r.t.\ the variable conditions of existentially constrained terms 
as follows:
%This equivalence will later be used without explicitly mentioning.

\begin{restatable}{lemma}{LemmaIIIiv}
Let $X$ be a set of variables, $s$ a term, and
$\ECO{\vec{x}}{\varphi}$ an existential constraint. Then, the
following statements are equivalent:
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item 
%\Bfnum{1.}
    $\CTerm{X}{s}{\vec{x}}{\varphi}$ is an existentially constrained term,
    \item
%\Bfnum{2.}
    $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq X \subseteq \Var(s)$ and $\BVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \setminus \Var(s)$, and
    \item 
%\Bfnum{3.}
    $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq X \subseteq \Var(s)$ and $\FVar(\ECO{\vec{x}}{\varphi}) = \Var(\varphi) \cap \Var(s)$.
\end{enumerate}
\end{restatable}

We give now the notion of equivalence of constrained terms together 
withe the notion of subsumption.

\begin{definition}[Subsumption and Equivalence]
\label{def:subsumption and equivalence}
An existentially constrained term $\CTerm{X}{s}{\vec{x}}{\varphi}$ is said to be
\emph{subsumed by} an existentially constrained term
$\CTerm{Y}{t}{\vec{y}}{\psi}$, denoted by $\CTerm{X}{s}{\vec{x}}{\varphi}
\subsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$, if for all $X$-valued substitutions
$\sigma$ with 
$\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$ 
there exists a
$Y$-valued substitution $\gamma$ with 
$\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$
such that $s\sigma = t\gamma$.
Two existentially constrained terms
$\CTerm{X}{s}{\vec{x}}{\varphi}$
and $\CTerm{Y}{t}{\vec{y}}{\psi}$ are said to be \emph{equivalent},
denoted by $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$, 
if $\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$
and 
$\CTerm{X}{s}{\vec{x}}{\varphi} \supsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$.
\end{definition}

\begin{example} 
\label{ex:subsumption and equivalence}
Consider $\mathsf{f} \in \xFTe$ for a signature of an LCTRS over the theory of integers.
% Then, %all of the following existentially constrained terms are equivalent:
We have
$\CTerm{\varnothing}{\mathsf{f}(1,1)}{}{\m{true}}
\sim
\CTerm{\SET{x,y}}{\mathsf{f}(x,y)}{}{(x = y) \land (x = 1)}
\sim
\CTerm{\SET{y}}{\mathsf{f}(1,y)}{}{y = 1}
\sim \CTerm{\SET{x}}{\mathsf{f}(x,x)}{}{x = 1}$.
Moreover, the following subsumptions hold:
$\CTerm{\SET{x}}{\mathsf{f}(x,y)}{}{x = 1}
\subsetsim \CTerm{\SET{x}}{\mathsf{f}(x,y)}{}{x \ge 1}$,
$\CTerm{\SET{x}}{\mathsf{f}(x,x)}{}{}
\subsetsim \CTerm{\SET{x,y}}{\allowbreak\mathsf{f}(x,y)}{}{}$, and
$\CTerm{\SET{x,y}}{\mathsf{f}(x,y)}{}{}
\subsetsim \CTerm{\SET{x}}{\mathsf{f}(x,y)}{}{}$.
However, equivalence does not hold for any these.
\end{example}

We define satisfiability of existentially constrained terms.
%, which ensures the existence of their instances.

\begin{definition}[Satifiability of Existentially Constrained Terms]
An existentially constrained term $\CTerm{X}{s}{\vec{x}}{\varphi}$ is said to be \emph{satisfiable} if 
$\ECO{\vec{x}}{\varphi}$ is satisfiable.
\end{definition}

Below, we often focus on characterizations of equivalence 
for \emph{satisfiable} existentially constrained terms.
%, i.e.,  we only consider existentially constrained terms 
%that have at least one instance.
However, since all unsatisfiable existentially constrained terms are equivalent,
this is no restriction.

The following lemma on satisfiable existentially constrained terms turns out 
to be very useful in later proofs.

\begin{restatable}{lemma}{LemmaBasicPropertiesOfXvaluedSubstitution}
\label{lem:basic-properties-of-X-valued-substitutions}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term.
Then, there exists an $X$-valued substitution $\gamma$ such that 
%$\xM \vDash (\ECO{\vec{x}}{\varphi})\gamma$ 
$\gamma \vDash_\xM \ECO{\vec{x}}{\varphi}$,  $\Dom(\gamma) = X$,
and $\Pos(s) = \Pos(s\gamma)$.
\end{restatable}

\begin{proof}
By assumption, 
the constraint $\ECO{\vec{x}}{\varphi}$ is satisfiable.
Thus, there exists a valuation $\rho$ such that 
$\vDash_{\xM,\rho} \ECO{\vec{x}}{\varphi}$.
Take a substitution $\gamma := \rho|_{X}$.
\qed
\end{proof}

