We start with a sufficient condition for equivalence of 
existentially constrained terms consisting of renamed variants.

\begin{restatable}{lemma}{LemmaIIIxxi}
\label{lem:equivalence by renaming}
%%%
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$, $\CTerm{Y}{t}{\vec{y}}{\psi}$ be
existentially constrained terms.
Suppose that there exists a renaming $\delta$
such that $s\delta = t$, $\delta(X) = Y$,
and $\vDash_\xM (\ECO{\vec{x}}{\varphi})\delta \Leftrightarrow (\ECO{\vec{y}}{\psi})$.
Then, $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$.
%%%
\end{restatable}

\begin{proof}
As $\delta$ is a bijection, we can take the inverse renaming by $\delta^{-1}$. 
From the condition,
we have $t = s\delta^{-1}$, $Y = \delta^{-1}(X)$,
and $\vDash_\xM (\ECO{\vec{y}}{\psi})\delta^{-1}  \Leftrightarrow (\ECO{\vec{x}}{\varphi})$.
By symmetricity of the definition of equivalence,
it suffices to prove 
$\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{\SET{ x\delta \mid x \in X }}{s\delta}{}{(\ECO{\vec{x}}{\varphi})\delta}$.
%Consider an existentially constrained term $\CTerm{X}{s}{\vec{x}}{\varphi}$ and a renaming $\delta$.
Fix an $X$-valued substitution $\sigma$ with 
$\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$. 
Let us define the substitution $\gamma := \sigma \circ \delta^{-1}$.
Then one can show that $\gamma$ is $Y$-valued, 
$\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$ and $s\sigma = t\gamma$. 
\qed
\end{proof}

\begin{example} 
\label{ex:equivalence of renamed terms}
%Let $\mathsf{f} \in \xFTe$.
\Cref{lem:equivalence by renaming}
gives that 
$\CTerm{\SET{x}}{\mathsf{f}(x,y)}{}{x \ge 0}
\sim\CTerm{\SET{y}}{\mathsf{f}(y,x)}{}{y \ge 0}$
using a renaming $\delta = \{ x \mapsto y, y \mapsto x \}$.
Also
$\CTerm{\SET{x}}{\mathsf{f}(x,y)}{z}{x = z + z}
\sim\CTerm{\SET{x}}{\mathsf{f}(x,y)}{}{(x \mod 2) = 0}$ holds.
However, \Cref{lem:equivalence by renaming} does 
not imply any of the equivalences
in \Cref{ex:subsumption and equivalence}.
\end{example}


