The following lemma proving well-definedness of the
PG-transformation can be shown in a straightforward manner.

\begin{restatable}{lemma}{LemmaBasicPropertiesOfPG}
\label{lem:basic-properties-of-PG}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be an existentially constrained term.
Then, both of the following statements hold:
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item
%\Bfnum{1.}
    $\PG(\CTerm{X}{s}{\vec{x}}{\varphi})$ is a pattern-general existentially constrained term, 
        and
    \item
%\Bfnum{2.}
    if $\CTerm{X}{s}{\vec{x}}{\varphi}$ is satisfiable, then so is $\PG(\CTerm{X}{s}{\vec{x}}{\varphi})$.
\end{enumerate}
\end{restatable}

The following theorem states the correctness of the PG-transformation.

%\begin{restatable}{lemma}{LemmaCorrectnessOfPG}
\begin{restatable}{theorem}{TheoremCorrectnessOfPG}
%\label{lem:correctness-of-PG}
\label{thm:correctness-of-PG}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be an existentially constrained term.
Then, we have $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \PG(\CTerm{X}{s}{\vec{x}}{\varphi})$.
\end{restatable}

\begin{proof}
Let $\Pos_{X\cup\Val}(s) = \SET{p_1,\ldots,p_n}$ and $\PG(\CTerm{X}{s}{\vec{x}}{\varphi}) = \CTerm{Y}{t}{\vec{y}}{\psi}$
where
%\begin{itemize}
%    \item 
$w_1,\ldots,w_n$ are pairwise distinct fresh variables, 
%    \item 
$t = s[w_1,\ldots,w_n]_{p_1,\ldots,p_n}$, 
%    \item 
$Y = \SET{w_1,\ldots,w_n}$,
%    \item 
$\SET{\vec{y}} = \SET{\vec{x}} \cup X$,
        and
%    \item 
$\psi = (\varphi \land \bigwedge_{i=1}^n (s|_{p_i} = w_i))$.
%\end{itemize}
%We prove $\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$ 
%and $\CTerm{X}{s}{\vec{x}}{\varphi} \supsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$ one after another.
($\subsetsim$)
Let $\sigma$ be an $X$-valued substitution such that 
$\sigma \vDash_{\xM} \ECO{\vec{x}}{\varphi}$. 
Take a substitution $\gamma = \sigma \circ \SET{ w_i \mapsto s|_{p_i} \mid 1  \le i \le n }$.
Then, we can show that $\gamma$ is $Y$-valued,
$\gamma \vDash_{\xM} \ECO{\vec{y}}{\psi}$,
and $t\gamma = s\sigma$.
($\supsetsim$)
Let $\gamma$ be a $Y$-valued substitution such that 
$\gamma \vDash_{\xM} \ECO{\vec{y}}{\psi}$. 
Then, 
there exists $\vec{v} \in \Val^*$
such that $\vDash_{\xM} \psi\kappa\gamma$,
where $\kappa = \SET{\vec{y} \mapsto \vec{v}}$.
Take $\sigma = \gamma \circ \kappa|_{X}$.
Then, one can show $\sigma$ is $X$-valued,
$\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$,
$s\sigma = t\gamma$.
\qed
\end{proof}

