We are now ready to present a characterization 
of equivalence of satisfiable pattern-general existentially constrained terms.

\begin{restatable}{theorem}{TheoremIIIxxviii} % from PPL
\label{thm:complete characterization of equivalence for most sim-general constrained terms}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}, \CTerm{Y}{t}{\vec{y}}{\psi}$ be 
satisfiable pattern-general existentially constrained terms.
Then, $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$ if and only if there exists a renaming $\rho$ such that
%\begin{itemize}
%    \item
    $s\rho = t$,
%    \item for any variable $x$, $x \in X$ if and only if $\rho(x) \in Y$,
%    \item
    $\rho(X) = Y$,    
        and
%    \item 
    $\vDash_\xM (\ECO{\vec{x}}{\varphi})\rho \Leftrightarrow (\ECO{\vec{y}}{\psi})$.
%\end{itemize}
\end{restatable}

\begin{proof}
The \textit{if} part follows from \Cref{lem:equivalence by renaming}.
We show the \textit{only-if} part.
%%
By our assumption,
no value appears in $s$ or $t$ and hence $\Pos_{\Val}(s) = \Pos_{\Val}(t) = \varnothing$.
Using \Cref{lem:basic-derived-properties-of-equivalence},
let $\SET{p_1,\ldots,p_n} = \Pos_{X}(s) =\Pos_{Y}(t)$,
and $s|_{p_i} = z_i$ and $t|_{p_i} = w_i$ for $1 \leqslant i \leqslant n$.
As $\CTerm{X}{s}{\vec{x}}{\varphi}$ and $\CTerm{Y}{t}{\vec{y}}{\psi}$ are pattern-general,
$z_1,\ldots,z_n$ are pairwise distinct variables, and so are $w_1,\ldots,w_n$.
%
Let $\rho = \theta \cup \SET{ z_i \mapsto w_i \mid 1 \leq i \leq n}$.
Since $\theta$ is a renaming,
$\SET{z_1,\ldots,z_n} \cap (\Var(s) \setminus X) = \varnothing$, and
$\SET{w_1,\ldots,w_n} \cap (\Var(t) \setminus Y) = \varnothing$,
we know $\rho$ is well-defined and renaming.
%
Furthermore, $s\rho = (s[z_1,\ldots,z_n]_{p_1,\ldots,p_n})\rho 
= s\rho[z_1\rho,\ldots,z_n\rho]_{p_1,\ldots,p_n} 
= s\theta[w_1,\ldots,w_n]_{p_1,\ldots,p_n} 
= t[w_1,\ldots,w_n]_{p_1,\ldots,p_n} = t$.
%
The rest of the statements follow 
from this by \Cref{thm: characterization of equivalence using renaming}.
\qed
\end{proof}

\begin{example} 
\label{ex:equivalence of pattern-general terms}
Recall the equivalent existentially constrained terms 
of \Cref{ex:subsumption and equivalence}.
By applying the PG-transformation to each them, we obtain the following:
\[
\begin{array}{l}
\PG(\CTerm{\varnothing}{\mathsf{f}(1,1)}{}{}) 
= \CTerm{\SET{w_1,w_2}}{\mathsf{f}(w_1,w_2)}{}{(1 = w_1) \land (1 = w_2})\\
\PG(\CTerm{\SET{x,y}}{\mathsf{f}(x,y)}{x,y}{(x = y) \land (x = 1)})\\
\quad = \CTerm{\SET{w_1,w_2}}{\mathsf{f}(w_1,w_2)}{x,y}{(x = y) \land (x = 1) \land (x = w_1) \land (y = w_2})\\
\PG(\CTerm{\SET{y}}{\mathsf{f}(1,y)}{}{y = 1})\\
\quad = \CTerm{\SET{w_1,w_2}}{\mathsf{f}(w_1,w_2)}{y}{(y = 1) \land (1 = w_1) \land (y = w_2})\\
\PG(\CTerm{\SET{x}}{\mathsf{f}(x,x)}{}{x = 1})\\
\quad = \CTerm{\SET{w_1,w_2}}{\mathsf{f}(w_1,w_2)}{x}{(x = 1) \land (x = w_1) \land (x = w_2})
\end{array}
\]
It becomes trivial to see the equivalence of these terms by
\Cref{thm:complete characterization of equivalence for most sim-general constrained terms},
as all of these constraints are logically equivalent.
\end{example}

Together with \Cref{thm:correctness-of-PG},
we have a sound and complete characterization of equivalence
of satisfiable existentially constrained terms.

\begin{corollary}
\label{cor:sound and complete characterization of equivalence for PG terms}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}, \CTerm{Y}{t}{\vec{y}}{\psi}$ be 
satisfiable existentially constrained terms.
Then, $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$ if and only if 
there exists a renaming $\rho$ such that
    $s'\rho = t'$,
    $\rho(X') = Y'$,    
        and
    $\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\rho \Leftrightarrow (\ECO{\pvec{y}'}{\psi'})$,
where $\PG(\CTerm{X}{s}{\vec{x}}{\varphi}) = \CTerm{X'}{s'}{\pvec{x}'}{\varphi'})$
and $\PG(\CTerm{Y}{t}{\vec{y}}{\psi}) = \CTerm{Y'}{t'}{\pvec{y}'}{\psi'})$.
\end{corollary}

Transformations of non-existentially constrained terms into \emph{value-free} ones can be seen in~\cite{Kop17,KN24jip}.
The PG-transformation in this section is an extension to that of existentially constrained terms into pattern-general ones (i.e., not only value-free but also LV-linear ones).

%\section{Characterizing Equivalence of Existentially Constrained Terms III}
\section{General Characterization of Equivalence}
\label{sec:general-characterization-of-equivalence}

To check the equivalence of existentially constrained terms, it is often
convenient to apply the PG transformation and
use \Cref{thm:complete characterization of equivalence for most sim-general constrained terms}. However, in a theoretical analysis, one frequently needs to handle the
equivalence of non-pattern-general terms as well, where the PG transformation is
less suitable. Therefore, a general criterion for the equivalence of
existentially constrained terms is preferred.

In this section, we generalize \Cref{thm:complete characterization of
equivalence for most sim-general constrained terms} to arbitrary existentially
constrained terms, i.e., we characterize equivalence of existentially
constrained terms which are not assumed to be pattern-general. To this end, we
introduce new notions and notations.

\begin{definition} % from PPL
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be an existentially constrained term.
Then, we define a binary relation $\sim_{\Pos_{X\cup \Val}(s)}$ over the positions in $\Pos_{X\cup \Val}(s)$ as follows:
$p \sim_{\Pos_{X\cup \Val}(s)} q$
if and only if
$\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = s|_q)$.
\end{definition}
We may omit the subscript $\Pos_{X\cup\Val}(s)$ of $\sim_{\Pos_{X\cup \Val}(s)}$ if it is clear from the context.

\begin{example}
\label{ex:sim over positions of X U Val}
Consider an existentially constrained term
$\CTerm{X}{s}{}{\varphi}$
where $X = \SET{x,x',y,y'}$, 
$s = \m{h}(x,x',0,y,y,y',0 \times 10)$ with $\m{h} \in \xFTe$, 
and $\varphi = (x = x') \land (x' = 0) \land (y = y')$.
Then, $\Pos_{X\cup \Val}(s) = \SET{1,2,3,4,5,6,7.1,7.2}$
and we have $1 \sim 2 \sim 3 \sim 7.1$ and $4 \sim 5 \sim 6$.
\end{example}

The proof of the following lemma is straightforward.

\begin{restatable}{lemma}{LemPropertiesOfEquivalenceOverXvarValPositions} % from PPL
\label{lem:properties-of-equivalence-over-X-var-val-positions}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be an existentially constrained term. Then,
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item $\sim_{\Pos_{X\cup \Val}(s)}$ is an equivalence relation over the positions in $\Pos_{X\cup \Val}(s)$,
        and
    \item for any positions $p,q \in \Pos_{X\cup \Val}(s)$, if $s|_p = s|_q$, then $p \sim_{\Pos_{X\cup \Val}(s)} q$.
\end{enumerate}
\end{restatable}


