As mechanism to instantiate the term part of an existentially constrained term by
values under the equivalence, we introduce representative
substitutions.

\begin{definition} % from PPL
\label{def:representative substituions}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term.
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
\item For each $p \in \Pos_{\Val!}(s)$,  there exists a unique value $v$
    such that $\xM \vDash (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_p = v)$
    by \Cref{lem:properties-of-PosValExcl}.
    We denote such $v$ by $\Val!(p)$.
\item We define a 
\emph{representative substitution} $\mu_{X}: X \to X \cup \Val$ of 
$\CTerm{X}{s}{\vec{x}}{\varphi}$ as follows:
\[
\mu_{X}(z) = 
\left\{
\begin{array}{ll}
\Val!(p) & \mbox{if $s(p) = z$ for some $p \in \Pos_{\Val!}(s)$},\\
s(\hat{p}) & \mbox{otherwise},
\end{array}
\right.
\]
where $\hat{p}$ is the representative of the equivalence class $[p]_\sim$.
Here note that if $s(p) = z$ for some $p \in \Pos_{\Val!}(s)$,
then $q \in \Pos_{\Val!}(s)$ for any $q$ such that $s(q) = z$
by \Cref{lem:properties-of-PosValExcl}~\Bfnum{2}.

%\NN{Since $X \subseteq \Var(s)$, 
%there exists at least one position $p \in \Pos_X(s)$ such that $s|_p = z$.}

\item
Provided it is clear from the contexts, 
for simplicity, we shorten $\mu_{X}(x)$ by $\hat{x}$ and so does $\mu_{X}(X)$ by $\hat{X}$.
We also put $\hat{v} = v$ for $v \in \Val$.
\end{enumerate}
\end{definition}

\begin{example}[Cont'd from \Cref{ex:presentative of sim-equivalence class over positions of X U Val}]
\label{ex:representative substituions}
We have $\Val!(p) = 0 \in \Val$ for $p \in \SET{1,2,3,7.1}$,
and $\Val!(7.2) = 10 \in \Val$.
Since $X = \SET{x,x',y,y'}$, the representative substitution is
$\mu_{X} = \SET{ x \mapsto 0, x' \mapsto 0, y \mapsto y, y' \mapsto y }$
and $\hat{X} = \SET{1,y}$.
\end{example}

\begin{example}[Cont'd from \Cref{ex:representative substituions}]
\label{ex:equivalence for general case II}
Let $\CTerm{Y}{t}{}{\psi}$ be another existentially constrained term
such that $Y=\SET{x,x',y,z}$, $t = \m{h}(z,z,z,x,x',x,z \times y)$, 
and $\psi = ((x \le x') \land (x' \le x) \land (z = 0) \land (y = (z + 2) \times 5))$.
Then, we have $\CTerm{X}{s}{}{\varphi} \sim \CTerm{Y}{t}{}{\psi}$.
Let us see how this equivalence can be observed using our notions.
We have 
$\Pos_{X\cup \Val}(s) = \SET{1,2,3,4,5,6,7.1,7.2} = \Pos_{X\cup \Val}(t)$,
${\sim}_{\Pos_{X\cup \Val}(s)} = {\sim}_{\Pos_{Y\cup \Val}(t)}$,
and $\Pos_{\Val!}(s) = \Pos_{\Val!}(t)$.
Let $1$ and $4$ be representatives of $\SET{1,2,3,7.2}$ and $\SET{4,5,6}$.
Then, we have 
$\mu_{X} = \SET{ x \mapsto 0, x' \mapsto 0, y \mapsto y, y' \mapsto y }$
and
$\mu_{Y} = \SET{ x \mapsto x, x' \mapsto x, y \mapsto 10, z \mapsto 0 }$.
We also have 
$\varphi\mu_X = ((0 = 0) \land (0 = 0) \land (y = y))$ and
$\psi\mu_Y = ((x \le x) \land (x \le x) \land (0 = 0) \land (10 = (0 + 2) \times 5))$.
The remaining key is the correspondence
between the sets $\hat X \cap X = \{ y \}$ and $\hat Y \cap Y = \{ z \}$.
\end{example}


