\end{restatable}

\begin{proof}
Let $\PG(\CTerm{X}{s}{\vec{x}}{\varphi}) 
= (\CTerm{W}{s[w_1,\ldots,w_n]_{p_1,\ldots,p_n}}{\pvec{x}'}{\varphi'})$
and
$\PG(\CTerm{Y}{t}{\vec{y}}{\psi}) 
= (\CTerm{W'}{t[w'_1,\ldots,w'_n]_{p_1,\ldots,p_n}}{\pvec{y}'}{\psi'})$, 
where we let
$W = \SET{w_1,\ldots,w_n}$,
$\SET{\pvec{x}'} = \SET{\vec{x}}\cup X$,
$\varphi' = (\varphi \land \bigwedge_{i=1}^n (w_i = s|_{p_i}))$,
$W' = \SET{w_1',\ldots,w_n'}$,
$\SET{\pvec{y}'} = \SET{\vec{y}}\cup Y$,
and
$\psi' = (\psi \land \bigwedge_{i=1}^n (w'_i = t|_{p_i}))$.
Then, by our assumption and \Cref{thm:correctness-of-PG}, we have
\[
(\CTerm{W}{s[w_1,\ldots,w_n]_{p_1,\ldots,p_n}}{\pvec{x}'}{\varphi'})
\sim
(\CTerm{W}{t[w'_1,\ldots,w'_n]_{p_1,\ldots,p_n}}{\pvec{y}'}{\psi'}). 
\]
By \Cref{thm:complete characterization of equivalence for most sim-general constrained terms}, 
there is a renaming $\delta$ such that 
$s[w_1,\ldots,w_n]\delta = t[w_1',\ldots,w_n']$
and $\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\delta \Leftrightarrow \ECO{\pvec{y}'}{\psi'}$.
Thus, $\delta(w_i) = w_i'$. 
Then, using \Cref{lem:X or val subterms equality from constraints}~\Bfnum{1},
\[
\begin{array}{lcl}
 \vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_{p_i} = s|_{p_j})
&\iff& \vDash_\xM (\ECO{\pvec{x}'}{\varphi'}) \Rightarrow (w_i = w_j)\\
&\iff& \vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\delta \Rightarrow (w_i\delta = w_j\delta) \\
&\iff& \vDash_\xM (\ECO{\pvec{y}'}{\psi'}) \Rightarrow (w_i' = w_j')\\
&\iff& \vDash_\xM (\ECO{\pvec{y}}{\psi}) \Rightarrow (t|_{p_i} = t|_{p_j})\\
\end{array}
\]
This proves~\Bfnum{1}. 
\Bfnum{2} follows similarly, by
using \Cref{lem:X or val subterms equality from constraints}~\Bfnum{2}.
%From \Bfnum{1}, it follows ${\sim}_{\Pos_{X\cup \Val}(s)} = {\sim}_{\Pos_{X\cup \Val}(t)}$.
%%%
In order to show~\Bfnum{3}, take $\theta = \SET{ \langle s|_{p_i}, t|_{p_i} \rangle \mid 1 \le i \le n }$.
Then, by~\Bfnum{1},\,\Bfnum{2}, and our assumption, we have
\begin{itemize}
\item $\mu_X(s|_{p_i}) \in \Val$ if and only if  $\mu_Y(t|_{p_i}) \in \Val$, and moreover, 
\item $s|_{p_i} \in \tilde{X}$ if and only if $p_i$ is a representative of an equivalence class $[p_i]$
if and only if $t|_{p_i} \in \tilde{Y}$.
\end{itemize}
Thus, 
$\{ \langle s|_{p_i}, t|_{p_i} \rangle \mid
p_i$ is a representative of an equivalence class 
$[p_i]$ such that $\mu_X(s|_{p_i}) \notin \Val \} = \theta|_{\tilde{X}}$
is a renaming from $\tilde{X}$ to $\tilde{Y}$.
%%
Take an arbitrary but fixed function $\theta': X \to Y$
such that $\theta'(s|_{p_i}) \in \SET{ t|_{p_j} \mid p_i \sim p_j }$.
Then (i) $\theta|_{\tilde{X}}(\mu_X(s|_{p_i})) = \theta|_{\tilde{X}}(s|_{\hat{p_i}}))) 
= t|_{\hat{p_i}} = \mu_Y(t|_{p_j}) = \mu_Y(\theta'(s|_{p_i}))$.
%%
Let $\sigma = \SET{ w_1 \mapsto s|_{p_1},\ldots, w_n \mapsto s|_{p_n}}$
and
$\sigma' = \SET{ w'_1 \mapsto t|_{p_1},\ldots, w'_n \mapsto t|_{p_n}}$.
Then, we have
(ii) $\mu_Y(\theta'(\sigma(w_i)))
= \mu_Y(\theta'(s|_{p_i}))
= \mu_Y(t|_{p_j})
= t|_{\hat{p_i}}
= \mu_Y(t|_{p_i})
= \mu_Y(\sigma'(w_i'))
= \mu_Y(\sigma'(\delta(w_i)))$.
Thus, for any valuation $\rho$,
\[
\begin{array}{lcl@{\qquad}l}
 \vDash_{\xM,\rho} (\ECO{\vec{x}}{\varphi})\mu_X\theta|_{\tilde{X}}
&\iff& \vDash_{\xM,\rho} (\ECO{\pvec{x}'}{\varphi'})\sigma\mu_X\theta|_{\tilde{X}}
& \mbox{by \Cref{lem:induced-validity-of-representative-substitutions}}\\
&\iff& \vDash_{\xM,\rho} (\ECO{\pvec{x}'}{\varphi'})\sigma\theta'\mu_Y
& \mbox{by (i)}\\
&\iff& \vDash_{\xM,\rho}(\ECO{\pvec{x}'}{\varphi'})\delta\sigma'\mu_Y
& \mbox{by (ii)}\\
&\iff& \vDash_{\xM,\rho} (\ECO{\pvec{y}'}{\psi'})\sigma'\mu_Y
& \mbox{by \Cref{lem:induced-validity-of-representative-substitutions}}\\
&\iff& \vDash_{\xM,\rho} (\ECO{\pvec{y}}{\psi}) \mu_Y
\end{array}
\]
Thus, 
$\vDash_{\xM} (\ECO{\vec{x}}{\varphi})\mu_X\theta|_{\tilde{X}} \Leftrightarrow (\ECO{\pvec{y}}{\psi}) \mu_Y$.
\qed
\end{proof}


We finally arrive at a general characterization of equivalence.

\begin{restatable}{theorem}{ThmCompleteCharacterizatinOfEquivalenceOfConstrainedTerms} % from PPL
\label{thm:complete characterizatin of equivalence of constrained terms}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}, \CTerm{Y}{t}{\vec{y}}{\psi}$ be satisfiable existentially constrained terms, and $\Pos_{X\cup\Val}(s) = \SET{p_1,\ldots,p_n}$.
Then, $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$
if and only if
the following statements hold:
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item $\Pos_{X\cup\Val}(s) = \Pos_{Y\cup\Val}(t)$,
    \item there exists a renaming $\rho \colon \Var(s) \setminus X \to \Var(t) \setminus Y$ such that 
    $\rho(s[\,]_{p_1,\ldots,p_n}) = t[\,]_{p_1,\ldots,p_n}$,
%    (i.e., $t[\,]_{p_1,\ldots,p_n}$ is a renamed variant of $s[\,]_{p_1,\ldots,p_n}$),
    \item for any $i,j \in \SET{1,\ldots,n}$, 
        $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_{p_i} = s|_{p_j})$
        if and only if 
        $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (t|_{p_i} = t|_{p_j})$,
    \item for any $i \in \SET{1,\ldots,n}$ and $v \in \Val$, 
        $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_{p_i} = v)$
        if and only if 
        $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (t|_{p_i} = v)$,
        and
    \item
    let ${\sim} = {\sim}_{\Pos_{X\cup \Val}(s)} = {\sim}_{\Pos_{X\cup \Val}(t)}$, 
    and $\mu_X,\mu_Y$ be representative substitutions of
     $\CTerm{X}{s}{\vec{x}}{\varphi}$ and $\CTerm{Y}{t}{\vec{y}}{\psi}$, respectively, 
    based on the same representative for
    each equivalence class $[p_i]_\sim$ ($1 \le i \le n$), and
    we have 
    $\vDash_\xM (\ECO{\vec{x}}{\varphi})\mu_X\theta|_{\tilde{X}}
    \Leftrightarrow (\ECO{\vec{y}}{\psi})\mu_Y$
    with a renaming $\theta|_{\tilde{X}} \colon \tilde{X} \to \tilde{Y}$,
    where $\theta =  \SET{ \langle s|_{p_i}, t|_{p_i} \rangle \mid 1 \le i \le n }$,
    $\tilde{X} = \hat{X} \cap X$, and $\tilde{Y} = \hat{Y}\cap Y$.
\end{enumerate}
\end{restatable}

\begin{proof}[Sketch]
The \textit{only-if} part follows \Cref{lem:basic-derived-properties-of-equivalence} 
and \Cref{lem:induced-propertis-of-equivalence}.
The \textit{if} part is shown by applying the PG-transformation
to $\CTerm{X}{s}{\vec{x}}{\varphi}$ and $\CTerm{Y}{t}{\vec{y}}{\psi}$,
and using \Cref{thm:complete characterization of equivalence for most sim-general constrained terms}.
For this 
\Cref{lem:induced-equalities-of-expliciit-substitutions}
and 
\Cref{lem:induced-propertis-of-equivalence}
are needed.
\qed
