\LemCorrespondence*

\begin{proof}
($\Longrightarrow$)
Suppose $s~\CO{\varphi} \sim t~\CO{\psi}$.
Let 
$X = \Var(s) \cap \Var(\varphi)$,
$\SET{\vec{x}} = \Var(\varphi) \setminus\Var(s)$,
$Y = \Var(t) \cap \Var(\psi)$, and
$\SET{\vec{y}} = \Var(\psi) \setminus\Var(t)$.
Then, obviously
$\CTerm{X}{s}{\vec{x}}{\varphi}$
and $\CTerm{Y}{t}{\vec{y}}{\psi}$ are
existentially constrained terms.
%
We show
$\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$.
The other direction $\CTerm{X}{s}{\vec{x}}{\varphi} \supsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$
follows similarly.
%
Let $\sigma$ be an $X$-valued substitution such that
$\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$.
Then $\sigma(\FVar(\ECO{\vec{x}}{\varphi})) \subseteq \Val$
and $\vDash_\xM \varphi\kappa\sigma$ with $\kappa = \{ \vec{x} \mapsto \vec{v} \}$.
Then $\sigma \circ \kappa \vDash_\xM \varphi$,
and by our assumption there exists a substitution $\gamma$
such that $\gamma \vDash_\xM \psi$ and $s\kappa\sigma = t\gamma$.
Since $\SET{\vec{x}} \cap \Var(s) = \varnothing$ and $\vec{v} \in \Val^*$,
we have $s\sigma = s\kappa\sigma = t\gamma$.
From $\gamma \vDash_\xM \psi$, we know $\gamma(\Var(\psi)) \subseteq \Val$.
As $\FVar(\ECO{\vec{y}}{\psi}) \subseteq \Var(\psi)$, we have $\gamma(\FVar(\psi)) \subseteq \Val$.
Furthermore, it follows from $\vDash_\xM \psi\gamma$ that $\vDash_\xM (\ECO{\vec{y}}{\psi})\gamma$.
This concludes $\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$.

\noindent
($\Longleftarrow$)
Suppose 
$\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$
where 
$X = \Var(s) \cap \Var(\varphi)$,
$\SET{\vec{x}} = \Var(\varphi) \setminus\Var(s)$,
$Y = \Var(t) \cap \Var(\psi)$, and
$\SET{\vec{y}} = \Var(\psi) \setminus\Var(t)$.
%%
We show $s~\CO{\varphi} \subsetsim t~\CO{\psi}$.
As before the other direction $s~\CO{\varphi} \supsetsim t~\CO{\psi}$ follows similarly.
%
Let $\sigma$ be substitution $\sigma \vDash_\xM \varphi$.
Then, since $\FVar(\ECO{\vec{x}}{\varphi}) \subseteq \Var(\varphi)$
and $\vDash_\xM \varphi\sigma$ implies 
$\vDash_\xM (\ECO{\vec{x}}{\varphi})\sigma$,
we obtain $\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$.
Also, by $X = \Var(s) \cap \Var(\varphi) \subseteq \Var(\varphi)$, 
it follows that $\sigma$ is $X$-valued.
By our assumption
there exists a $Y$-valued substitution $\gamma$ such that
$\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$ and $s\sigma = t\gamma$.
Thus, 
$\vDash_\xM \psi\kappa\gamma$ with $\kappa = \{ \vec{y} \mapsto \vec{v} \}$
with some $\vec{v} \in \Val^*$.
Then, by $\SET{\vec{y}} \cap \Var(t) = \varnothing$ and $\vec{v} \in \Val^*$,
$s\sigma = t\gamma = t\kappa\gamma = t (\gamma \circ \kappa)$.
Also, we have
$\Var(\psi) = (\Var(\psi) \cap \Var(t)) \cup (\Var(\psi) \setminus\Var(t)) 
= Y \cup \SET{\vec{y}} \subseteq \VDom(\gamma \circ \kappa)$,
i.e.\ $(\gamma \circ \kappa)(\Var(\psi) \subseteq \Val$.
From all of this we obtain $\gamma \circ \kappa \vDash_\xM \psi$.
\qed
\end{proof}

