\LemmaIIIxxi*
\begin{proof}
As $\delta$ is a bijection, we can take the inverse renaming by $\delta^{-1}$. 
From the condition,
we have $t = s\delta^{-1}$, $Y = \delta^{-1}(X)$,
and $\vDash_\xM (\ECO{\vec{y}}{\psi})\delta^{-1}  \Leftrightarrow (\ECO{\vec{x}}{\varphi})$.
By symmetricity of the definition of equivalence,
it suffices to prove 
$\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{\SET{ x\delta \mid x \in X }}{s\delta}{}{(\ECO{\vec{x}}{\varphi})\delta}$.
%As $\delta$ is a bijection, we can take the inverse renaming by $\delta^{-1}$. 
%From the condition,
%we have $t = s\delta^{-1}$, $Y = \delta^{-1}(X)$,
%and $\vDash_\xM (\ECO{\vec{y}}{\psi})\delta^{-1}  \Leftrightarrow (\ECO{\vec{x}}{\varphi})$.
%Since the second condition in \Cref{def:equivalence-constrained-terms} is symmetric,
%it suffices to prove 
%that the first condition in \Cref{def:equivalence-constrained-terms} holds
%to conclude 
%$\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{\SET{ x\delta \mid x \in X }}{s\delta}{}{(\ECO{\vec{x}}{\varphi})\delta}$.
%Consider an existentially constrained term $\CTerm{X}{s}{\vec{x}}{\varphi}$ and a renaming $\delta$.
Fix an $X$-valued substitution $\sigma$ with 
$\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$. 
Let us define the substitution $\gamma := \sigma \circ \delta^{-1}$.
We now show that $\gamma$ is $Y$-valued, 
$\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$ and $s\sigma = t\gamma$. 
%
Let $y \in Y$. Then, by $Y = \delta(X)$, there exists $x \in X$ such that $\delta(x) = y$.
Hence, as $\sigma$ is $X$-valued,
$y\gamma = x\delta\gamma 
= x\delta\delta^{-1}\sigma = x\sigma \in \Val$.
Thus, we know that $\gamma$ is $Y$-valued.
%
From $\sigma \vDash_\xM \ECO{\vec{x}}{\varphi}$,
it follows $\vDash_\xM (\ECO{\vec{x}}{\varphi})\sigma$.
Hence, by $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Leftrightarrow (\ECO{\vec{y}}{\psi})\delta^{-1}$,
we obtain $\vDash_\xM  (\ECO{\vec{y}}{\psi})\delta^{-1}\sigma$.
Therefore,  $\vDash_\xM  (\ECO{\vec{y}}{\psi})\gamma$.
Since $\FVar(\ECO{\vec{y}}{\psi}) \subseteq Y$ and 
$\gamma$ is $Y$-valued,  it follows $\gamma \vDash_\xM \ECO{\vec{y}}{\psi}$.
Finally, 
$t\gamma = (s\delta)\gamma = s\gamma\delta = s\sigma$.
%
\qed
\end{proof}

