    \item $t = s[w_1,\ldots,w_n]_{p_1,\ldots,p_n}$, 
    \item $Y = \SET{w_1,\ldots,w_n}$,
    \item $\SET{\vec{y}} = \SET{\vec{x}} \cup X$,
