\TheoremCorrectnessOfPG*
\begin{proof}
Let $\Pos_{X\cup\Val}(s) = \SET{p_1,\ldots,p_n}$ and $\PG(\CTerm{X}{s}{\vec{x}}{\varphi}) = \CTerm{Y}{t}{\vec{y}}{\psi}$
where
\begin{itemize}
    \item $w_1,\ldots,w_n$ are pairwise distinct fresh variables, 
    \item $t = s[w_1,\ldots,w_n]_{p_1,\ldots,p_n}$, 
    \item $Y = \SET{w_1,\ldots,w_n}$,
    \item $\SET{\vec{y}} = \SET{\vec{x}} \cup X$,
        and
    \item $\psi = (\varphi \land \bigwedge_{i=1}^n (s|_{p_i} = w_i))$.
\end{itemize}
We prove $\CTerm{X}{s}{\vec{x}}{\varphi} \subsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$ and $\CTerm{X}{s}{\vec{x}}{\varphi} \supsetsim \CTerm{Y}{t}{\vec{y}}{\psi}$ one after another.

($\subsetsim$)
Let $\sigma$ be an $X$-valued substitution such that 
$\sigma \vDash_{\xM} \ECO{\vec{x}}{\varphi}$. 
Then there exists $\vec{v} \in \Val^*$
such that $\vDash_{\xM} \varphi\kappa\sigma$,
where $\kappa = \SET{\vec{x} \mapsto \vec{v}}$.
Take $\sigma' = \sigma|_{X}$.
Then, since $\sigma(X) \subseteq \Val$,
we have a substitution $\kappa \cup \sigma'\colon \SET{\vec{x}} \cup X \to \Val$
such that $\vDash_{\xM} \varphi(\kappa \cup \sigma')\sigma$.
%
Take a substitution $\gamma = \sigma \circ \SET{ w_i \mapsto s|_{p_i} \mid 1  \le i \le n }$.
Then, we have $\gamma(w_i) = s|_{p_i}\sigma \in \Val$
as $s|_{p_i}\in X \cup \Val$ and $\sigma$ is $X$-valued.
Hence, $\gamma$ is $Y$-valued.
%
As $\FVar(\ECO{\vec{y}}{\psi}) \subseteq Y$,
$\gamma(\FVar(\ECO{\vec{y}}{\psi})) \subseteq \Val$ holds.
Also, by our assumption on $w_1,\ldots,w_n$,
it follows from $\vDash_{\xM} \varphi(\kappa \cup \sigma')\sigma$
that $\vDash_{\xM} \varphi(\kappa \cup \sigma')\gamma$.
Also, since 
$\bigwedge_{i=1}^n (s|_{p_i} = w_i))(\kappa \cup \sigma')\gamma
= \bigwedge_{i=1}^n (s|_{p_i}\sigma' = w_i))\gamma
= \bigwedge_{i=1}^n (s|_{p_i}\sigma = w_i\gamma))
= \bigwedge_{i=1}^n (s|_{p_i}\sigma = s|_{p_i}\sigma)$,
we have $\vDash_{\xM} \bigwedge_{i=1}^n (s|_{p_i} = w_i))(\kappa \cup \sigma')\gamma$.
Hence, $\vDash_{\xM} (\varphi \land \bigwedge_{i=1}^n (s|_{p_i} = w_i))(\kappa \cup \sigma')\gamma$,
and thus, $\vDash_{\xM} (\ECO{\vec{y}}{\psi})\gamma$ holds.
Therefore, together with $\gamma(\FVar(\ECO{\vec{y}}{\psi})) \subseteq \Val$,
we obtain $\gamma \vDash_{\xM} \ECO{\vec{y}}{\psi}$.
%
Finally, as $\Var(s) \cap \SET{\seq{w}} = \varnothing$,
we have $t\gamma = s[w_1,\ldots,w_n]_{\seq{p}}\gamma
= s\gamma[w_1\gamma,\ldots,w_n\gamma]_{\seq{p}}
= s\sigma[s|_{p_1}\sigma,\ldots,s|_{p_n}\sigma]_{\seq{p}}
= s\sigma$.
%%%

%%%
($\supsetsim$)
Let $\gamma$ be a $Y$-valued substitution such that 
$\gamma \vDash_{\xM} \ECO{\vec{y}}{\psi}$. 
Then, %$\gamma(\FVar(\ECO{\vec{y}}{\psi})) \subseteq \Val$, and 
there exists $\vec{v} \in \Val^*$
such that $\vDash_{\xM} \psi\kappa\gamma$,
where $\kappa = \SET{\vec{y} \mapsto \vec{v}}$.
Thus, in particular, we have
$\vDash_{\xM} \varphi\kappa\gamma$ and 
$\vDash_{\xM} (s|_{p_i} = w_i)\kappa\gamma$ for all $1 \le i \le n$.
%
As $\SET{\vec{y}} \cap \SET{\seq{w}} = \varnothing$,
and $s|_{p_i}\in X \cup \Val$ and $X \subseteq \SET{\vec{y}}$,
we have $(s|_{p_i} = w_i)\kappa\gamma = (s|_{p_i}\kappa = w_i\gamma)$.
As $s|_{p_i}\kappa, w_i\gamma \in \Val$,
it follows from $\vDash_{\xM} (s|_{p_i} = w_i)\kappa\gamma$
that $s|_{p_i}\kappa = w_i\gamma$.
%
Now, take $\kappa' = \kappa|_{\SET{\vec{x}}}$ and $\kappa'' = \kappa|_{X}$.
Then $\kappa = \kappa' \cup \kappa''$.
Also take $\sigma = \gamma \circ \kappa''$.
%
Firstly, we have $\sigma(s|_{p_i}) 
= s|_{p_i}\kappa''\gamma
= s|_{p_i}\kappa\gamma
= s|_{p_i}\kappa \in \Val$.
Thus, $\sigma$ is $X$-valued, as $X \subseteq \SET{s|_{p_i} \mid 1 \le i \le n}$.
