\land \bigwedge_{i=k+1}^n(v_i=w_i\sigma)})       \\
\iff& \vDash_{\xM,\rho} (\ECO{\vec{x},x_1',\ldots,x_k'}{\varphi \land \bigwedge_{i=1}^k(x_i'=x_i) 
\land \bigwedge_{i=k+1}^n(v_i=v_i)})       \\
\iff& \vDash_{\xM,\rho} (\ECO{\vec{x}}{\varphi})      \\
\end{array}
\]
