\LemmaIIIxix*
\begin{proof}
By definition, we have that $Y = \SET{ w_1,\ldots,w_n }$,
$\SET{\vec{y}} = \SET{\vec{x}} \cup X$, and
$\psi = (\varphi \land \bigwedge_{i=1}^n(s|_{p_i}=w_i))$.

\begin{enumerate}
\renewcommand{\labelenumi}{(\arabic{enumi})}

\item
($\Longrightarrow$)
Suppose 
$\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow s|_{p_i} = s_{p_j}$.
Let $\rho$ be valuation.
Suppose $\vDash_{\xM,\rho} \psi$, i.e., 
$\vDash_{\xM,\rho} \varphi \land \bigwedge_{i=1}^n(s|_{p_i}=w_i)$.
Then, in particular, we have $\vDash_{\xM,\rho} \varphi$
and $\vDash_{\xM,\rho} (s|_{p_i}=w_i) \land (s|_{p_j}=w_j)$.
Using our assumption, it follows from the former that
$\vDash_{\xM,\rho} (s|_{p_i} = s|_{p_j})$.
Then by the latter, we obtain $\vDash_{\xM,\rho} (w_i = w_j)$.
All in all, we have proved
$\vDash_{\xM,\rho} \psi \Rightarrow (w_i = w_j)$.
From this, 
$\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (w_i = w_j)$ follows.

($\Longleftarrow$)
Suppose $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (w_i = w_j)$.
Then $\vDash_\xM \psi \Rightarrow (w_i = w_j)$.
Take a substitution $\sigma = \SET{ w_i \mapsto s|_{p_i} \mid 1 \le i \le n }$.
Then we have $\vDash_\xM \psi\sigma \Rightarrow (w_i\sigma = w_j\sigma)$.
Hence 
$\vDash_\xM \varphi \land \bigwedge_{i=1}^n(s|_{p_i}=s|_{p_i})) \Rightarrow (s|_{p_i}=s|_{p_j})$.
Therefore,
$\vDash_\xM \varphi \Rightarrow (s|_{p_i}=s|_{p_j})$.

%%%
\item
($\Longrightarrow$)
Suppose $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_{p_i} = v)$.
Let $\rho$ be valuation.
Suppose $\vDash_{\xM,\rho} \psi$, i.e.\ 
$\vDash_{\xM,\rho} \varphi \land \bigwedge_{i=1}^n(s|_{p_i}=w_i)$.
Then, in particular, we have $\vDash_{\xM,\rho} \varphi$
and $\vDash_{\xM,\rho} (s|_{p_i}=w_i)$.
Using our assumption, it follows from the former that
$\vDash_{\xM,\rho} (s|_{p_i} = v)$.
Then by the latter, we obtain $\vDash_{\xM,\rho} (w_i = v)$.
All in all, we have proved that $\vDash_\xM \psi \Rightarrow (w_i = v)$.
From this, it follows $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (w_i = v)$.

($\Longleftarrow$)
Suppose $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (w_i = v)$.
Then $\vDash_\xM \psi \Rightarrow (w_i = v)$.
Take a substitution $\sigma = \SET{ w_i \mapsto s|_{p_i} \mid 1 \le i \le n }$.
Then we have $\vDash_\xM \psi\sigma \Rightarrow (w_i\sigma = v)$.
Hence 
$\vDash_\xM \varphi \land \bigwedge_{i=1}^n(s|_{p_i}=s|_{p_i})) \Rightarrow (s|_{p_i}=v)$.
Therefore,
$\vDash_\xM \varphi \Rightarrow (s|_{p_i}=v)$.
%%%
\qed
\end{enumerate}
\end{proof}



