\LemChacterizationOfPatternGeneral*
\begin{proof}
We prove the \textit{if} part by contradiction. Assume that $s$ is most general
in $\SET{ t \mid \CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}
}$ and $\CTerm{X}{s}{\vec{x}}{\varphi}$ is not pattern-general (i.e., $s$ is
not linear w.r.t.\ $X$ or a value $c$ appears in $s$). We proceed by case analysis
on whether $s$ is linear w.r.t.\ $X$:
\begin{itemize}
    \item Assume $s$ is linear w.r.t.\ $X$.
    In this case, a value $c$ appears in $s$.
    Let $s = s[c]_p$ for some position $p$ in $s$.
    Let $s' = s[y]_p$ for some fresh variable $y$.
    Then, $\CTerm{X}{s'}{\vec{x}}{\varphi\land(y = c)}$ is an existentially constrained term.
    By definition, it is clear that $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{X}{s'}{\vec{x}}{\varphi\land(y = c)}$.
    It is also clear that $s'$ is more general than $s$ but $s$ is not more general than $s'$.
    This contradicts the assumption that $s$ is most general in $\SET{t \mid \CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}}$.
%
    \item Assume $s$ is not $X$-linear.
    In this case, there exists a variable $y$ with non-linear occurrences in $s$.
    Let $p_1,\ldots,p_n$ be the pairwise distinct positions in $s$ such that
    $s|_{p_1} = \cdots = s|_{p_n} = y$.
    Let $z_2,\ldots,z_n$ be fresh pairwise distinct variables.
    Let $s' = s[y,z_2,\ldots,z_n]_{p_1,\ldots,p_n}$.
    Then, $\CTerm{X\cup \SET{z_2,\ldots,z_n}}{s'}{\vec{x}}{(\varphi\land \bigwedge_{i=2}^n(z_i = y))}$ is an existentially constrained term.
    By definition, it is clear that $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{X}{s'}{\vec{x}}{(\varphi\land\bigwedge_{i=2}^n(z_i = y))}$.
    It is also clear that $s'$ is more general than $s$ but $s$ is not more general than $s'$.
    This contradicts the assumption that $s$ is most general in $\SET{ t \mid \CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi} }$.
\end{itemize}

%%%
For the \textit{only-if} part, 
assume that $\CTerm{X}{s}{\vec{x}}{\varphi}$ is satisfiable and pattern-general,
and $\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then, it follows from \Cref{lem:basic-derived-properties-of-equivalence}~(2) %,
that $\Pos_{\Val \cup X} (s) = \Pos_{\Val \cup Y} (t) = \SET{\seq{p}}$
for some $\seq{p}$. %, by
It also follows from \Cref{lem:basic-derived-properties-of-equivalence}~(7) %,
that
$\rho(s[~]_{\seq{p}}) =  t[~]_{\seq{p}}$ for some renaming
$\rho: (\Var(s)\setminus X) \to (\Var(t)\setminus Y)$.
Let $s = s[\seq{s}]_{\seq{p}}$.
Then, because $\CTerm{X}{s}{\vec{x}}{\varphi}$ is pattern-general,
$\seq{s}$ consists of mutually distinct variables.
Thus, one can take a substitution $\delta: \SET{\seq{s}} \to \SET{ t|_{p_i} \mid 1 \le i \le n }$
such that $\delta(s_i) = t|_{p_i}$ ($1 \le i \le n$).
Moreover, since  $\seq{s} \in X$,
$\SET{\seq{s}} \cap (\Var(s)\setminus X) = \varnothing$.
Thus, we can take a substitution $\rho \cup \gamma$.
Then, $s(\rho \cup \gamma) 
= s[s_1,\ldots,s_n](\rho \cup \gamma) 
= s\rho[s_1\gamma,\ldots,s_n\gamma]
= t[t_1,\ldots,t_n] = t$.
Therefore, we conclude $\CTerm{X}{s}{\vec{x}}{\varphi}$ is most general
in the set $\SET{t \mid \CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}}$.
%%%
%We prove the \textit{only-if} part by contradiction. Assume that
%$\CTerm{X}{s}{\vec{x}}{\varphi}$ is pattern-general but $s$ is not most general
%in $\{ t \mid \CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}
%\}$. Then, there exists an existentially constrained term
%$\CTerm{Y}{t}{\vec{y}}{\psi}$ and a substitution $\theta$ such that
%$\CTerm{X}{s}{\vec{x}}{\varphi} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$, $s =
%t\theta$, and $s$ is not a renamed variant of $t$.
%\textcolor{red}{NN: for a simple proof, we need a lemma shown later for characterization.}
\qed
\end{proof}

