\LemPropertiesOfEquivalenceOverXvarValPositions*
\begin{proof}
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item 
    By definition, it is clear that $\sim_{\Pos_{X\cup \Val}(s)}$ is reflexive and symmetric.
    We show the transitivity of $\sim_{\Pos_{X\cup \Val}(s)}$.
    Assume that $p_1 \sim_{\Pos_{X\cup \Val}(s)} p_2$ and $p_2 \sim_{\Pos_{X\cup \Val}(s)} p_3$.
    Then, by definition, we have that 
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_{p_1} = s|_{p_2})$
    and
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_{p_2} = s|_{p_3})$ and hence
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_{p_1} = s|_{p_3})$.
    Therefore, we have that $p_1 \sim_{\Pos_{X\cup \Val}(s)} p_3$ and thus $\sim_{\Pos_{X\cup \Val}(s)}$ is transitive.

    \item 
    Let $p,q \in \Pos_{X\cup \Val}(s)$ such that $s|_p = s|_q$.
    Then, $\vDash_\xM (s|_p = s|_q)$ and hence 
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = s|_q)$.
    Therefore, we have that $p \sim_{\Pos_{X\cup \Val}(s)} q$.
\qed\end{enumerate}
\end{proof}

\LemPropertiesOfPosExcl*
\begin{proof}
\begin{enumerate}
\renewcommand{\labelenumi}{\Bfnum{\arabic{enumi}}}
    \item 
    By definition, it is clear that 
    there exists at least one value $v$ such that 
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = v)$.
    %We show by contradiction that $v$ is unique.
    Assume %that there exists a value $v'$ such that 
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = v')$.  %%and $v \ne v'$.
    Since $\vDash_\xM \ECO{\vec{x}}{\varphi}$ is satisfiable, 
    $\vDash_{\xM,\rho} \ECO{\vec{x}}{\varphi}$ for some valuation $\rho$.
    Then, we have $\vDash_{\rho,\xM}  s|_p = v$
    and $\vDash_{\rho,\xM}  s|_p = v'$.
    Hence, $v = \rho(s|_p) = v'$.
%    Then, we have that $\xM \vDash ((\ECO{\vec{x}}{\varphi}) \Rightarrow v = v')$.
%    Let $\sigma$ be an $X$-valued substitution $\xM \vDash (\ECO{\vec{x}}{\varphi})\sigma$.
%    Then, we have that $\xM \vDash (v = v')\sigma$, i.e., $\xM \vDash v = v'$.
%    This contradicts the fact that $v \ne v'$.

    \item 
    Let $p,q \in \Pos_{X \cup \Val}(s)$ such that $p \in \Pos_{\Val!}(s)$ and $p \sim q$.
    Then, from $p \in \Pos_{\Val!}(s)$, 
    there exists a value $v \in \Val$ such that 
    $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_{p} = v)$, 
    and
    from $p \sim q$, 
    we have $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = s|_q)$.
    Thus, we have that $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_q = v)$.
    Therefore, we obtain $q \in \Pos_{\Val!}(s)$.

    \item 
    Let $p,q \in \Pos_{X\cup\Val}(s)$ and $v,v' \in \Val$ such that
    $p \sim q$, $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = v)$, 
    and $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_q = v')$.
    Then, %by definition, 
    from $p \sim q$
    we have that $\vDash_\xM ((\ECO{\vec{x}}{\varphi}) \Rightarrow s|_p = s|_q)$. 
    Hence,  
    $\xM \vDash ((\ECO{\vec{x}}{\varphi}) \Rightarrow v = v')$.
    Therefore, we obtain $v = v'$.
\qed\end{enumerate}
\end{proof}

