\LemInducedEqualitiesOfExpliciitSubstitutions*
\begin{proof}
Let $z \in X$.
Then, Since $X \subseteq \Var(s)$, there exists a position $p \in \Pos_X(s)$ such that $s|_p = z$.
We make a case analysis depending on the existence of a position $p \in \Pos_{\Val!}(s)$ such that $s|_p = z$.
\begin{itemize}
    \item Assume that there exists a position $p \in \Pos_{\Val!}(s)$ such that $s|_p=z$.
    Then, by definition, we have that $\mu_{X}(z) = \Val!(p)$.
    Since $p \in \Pos_{\Val!}(s)$ and $s|_p=z$, by definition, 
    we have that $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (z=\Val!(p))$
    and hence $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (z = \mu_{X}(z))$.
%
    \item Assume that there exists no position $p \in \Pos_{\Val!}(s)$ such that $s|_p=z$.
    Then, by definition, we have that $\mu_{X}((z) = s|_{\hat{p}}$.
    Since $\hat{p}$ is a representative of $[p]_\sim$, we have that $p \sim \hat{p}$.
    It follows from \Cref{lem:properties-of-PosValExcl} that $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s|_p = s|_{\hat{p}})$
    and hence
     $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (z = \mu_{X}(z))$.
\qed\end{itemize}
\end{proof}

