% Note $\gamma(w') = w$ for $w' \notin \Var(r)$.
% $w \in \Var(\m{g}(\square,w))$,
$s|_2 = t|_2 = w$, hence
$w \in \Var(t)$.
%
%\item 
We have $x \in \SET{\vec{y}}$. Note that
$x \in \Var(s)$, but 
$x \notin \Var(r\gamma)$ and $x \notin \Var(t)$;
% Note $\gamma(x') = x$ for $x' \notin \Var(r)$
% and $x \notin \Var(\m{g}(\square,w))$.
however, since $x \in\Var(\varphi)$, 
we have $x \in \SET{\vec{y}}$.
%
%\item
We have $y \in \SET{\vec{y}}$;
note that
$y \in \Var(s)$, but 
$y \notin \Var(r\gamma)$, $y \notin \Var(t)$
and $y \notin \Var(\varphi)$;
however, $y \in \Var(\pi\gamma)$ 
and hence $y \in \Var(\psi)$.
%
%\item
We have $z \notin Y \cup \SET{\vec{y}}$;
although $z \in \Var(s)$, we have that
$z \notin \Var(t)$,
