In the following we show that rewriting existentially constrained terms is
well-defined, in the sense that each rewrite step results in an existentially
constrained term. Before that we give certain characterizations which are used in 
later proofs.
% \TA{%%%
% We are now going to show that our definition of rewrite step is well-defined, 
% namely that the result of rewrite step becomes a constrained term. 
% Before this,  we give characterizations of free and bound variables in the constraint of reducts. 
% The former is used in the well-definedness proof, and the latter will be used later.
% }%%%

\begin{restatable}[Characterization of Free Variables in Reducts]{lemma}{LemmaIVvii}
\label{lem:free variables of constraint of reducts}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term.
Suppose that $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ is a left-linear constrained rule
satisfying $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$.
If $\CTerm{X}{s}{\vec{x}}{\varphi} \R_{\rho} \CTerm{Y}{t}{\vec{y}}{\psi}$
then $\FVar(\ECO{\vec{y}}{\psi}) \subseteq \ExVar(\rho) \cup (X \cap \Var(t))$.
\end{restatable}

\begin{restatable}[Characterization of Bound Variables]{lemma}{LemmaIVviii}
\label{lem:bound variables of constraint of reducts}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term.
Suppose that $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ is a left-linear constrained rule
satisfying $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$.
Suppose $\CTerm{X}{s}{\vec{x}}{\varphi} \R_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then the following statements hold:
%\begin{enumerate}
%    \item 
\Bfnum{1.}
$\BVar(\ECO{\vec{x}}{\varphi}) \subseteq \BVar(\ECO{\vec{y}}{\psi})$.
%    \item 
\Bfnum{2.}
$\BVar(\ECO{\vec{x}}{\varphi}) \cap \Var(l\gamma, r\gamma, \pi\gamma) = \varnothing$.
%    \item 
\Bfnum{3.}
$Y \cup \BVar(\ECO{\vec{y}}{\psi}) = \ExVar(\rho) \cup (X \cap \Var(t)) \cup \Var(\psi)$.
%\end{enumerate}
\end{restatable}

\begin{restatable}[Well-Definedness of Rewrite Steps]{theorem}{TheoremIVix}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term.
Suppose that $\rho$ is a left-linear constrained rule
satisfying $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$.
If $\CTerm{X}{s}{\vec{x}}{\varphi} \R_{\rho} \CTerm{Y}{t}{\vec{y}}{\psi}$
then $\CTerm{Y}{t}{\vec{y}}{\psi}$ is an existentially constrained term.
\end{restatable}

A significant feature of our notion of rewriting existentially constrained terms
is that, for the same constrained rewrite rule at the same position, the resulting term 
is unique.

\begin{restatable}[Uniqueness of Reducts]{theorem}{TheoremIVx}
Let $\CTerm{X}{s}{\vec{x}}{\varphi}$ be a satisfiable existentially constrained term
and $p \in \Pos(s)$.
Suppose that $\rho,\rho'$ are renamed variants of the same left-linear constrained rule
satisfying $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$
and $\Var(\rho') \cap \Var(s,\varphi) = \varnothing$.
If $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho} \CTerm{Y}{t}{\vec{y}}{\psi}$ and
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho'} \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$
then $\CTerm{Y}{t}{\vec{y}}{\psi} \sim \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.
\end{restatable}

\subsection{Commutativity of Rewriting and Equivalence}
\label{ssec:commutativity of rewriting and equivalence}

The aim of this subsection is to show that our new notion of rewriting
commutes with the equivalence transformation, using a characterization shown in
\Cref{ssec:pattern general constrained terms}.
We begin with showing one-step commutation for pattern-general constrained terms,
before we proceed to general case.

\begin{restatable}[Commutativity of Rewrite Steps and Equivalence for Pattern-General Terms]{lemma}{LemmaIVxi}
\label{lem:commutativity of rewrite steps and equivalence for pattern-general terms}
Let 
$\rho$ be a left-linear constrained rewrite rule and
$\CTerm{X}{s}{\vec{x}}{\varphi},
\CTerm{Y}{t}{\vec{y}}{\psi}$ be existentially constrained terms
that are satisfiable and pattern-general.
If $\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} \Lb[\rho] \CTerm{X}{s}{\vec{x}}{\varphi} \sim  \CTerm{Y}{t}{\vec{y}}{\psi}$
then
$\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} \sim \CTerm{Y'}{t'}{\pvec{y}'}{\psi'} \Lb[\rho]  \CTerm{Y}{t}{\vec{y}}{\psi}$
for some $\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.
\end{restatable}

\begin{example}
\label{ex:non-commutation example}
In \Cref{lem:commutativity of rewrite steps and equivalence for pattern-general terms},
we assume that the equivalent existentially constrained terms are pattern-general.
A natural question is, what happens if we drop this condition?
Let $\rho\colon\CRu{\varnothing}{\m{f}(\m{0})}{\m{0}}{\m{true}}$ be a constrained rule, 
and consider the equivalence 
$\CTerm{\varnothing}{\m{f}(\m{0})}{}{}
\sim \CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}}$.
Then, we have 
$\CTerm{\varnothing}{\m{f}(\m{0})}{}{} \R_\rho \CTerm{\varnothing}{\m{0}}{}{}$.
However, 
$\CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}}$ cannot be rewritten by $\rho$,
because there does not exists a $\gamma$ such that $\m{f}(x) = \m{f}(\m{0})\gamma$.
Thus constrained terms that are not pattern-general,
may not commute with rewrite steps in general.
\end{example}

However, we can recover commutation using a reasonable transformation
on constrained rewrite rules. In the next subsection, we introduce this and show
that any constrained rewrite rule can be simulated by it.

\subsection{Left-Value-Free Rules}
\label{ssec:left-value-free rules}

\Cref{ex:non-commutation example}
contains a counterexample of commutation
using the rule $\rho\colon\CRu{\varnothing}{\m{f}(\m{0})}{\m{0}}{\m{true}}$,
which cannot reduce the constrained term
$\CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}}$.
However, the rule 
$\rho'\colon\CRu{\SET{x}}{\m{f}(x)}{\m{0}}{x = \m{0}}$ has the same effect as $\rho$,
but can reduce the term as follows:
$\CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}}
\R_{\rho'} \CTerm{\varnothing}{\m{0}}{x}{x = \m{0}}
\sim \CTerm{\varnothing}{\m{0}}{}{}$.
In the following, we show how this can be achieved for arbitrary constrained rewrite rules.

We define left-value-free rewrite rules~\cite{Kop17} in our setting as follows.

\begin{definition}[Left-Value-Free Rewrite Rule]
A constrained rewrite rule $\CRu{Z}{\ell}{r}{\pi}$ is \emph{left-value-free}
if $\Pos_{\Val}(\ell) = \varnothing$.
\end{definition}

\begin{definition}[Left-Value-Free Transformation]
Let $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ be a left-linear constrained rule,
$\Pos_{\Val}(\ell) = \SET{p_1,\ldots,p_n}$, and
$\ell|_{p_i} = v_i$ for $1 \le i \le n$.
Taking the fresh variables $x_1,\ldots,x_n$,
we define the \emph{left-value-free transformation} of $\rho$
as $\lvf(\rho) = \CRu{\hat{Z}}{\hat\ell}{r}{\hat\pi}$ 
where $\hat{Z} = Z \cup \SET{x_1,\ldots,x_n}$,
$\hat\ell = \ell[x_1,\ldots,x_n]_{p_1,\ldots,p_n}$,
and $\hat\pi = \pi \land \bigwedge_{i = 1}^{n} (x_i = v_i)$.
% \NN{\color{red}NN: is it possible to define $\lvf$ by $\PG$?
% (just question from my interest)}
\end{definition}

We demonstrate that restricting rewrite rules to left-value-free ones preserves
generality.

\begin{restatable}{theorem}{TheoremIVxv}
Let $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ be a left-linear constrained rewrite rule,
and $\lvf(\rho) = \hat\rho\colon \CRu{\hat Z}{\hat \ell}{r}{\hat \pi}$.
Suppose that 
$\CTerm{X}{s}{\vec{x}}{\varphi}$ is an existentially constrained term
such that $\Var(\hat \rho) \cap \Var(s,\varphi) = \varnothing$.
%Then the following hold.
%If $\CTerm{X}{s}{\vec{x}}{\varphi}$ has a $\rho$-redex at position $p \in \Pos(s)$
%then it has a $\hat{\rho}$-redex at position $p$.
If $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho} \CTerm{Y}{t}{\vec{y}}{\psi}$
then there exists a constrained term $\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$
such that
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\hat\rho} 
\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}
\sim \CTerm{Y}{t}{\vec{y}}{\psi}$.
\end{restatable}

\begin{example}
\label{ex:non-commutation example II}
Let us revisit \Cref{ex:non-commutation example}.
There we consider the constrained rewrite rule 
$\rho\colon\CRu{\varnothing}{\m{f}(\m{0})}{\m{0}}{\m{true}}$
and the equivalence
$\CTerm{\varnothing}{\m{f}(\m{0})}{}{} 
\sim \CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}}$.
Let $\hat\rho = \lvf(\rho) 
= \CRu{\SET{y}}{\m{f}(y)}{\m{0}}{\m{true} \land y = \m{0}}$.
In contrast to rewriting with $\rho$, 
we have 
$\CTerm{\varnothing}{\m{f}(\m{0})}{}{} 
\R_{\hat\rho} \CTerm{\varnothing}{\m{0}}{}{\m{true} \land \m{0} = \m{0}}$
and 
$\CTerm{\varnothing}{\m{f}(x)}{}{x = \m{0}} 
\R_{\hat\rho} \CTerm{\varnothing}{\m{0}}{x}{\m{true} \land (x = \m{0}) \land (x = \m{0})}$.
In this case, clearly,
$\CTerm{\varnothing}{\m{0}}{}{\m{true} \land \m{0} = \m{0}}
\sim \CTerm{\varnothing}{\m{0}}{x}{\m{true} \land (x = \m{0}) \land (x = \m{0})}$.
\end{example}

In the next subsection
we show that, if we only consider left-value-free rewrite rules
then commutativity holds for terms that are not necessarily pattern-general.

\subsection{General Commutativity for Rewrite Steps with Left-Value-Free Rules}
