\begin{restatable}[Simulation of Rewrite Steps by Existential Removing]{theorem}{TheoremIVxxxi}
Let $\rho$ be a left-linear constrained rewrite rule.
If $\CTerm{X}{s}{\vec{x}}{\varphi} \R_\rho \CTerm{Y}{t}{\vec{y}}{\psi}$
then $\rmv(\CTerm{X}{s}{\vec{x}}{\varphi}) \Rs \rmv(\CTerm{Y}{t}{\vec{y}}{\psi})$.
\end{restatable}

The opposite direction is characterized as follows.

\begin{restatable}[Simulation of Rewrite Steps by Existential Extension]{theorem}{TheoremIVxxxii}
Let $\rho$ be a left-linear constrained rewrite rule.
If $\CTerm{X}{s}{}{\varphi} \R_{\rho} \CTerm{Y}{t}{}{\varphi}$
then $\ext(\CTerm{X}{s}{}{\varphi}) \R \cdot \supsetsim \ext(\CTerm{Y}{t}{}{\varphi})$.
\end{restatable}

