\LemmaIVvii*
\begin{proof}
Let $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then we have 
(1) $\Dom(\gamma) = \Var(\ell)$,
(2) $s|_p = \ell\gamma$,
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]_{p}$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.
%
We have
$\FVar(\ECO{\vec{y}}{\psi}) 
= \Var(\psi) \setminus \SET{\vec{y}} 
= \Var(\psi) \setminus (\Var(\psi) \setminus \Var(t))
= \Var(\psi) \cap \Var(t)
= \Var(\varphi \land \pi\gamma) \cap \Var(t)$.
We show that $x \in \FVar(\ECO{\vec{y}}{\psi})$
implies $x \in \ExVar(\rho) \cup (X \cap \Var(t))$,
and distinguish the cases
whether $x \in \Var(\varphi) \cap \Var(t)$
or $x \in \Var(\pi\gamma) \cap \Var(t)$.
\begin{itemize}
\item 
Case $x \in \Var(\varphi) \cap \Var(t)$.
Because $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$,
we know $x \notin \Var(\rho)$, and thus $x \notin \Var(r)$.
%
We claim that $x \in \Var(s)$ and assume the contrary.
Then by $x \in \Var(t)$, we know $x \in \Var(r\gamma) \setminus \Var(\ell\gamma)$.
This implies by $x \notin \Var(r)$
that for some $x' \in \Dom(\gamma)$ we have $x \in \Var(x'\gamma)$.
By $\Dom(\gamma)= \Var(\ell)$, this contradicts $x \notin \Var(\ell\gamma)$.
Thus, $x \in \Var(s)$.
%
From $x \in \Var(s)$ and $x \in \Var(\varphi)$,
$x \in \Var(s) \cap \Var(\varphi) = \FVar(\ECO{\vec{x}}{\varphi})
\subseteq X$.
Thus, $x \in X \cap \Var(t)$.

\item 
Case $x \in \Var(\pi\gamma) \cap \Var(t)$.
Suppose there exists some $x' \in \Dom(\gamma) \cap \Var(\pi)$ such that
$x \in \Var(x'\gamma)$. Then, $x' \in \Var(\ell)$,
and thus $x \in \Var(\ell\gamma)$.
Since $x' \in \Var(\pi) \subseteq Z$, we know $x' \in \Var(\ell) \cap Z$.
This implies $x = \gamma(x') \in \Val \cup X$ by condition (3) above.
Hence $x \in X$. Thus, $x \in X \cap \Var(t)$.
%
Now, suppose he opposite, i.e.\ 
there is no $x' \in \Dom(\gamma) \cap \Var(\pi)$ such that $x \in \Var(x'\gamma)$.
Then from $x \in \Var(\pi\gamma)$, we know $x \in \Var(\pi) \setminus \Var(\ell)$.
Thus, $x \notin \Var(s,\varphi)$ by $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$.
Since $x \in \Var(t)$, this implies $x \in \ExVar(\rho)$.
\end{itemize}
\end{proof}

\LemmaIVviii*
\begin{proof}
Let $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then we have 
(1) $\Dom(\gamma) = \Var(\ell)$,
(2) $s|_p = \ell\gamma$,
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.

\textup{\Bfnum{1.}}
We have $\BVar(\ECO{\vec{x}}{\varphi}) 
= \Var(\varphi) \setminus \Var(s)
= \Var(\varphi) \setminus \Var(s[\ell\gamma]_{p})$
and 
$\BVar(\ECO{\vec{y}}{\psi}) 
= \Var(\psi) \setminus \Var(t)
= \Var(\varphi \land \pi\gamma) \setminus \Var(s[r\gamma]_{p})$.
%
Thus, assume $x \in \Var(\varphi) \setminus \Var(s[\ell\gamma]_p)$,
i.e.\ $x \in \Var(\varphi)$ and $x \notin \Var(s[\ell\gamma]_p)$.
We show $x \in \Var(\varphi \land \pi\gamma) \setminus \Var(s[r\gamma])$.
By $x \in \Var(\varphi)$, clearly $x \in \Var(\varphi \land \pi\gamma)$.
It remains to show $x \notin \Var(s[r\gamma]_p)$.
%
Assume the contrary, i.e.\ $x \in \Var(s[r\gamma]_p)$.
Then by $x \notin \Var(s[\ell\gamma]_p)$ we have that $x \notin \Var(s[~]_p)$.
Thus, $x \in \Var(r\gamma)$.
If $x \in \Var(x'\gamma)$ for some $x' \in \Dom(\gamma) = \Var(\ell)$,
then $x = \gamma(x') \in \Var(\ell\gamma)$, 
which contradicts our assumption $x \notin \Var(s[\ell\gamma]_p)$.
Thus, there is no $x' \in \Dom(\gamma) = \Var(\ell)$ such that $x \in \Var(x'\gamma)$.
This implies that $x \in \Var(r) \setminus \Var(\ell)$.
However, since $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$,
this contradicts our assumption $x \in \Var(\varphi)$.
Therefore we conclude that $x \notin \Var(s[r\gamma]_p)$.

\textup{\Bfnum{2.}}
%%$\BVar(\ECO{\vec{x}}{\varphi}) \cap \Var(r\gamma, \pi\gamma) = \varnothing$.
Firstly,
$\SET{\vec{x}} =  \Var(\varphi) \setminus \Var(s)$
and hence $\SET{\vec{x}} \cap \Var(s) = \varnothing$.
We also have $s|_p = \ell\gamma$ and then that $\Var(l\gamma) \subseteq \Var(s)$.
This implies $\SET{\vec{x}} \cap \Var(\ell\gamma) = \varnothing$.
Secondly, from~\Bfnum{1.} we obtain that $\SET{\vec{x}} \subseteq \SET{\vec{y}}$.
Since $\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$ we have that
$\SET{\vec{y}} \cap \Var(t) = \SET{\vec{y}} \cap \Var(s[r\gamma]_p) = \varnothing$.
Hence $\SET{\vec{y}} \cap \Var(r\gamma) = \varnothing$.

It suffices to show that 
$\BVar(\ECO{\vec{x}}{\varphi}) \cap \Var(\pi\gamma) = \varnothing$.
Suppose the contrary, for which there exists a variable $x$ 
such that $x \in \Var(\varphi)$, $x \notin \Var(s)$ and $x \in \Var(\pi\gamma)$.
Based on $x \in \Var(\pi\gamma)$ we perform a case analysis:
\begin{itemize}
\item Assume that there exists an $x' \in \Dom(\gamma) \cap \Var(\pi) = \Var(\ell) \cap \Var(\pi)$
such that $x \in \Var(x'\gamma)$.
Then $x \in \Var(\ell\gamma) \subseteq \Var(s)$, which contradicts our assumption.
\item Now assume that there is no $x' \in \Dom(\gamma) \cap \Var(\pi) = \Var(\ell) \cap \Var(\pi)$
such that $x \in \Var(x'\gamma)$.
By $x \in \Var(\pi\gamma)$ it follows that
$x \in \Var(\pi) \setminus \Dom(\gamma) = \Var(\pi) \setminus \Var(\ell)$.
Then $x \in \Var(\rho)$, but as $\Var(\rho)\cap \Var(s,\varphi) = \varnothing$
it contradicts that $x \in \Var(\varphi)$.
\end{itemize}

\textup{\Bfnum{3.}}
($\subseteq$)
From $Y = \ExVar(\rho) \cup (X \cap \Var(t))$,
the case $x \in Y$ is clear.
The case $x \in \BVar(\ECO{\vec{y}}{\psi})$
is also obvious, as 
$\BVar(\ECO{\vec{y}}{\psi}) \subseteq \Var(\psi)$.
%
($\supseteq$)
Due to the fact that $Y = \ExVar(\rho) \cup (X \cap \Var(t))$,
it suffices to show $\Var(\psi) \subseteq Y \cup \BVar(\ECO{\vec{y}}{\psi})$.
Furthermore, as $\Var(\psi) = \FVar(\ECO{\vec{y}}{\psi}) \cup \BVar(\ECO{\vec{y}}{\psi})$
it only remains to show that 
$\FVar(\psi) \subseteq Y = \ExVar(\rho) \cup (X \cap \Var(t))$.
The latter is satisfied by \Cref{lem:free variables of constraint of reducts}.
\end{proof}

\TheoremIVix*
\begin{proof}
Let $\rho\colon \CRu{Z}{\ell}{r}{\pi}$, and suppose that
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then we have 
(1) $\Dom(\gamma) = \Var(\ell)$,
(2) $s|_p = \ell\gamma$,
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, 
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
and 
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.
Clearly, $\ECO{\vec{y}}{\psi}$ is an existentially quantified constraint.

We show 
$\FVar(\ECO{\vec{y}}{\psi}) \subseteq Y \subseteq \Var(t)$
and $\BVar(\ECO{\vec{y}}{\psi}) \cap \Var(t) =  \varnothing$.
From \Cref{lem:free variables of constraint of reducts},
$\FVar(\ECO{\vec{y}}{\psi}) \subseteq \ExVar(\rho) \cup (X \cap \Var(t)) = Y$ follows.
Since $\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$,
$\SET{\vec{y}} \cap \Var(t) = \varnothing$ clearly holds.
It remains to show $Y = \ExVar(\rho) \cup (X \cap \Var(t)) \subseteq \Var(t)$.
However, as $X \cap \Var(t) \subseteq \Var(t)$, it suffices to show
$\ExVar(\rho) \subseteq \Var(t)$.
Let $x \in \ExVar(\rho) = \Var(r) \setminus\Var(\ell)$.
Then we obtain by $\gamma(x) = x$ that $x \notin \Var(\ell) = \Dom(\gamma)$.
Hence, from $x \in \Var(r)$, it follows that $x \in \Var(r\gamma) \subseteq \Var(t)$.
\end{proof}

\TheoremIVx*
\begin{proof}
Let $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ and $\rho'\colon \CRu{Z'}{\ell'}{r'}{\pi'}$.
Suppose that
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$
and 
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho',\gamma'} \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.
%
Then we have 
(1) $\Dom(\gamma) = \Var(\ell)$,
(2) $s|_p = \ell\gamma$,
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.
%
Similarly, we have 
(1') $\Dom(\gamma') = \Var(\ell')$,
(2') $s|_p = \ell'\gamma'$,
(3') $\gamma'(x) \in \Val \cup X$ for any $x \in \Var(\ell') \cap Z'$, and
(4') $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\pvec{z}'}{\pi'\gamma'})$,
where $\SET{\pvec{z}'} = \Var(\pi') \setminus \Var(\ell')$,
$t' = s[r'\gamma']$,
$\psi' = \varphi \land \pi'\gamma'$,
$\SET{\pvec{y}'} = \Var(\psi') \setminus \Var(t')$, and
$Y' = \ExVar(\rho') \cup (X \cap \Var(t'))$.

Since $\rho,\rho'$ are renamed variants of the same rule,
we have renaming $\sigma\colon \Var(\rho) \to \Var(\rho')$
such that
$\sigma(Z) = Z'$, 
$\sigma(\ell) = \ell'$, 
$\sigma(r) = r'$, and
$\sigma(\pi) = \pi'$.

For each $x \in \Var(r,\pi) \setminus \Var(\ell)$, 
we have by $x \notin \Var(\ell) = \Dom(\gamma)$ that $\gamma(x) = x$,
and by $\sigma(x) \notin \Var(\ell') = \Dom(\gamma')$ that $\gamma'(\sigma(x)) = \sigma(x)$.
Therefore, $\sigma(\gamma(x)) = \sigma(x) = \gamma'(\sigma(x))$ for all $x \in \Var(r,\pi) \setminus \Var(\ell)$.
%
Suppose $x \in \Var(\ell)$.
Then from $\gamma(x) \in \Var(s)$ and $\Var(s) \cap \Var(\rho) = \varnothing$,
we know $\gamma(x) \notin \Var(\rho)$, and hence $\gamma(x) \notin \Dom(\sigma)$.
Thus, $\sigma(\gamma(x))= \gamma(x)$.
Moreover, since $\ell\gamma = s|_p = \ell'\gamma' = \ell\sigma\gamma'$,
by fixing $x = \ell|_q$ for a position $q$, 
we obtain $\gamma(x) = s|_{pq} = \gamma'(\sigma(x))$.
Thus, $\sigma(\gamma(x))= \gamma(x) = \gamma'(\sigma(x))$ for all $x \in \Var(\ell)$.

Putting all of this together gives
$\sigma(\gamma(x))= \gamma'(\sigma(x))$ for all $x \in \Var(\rho)$.
Hence, we have $r\gamma\sigma = r\sigma\gamma' = r'\gamma'$
and $\pi\gamma\sigma = \pi\sigma\gamma' = \pi'\gamma'$.
%
Therefore, we have 
$t\sigma = s[r\gamma]_p\sigma = s[r\gamma\sigma]_p = s[r'\gamma']_p = t'$ and 
$\psi\sigma = (\varphi \land \pi\gamma)\sigma = \varphi \land \pi\gamma\sigma 
= \varphi \land \pi'\gamma' = \psi'$.
%
In particular, it also follows that $\sigma(\Var(t)) = \Var(t\sigma) = \Var(t')$
and $\sigma(\Var(\psi)) = \Var(\psi\sigma) = \Var(\psi')$.
Thus, as $\sigma$ is bijective on $\Var(\rho)$, we obtain
$\sigma(\SET{\vec{y}}) 
= \sigma(\Var(\psi) \setminus \Var(t))
= \sigma(\SET{ x \in \Var(\rho) \mid x \in \Var(\psi) \land x \notin \Var(t) }
= \SET{ \sigma(x) \in \Var(\rho) \mid x \in \Var(\psi) \land x \notin \Var(t) }
= \SET{ \sigma(x) \in \Var(\rho) \mid \sigma(x) \in \Var(\psi') \land \sigma(x) \notin \Var(t') }
= \Var(\psi') \setminus \Var(t') = \SET{\pvec{y}'}$.
%
From $X \cap \Var(\rho) = \varnothing$, we know that $X \cap \Dom(\sigma) = \varnothing$.
Thus, $\sigma(X) = X$. Therefore,
$\sigma(Y) 
= \sigma(\ExVar(\rho) \cup (X \cap \Var(t)))
= \sigma((\Var(r) \setminus \Var(\ell)) \cup (X \cap \Var(t)))
= (\Var(r\sigma) \setminus \Var(\ell\sigma)) \cup (X \cap \Var(t\sigma))
= \ExVar(\rho') \cup (X \cap \Var(t')) = Y'$.
Since $\sigma$ is a bijective renaming
by \Cref{lem:equivalence by renaming}
we have $\CTerm{Y}{t}{\vec{y}}{\psi} \sim \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.
\end{proof}

\LemmaIVxi*
