From~(7) we have $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
thus $\vDash_\xM (\ECO{\vec{x}}{\varphi})\sigma \Rightarrow (\ECO{\vec{z}}{\pi\gamma})\sigma$.
From~(3) follows that
$\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})\sigma$.
By $\sigma\colon \Var(s,\varphi) \to \Var(t,\psi)$ and $\SET{\vec{z}} \subseteq \Var(\rho)$,
we conclude from $\Var(\rho) \cap \Var(s,\varphi) = \varnothing$ 
%that $\SET{\vec{z}} \cap \Dom(\sigma) = \varnothing$,
that $\SET{\vec{z}} \cap \Var(s,\varphi)  = \varnothing$,
and 
further from $\Var(\rho) \cap \Var(t,\psi) = \varnothing$ 
%that $\SET{\vec{z}} \cap \Codom(\sigma) = \varnothing$.
that $\SET{\vec{z}} \cap \Var(t,\psi) = \varnothing$.
Hence, by definition of $\delta$, 
$(\ECO{\vec{z}}{\pi\gamma})\sigma 
= \ECO{\vec{z}}{\pi\gamma\sigma}
= \ECO{\vec{z}}{\pi\delta}$,
and therefore
$\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (\ECO{\vec{z}}{\pi\delta})$ is satisfied.
Let
$t' = s[r\delta]_p$,
$\psi' = \psi \land \pi\delta$,
$\SET{\pvec{y}'} = \Var(\psi') \setminus \Var(t')$, and
$Y' = \ExVar(\rho) \cup (Y \cap \Var(t'))$,
we obtain the rewrite step
$\CTerm{Y}{t}{\vec{y}}{\psi} \R^p_{\rho,\delta}  \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.

It remains to show that
$\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} \sim \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$.
To that end we use \Cref{thm:complete characterizatin of equivalence of constrained terms}.
Thus, we show 
(8) $\Pos_{X'\cup\Val}(s') = \Pos_{Y'\cup\Val}(t')~ ( = \SET{p_1,\ldots,p_n})$,
(9) there exists a renaming $\rho\colon \Var(s') \setminus X' \to \Var(t') \setminus Y'$ 
such that $\rho(s'[\,]_{p_1,\ldots,p_n}) = t'[\,]_{p_1,\ldots,p_n}$
(10) for any $i,j \in \SET{1,\ldots,n}$, 
        $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s'|_{p_i} = s'|_{p_j})$
        if and only if 
        $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (t'|_{p_i} = t'|_{p_j})$,
(11) for any $i \in \SET{1,\ldots,n}$ and $v \in \Val$, 
        $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (s'|_{p_i} = v)$
        if and only if 
        $\vDash_\xM (\ECO{\vec{y}}{\psi}) \Rightarrow (t'|_{p_i} = v)$,
        and
(12) 
%for representative substitutions $\mu_{X'}, \mu_{Y'}$ 
%of $\CTerm{X'}{s'}{\pvec{x}'}{\varphi'}$ and $\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$, respectively, 
%there exists a renaming $\theta\colon \tilde{X'} \to \tilde{Y'}$ such that
%$\vDash_\xM  (\ECO{\pvec{x}'}{\varphi'})\mu_{X'}\theta 
%\Leftrightarrow (\ECO{\pvec{y}'}{\psi'})\mu_{Y'}$, 
%where $\tilde{X'} = \hat{X'} \cap X$ and $\tilde{Y'} = \hat{Y'}\cap Y$.
let ${\sim} = {\sim}_{\Pos_{X'\cup \Val}(s')} = {\sim}_{\Pos_{X'\cup \Val}(t')}$
and $\mu_{X'},\mu_{Y'}$ be representative substitutions of
$\CTerm{X'}{s'}{\pvec{x}'}{\varphi'}$ and $\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$, respectively, 
based on the same representative for
each equivalence class $[p_i]_\sim$ ($1 \le i \le n$), 
and we have 
    $\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\mu_{X'}\theta|_{\tilde{X'}}
    \Leftrightarrow (\ECO{\pvec{y}'}{\psi'})\mu_{Y'}$
    with a renaming $\theta|_{\tilde{X'}} \colon \tilde{X'} \to \tilde{Y'}$,
    where $\theta =  \SET{ \langle s'|_{p_i}, t'|_{p_i} \rangle \mid 1 \le i \le n }$,
    $\tilde{X'} = \hat{X'} \cap X'$, and $\tilde{Y'} = \hat{Y'}\cap Y'$.

We start by showing~(8).
Consequently observe that
\addtocounter{equation}{12}
\begin{equation}\label{eq:13}
s'\sigma = s[r\gamma]_p\sigma = s\sigma[r\gamma\sigma]_p =  t[r\delta]_{p} = t'
\end{equation}
Hence, also 
$\sigma(X') 
= \sigma(\ExVar(\rho) \cup \sigma(X \cap \Var(s'))
= \sigma(\ExVar(\rho)) \cup \sigma(X \cap \Var(s'))
= \ExVar(\rho) \cup (\sigma(X) \cap \Var(s'\sigma))
= \ExVar(\rho) \cup (Y \cap \Var(t')) = Y'$ follows.
This implies that
$\Pos_{X'\cup\Val}(s') 
= \Pos_{\sigma(X')\cup\Val}(s'\sigma) 
= \Pos_{Y'\cup\Val}(t')$,
which shows~(8). 
In the following let $\Pos_{X'\cup\Val}(s') = \SET{p_1,\ldots,p_n}$.

We proceed to show~(9). Using the fact~(8), 
we let $s' = s'[s_1',\ldots,s_n']_{p_1,\ldots,p_n}$
and $t' = t'[t_1',\ldots,t_n']_{p_1,\ldots,p_n}$.
Then, from~(\ref{eq:13}), it follows that
$s'\sigma[~]_{p_1,\ldots,p_n} = t'[~]_{p_1,\ldots,p_n}$ and
$s_i'\sigma = t_i'$ for each $1 \le i \le n$.
Note here that $s_i' \in \Val \cup X'$ and $t_i' \in \Val \cup Y'$.
Thus, since $\sigma$ is a renaming, we have
$s_i' \in X'$ if and only if $t_i' \in Y'$,
$s_i' \in \Val$ if and only if $t_i' \in \Val$, and
$s_i' = s_j'$ if and only if $t_i' = t_j'$
for $i,j \in \SET{1, \ldots, n}$.
Hence $\SET{s_1',\ldots,s_n'} \cap X' = \SET{t_1',\ldots,t_n'} \cap Y'$.
Since $\sigma(X') = Y'$, it implies that 
$\eta = \SET{ x \mapsto \sigma(x) \mid x \in \Var(s') \setminus X' }$
is a bijection from $\Var(s') \setminus X'$ to $\Var(t') \setminus Y'$
such that $\eta(s'[~]_{p_1,\ldots,p_n}) = t'[~]_{p_1,\ldots,p_n}$.

Before we proceed to the remainder of the proof, let us introduce a useful
temporary notation and show some related properties.
For $\ECO{\vec{x}}{\varphi}$ 
and $\ECO{\pvec{x}'}{\varphi'} = \ECO{\pvec{x}'}{\varphi \land \pi\gamma}$,
we have, by \Cref{lem:bound variables of constraint of reducts},
that $\SET{\vec{x}} \subseteq \SET{\pvec{x}'}$.
Let $\SET{\pvec{x}''} = \SET{\pvec{x}'} \setminus \SET{\vec{x}}$
and let us write $\varphi = \varphi(\vec{x},\pvec{x}'')$.
Also, for $\pi\gamma$, because $\SET{\vec{x}} \cap \Var(\pi\gamma) = \varnothing$
by \Cref{lem:bound variables of constraint of reducts},
we have $\Var(\pi\gamma) \cap \SET{\pvec{x}'} = \SET{\pvec{x}'''} \subseteq \SET{\pvec{x}''}$.
Thus, using the subsequence $\pvec{x}'''$ of $\pvec{x}''$,
we write $\pi\gamma = \pi\gamma(\pvec{x}''')$.
Similarly, for $\ECO{\vec{y}}{\psi}$ 
and $\ECO{\pvec{y}'}{\psi'} = \ECO{\pvec{y}'}{\psi \land \pi\delta}$,
let us write $\psi = \psi(\vec{y},\pvec{y}'')$
and $\pi\delta = \pi\delta(\pvec{y}''')$ where 
$\SET{\pvec{y}''} = \SET{\pvec{y}'}\setminus \SET{\vec{y}}$
and $\SET{\pvec{y}'''} \subseteq \SET{\pvec{y}''}$.
Note that 
$\Var(\pi\gamma) 
= (\bigcup_{x \in \Var(\ell)\cap \Var(\pi)} \Var(x\gamma)) \cup (\Var(\pi) \setminus \Var(\ell))$.
%%%
Moreover, we have
$\sigma(\SET{\pvec{x}'''})
= \sigma(\Var(\pi\gamma) \cap \SET{\pvec{x}'})
= \sigma(
((\bigcup_{x \in \Var(\ell)\cap \Var(\pi)} \Var(x\gamma)) \cup (\Var(\pi) \setminus \Var(\ell)))
\setminus \Var(s'))
= 
((\bigcup_{x \in \Var(\ell)\cap \Var(\pi)} \Var(x\delta)) \cup (\Var(\pi) \setminus \Var(\ell)))
\setminus \Var(t')
= \Var(\pi\delta) \cap \SET{\vec{y}}
= \SET{\pvec{y}'''}$.

From~(3) $\vDash_\xM ((\ECO{\vec{x}}{\varphi})\sigma \Leftrightarrow (\ECO{\vec{y}}{\psi}))$,
we have that, for any valuation $\xi$,
$\vDash_{\xM,\xi} \varphi\sigma(\vec{a},\pvec{x}''\sigma)$ for some $\vec{a} \in \vert \xM \vert^*$
if and only if 
$\vDash_{\xM,\xi} \psi(\vec{b},\pvec{y}'')$ for some $\vec{b} \in \vert \xM \vert^*$.
Thus, for any valuation $\xi$,
$\vDash_{\xM,\xi} \varphi\sigma(\vec{a},\pvec{x}''\sigma) \land \pi\gamma\sigma(\pvec{x}'''\sigma)$ 
for some $\vec{a} \in \vert \xM \vert^*$
if and only if 
$\vDash_{\xM,\xi} \psi(\vec{b},\pvec{y}'') \land \pi\delta(\pvec{y}''')$ 
for some $\vec{b} \in \vert \xM \vert^*$,
as we know $\pi\gamma\sigma = \pi\delta$
and $\sigma(\SET{\pvec{x}'''}) = \SET{\pvec{y}'''}$.
In particular, we have
\begin{equation}\label{eq:14}
\vDash_\xM ((\ECO{\pvec{x}'}{\varphi'})\sigma \Leftrightarrow (\ECO{\pvec{y}'}{\psi'}))
\end{equation}

Using~(\ref{eq:14}) and our assumption that $\sigma$ is a bijection, we have 
$\vDash_\xM \ECO{x'}{\varphi'} \Rightarrow (s'|_{p_i} = s'|_{p_j})$
if and only if 
$\vDash_\xM \ECO{x'}{\varphi'}\sigma \Rightarrow (\sigma(s'|_{p_i}) = \sigma(s'|_{p_j}))$
if and only if 
$\vDash_\xM \ECO{y'}{\psi'} \Rightarrow (s'\sigma|_{p_i} = s'\sigma|_{p_j})$
if and only if 
$\vDash_\xM \ECO{y'}{\psi'} \Rightarrow (t'|_{p_i}) = t'|_{p_j})$
for $i,j \in \SET{1, \ldots,  n}$.
Similarly,
$\vDash_\xM \ECO{x'}{\varphi'} \Rightarrow (s'|_{p_i} = v)$
if and only if 
$\vDash_\xM \ECO{x'}{\varphi'}\sigma \Rightarrow (\sigma(s'|_{p_i}) = v\sigma)$
if and only if 
$\vDash_\xM \ECO{y'}{\psi'} \Rightarrow (s'\sigma|_{p_i} = v)$
if and only if 
$\vDash_\xM \ECO{y'}{\psi'} \Rightarrow (t'|_{p_i} = v)$
for $i,j \in \SET{1, \ldots,  n}$.
This shows~(10) and~(11).

Finally, take $\theta = \SET{\langle s'|_{p_i},t'|_{p_i} \rangle \mid 1 \le i \le n}$.
As $\theta|_{\tilde{X'}} \subseteq \sigma$,
from (10), (11) and $s'\sigma = t'$,
it follows that 
$\theta|_{\tilde{X'}} \circ \mu_{X'} = \mu_{Y'} \circ \sigma$.
%x0 = x1 = x2   muX =  {x1 := x0, x2 := x0 }
%y0 = y1 = y2   muY =  {y1 := y0, y2 := y0 }
%sigma = { xi := y_i }
From (\ref{eq:14}), we have 
$\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\sigma\mu_{Y'} 
\Leftrightarrow (\ECO{\pvec{y}'}{\psi'})\mu_{Y'}$, 
and thus,
$\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\mu_{X'}\theta|_{\tilde{X'}}
\Leftrightarrow (\ECO{\pvec{y}'}{\psi'})\mu_{Y'}$. 
As $\mu_{X'},\mu_{Y'}$ are based on the same representative for
each equivalence class $[p_i]_\sim$ ($1 \le i \le n$), 
$\theta|_{\tilde{X'}}$ is a variable renaming from $\tilde{X'}$ to $\tilde{Y'}$.
%Since $\Var(\JS{(}\ECO{\pvec{x}'}{\varphi'})\mu_{X'}) = \hat{X'}$,
%one can take a bijection 
%$\sigma|_{\hat{X'}}\colon \hat{X'} \to \hat{Y'}$ to have
%$\vDash_\xM (\ECO{\pvec{x}'}{\varphi'})\mu_{X'}\sigma|_{\hat{X'}}
%\Leftrightarrow (\ECO{\pvec{y}'}{\psi'})\mu_{Y'}$. 
This shows~(12) and completes the proof.
\end{proof}

\TheoremIVxv*
\begin{proof}
Let $\SET{p_1,\ldots,p_n} = \Pos_{\Val}(\ell)$
and $\ell = \ell[v_1,\ldots,v_n]_{p_1,\ldots,p_n}$.
Suppose that $y_1,\ldots,y_n$ are fresh variables,
and $\hat{Z} = Z \cup \SET{y_1,\ldots,y_n}$,
$\hat\ell = \ell[y_1,\ldots,y_n]_{p_1,\ldots,p_n}$, and
$\hat\pi = \pi \land \bigwedge_{i = 1}^{n} (y_i = v_i)$.
We obtain the following:
% \[
% \begin{array}{lcl}
% \Var(\hat\ell)  \cap \hat Z   
% & = & \Var(\ell) \cup \SET{y_1,\ldots,y_n} \cap (Z \cup \SET{y_1,\ldots,y_n})\\
% & = & (\Var(\ell) \cap X) \cup \SET{y_1,\ldots,y_n} \\
% \Var(\hat\pi) \setminus \Var(\hat\ell)
% & = & \Var(\pi) \cup \SET{y_1,\ldots,y_n} \setminus (\Var(\ell) \cup \SET{y_1,\ldots,y_n}) \\
% & = & \Var(\pi) \setminus \SET{y_1,\ldots,y_n}) \\
%  \end{array}
% \]
\begin{align*}
\Var(\hat\ell)  \cap \hat Z   
&= (\Var(\ell) \cup \SET{y_1,\ldots,y_n}) \cap (Z \cup \SET{y_1,\ldots,y_n})\\
&= (\Var(\ell) \cap Z) \cup \SET{y_1,\ldots,y_n} \\
\Var(\hat\pi) \setminus \Var(\hat\ell)
&= (\Var(\pi) \cup \SET{y_1,\ldots,y_n}) \setminus (\Var(\ell) \cup \SET{y_1,\ldots,y_n}) \\
% &= \JS{(}\Var(\pi) \setminus \SET{y_1,\ldots,y_n}) \\
&= \Var(\pi) \setminus \Var(\ell)
\end{align*}
Suppose $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then we have 
(1) $\Dom(\gamma) = \Var(\ell)$,
(2) $s|_p = \ell\gamma$,
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.

Let $\delta = \gamma \cup \SET{y_i \mapsto v_i \mid 1 \le i \le n}$.
We first show that 
the term $\CTerm{X}{s}{\vec{x}}{\varphi}$ has a $\hat\rho$-redex 
at $p \in \Pos(s)$ using $\delta$.
By~(1), we have 
$\Dom(\delta) = \Dom(\gamma) \cup \SET{y_1,\ldots,y_n} 
= \Var(\ell) \cup \SET{y_1,\ldots,y_n}$.
From~(2), we have 
$s|_p = \ell\gamma = \ell[v_1,\ldots,v_n]\gamma 
= \ell\gamma [v_1,\ldots,v_n] 
= \ell\delta[\delta(y_1),\ldots,\delta(y_n)] 
= \ell[y_1,\ldots,y_n] \delta
= \hat\ell\delta$.
We proceed to show that $\delta(x) \in \Val \cup X$
for any $x \in \Var(\hat \ell) \cap \hat Z$.
Let $x \in \Var(\hat\ell) \cap \hat{Z}= (\Var(\ell) \cap Z) \cup \SET{y_1,\ldots,y_n}$.
If $x \in \Var(\ell) \cap Z$, then $\delta(x) = \gamma(x)\in \Val \cup X$.
Otherwise, $x \in \SET{y_1,\ldots,y_n}$, and thus 
$\delta(x) = \delta(y_i) = v_i \in \Val \subseteq \Val \cup X$ for some $1 \leqslant i \leqslant n$.
Using the fact that $\Var(\hat\pi) \setminus \Var(\hat\ell) = \Var(\pi) \setminus \Var(\ell)$,
we show that $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\hat\pi\delta})$.
Here we have 
$\hat\pi\gamma 
= (\pi \land \bigwedge_{i = 1}^{n} (y_i = v_i))\gamma
= \pi\gamma \land \bigwedge_{i = 1}^{n} (v_i = v_i)
= \pi\delta \land \bigwedge_{i = 1}^{n} (v_i = v_i)$.
Clearly $\vDash_\xM \pi\gamma \Leftrightarrow \hat\pi\delta$.
Hence, from~(4), we have 
$\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\hat\pi\delta})$.
We conclude that 
$\CTerm{X}{s}{\vec{x}}{\varphi}$ has a $\hat\rho$-redex 
at $p \in \Pos(s)$ using $\delta$.

From this we obtain the rewrite step 
$\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\hat\rho,\delta} 
\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$,
where
$t' = s[r\delta]$,
$\psi' = \varphi \land \hat\pi\delta$,
$\SET{\pvec{y}'} = \Var(\psi') \setminus \Var(t')$, and
$Y' = \ExVar(\hat\rho) \cup (X \cap \Var(t'))$.
From $\ExVar(\hat\rho) \cap \SET{y_1,\ldots,y_n} = \varnothing$,
we have $r\delta = r\gamma$ and $\pi\delta = \pi\gamma$.
Thus,~(5) $t' = s[r\delta] = s[r\gamma] = t$.
It also follows from $\psi = \varphi \land \pi\gamma$,
$\psi' = \varphi \land \hat\pi\delta$,
and $\vDash_\xM \pi\gamma \Leftrightarrow \hat\pi\delta$ (shown above),
% that (6) $\vDash_\xM \varphi \Leftrightarrow \psi$.
% Using (5) and $\hat\pi\delta = \pi\gamma$ (shown above),
that~(6) $\vDash_\xM \psi' \Leftrightarrow \psi$.
Using~(5) and 
$\Var(\hat\pi\delta) 
= \Var(\pi\delta \land \bigwedge_{i = 1}^{n} (v_i = v_i)) 
= \Var(\pi\gamma)$, we obtain that,~%
(7) $\SET{\pvec{y}'} 
= \Var(\psi') \setminus \Var(t')
= \Var(\varphi \land \hat\pi\delta) \setminus \Var(t')
= \Var(\varphi \land \pi\gamma) \setminus \Var(t)
= \Var(\psi) \setminus \Var(t)
= \SET{\vec{y}}$.
By $\ExVar(\hat\rho) \cap \SET{y_1,\ldots,y_n} = \varnothing$,
we have $\ExVar(\rho) =  \ExVar(\hat \rho)$.
(8) $Y' 
= \ExVar(\hat\rho) \cup (X \cap \Var(t'))
= \ExVar(\rho) \cup (X \cap \Var(t))
= Y$.
Having~(5)--(8),
it is easy to check that 
\Cref{def:equivalence-constrained-terms}
is satisfied and therefore we conclude that
$\CTerm{Y'}{t'}{\vec{'y}}{\psi'} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$.
\end{proof}


We introduce a useful notation used in the subsequent proof.

\begin{restatable}{definition}{DefinitioinIVxvii}
\label{def:bullet translation}
Let $X$ be a set of variables, and $s$ a term,
$\Pos_{X \cup  \Val}(s)= \SET{p_1,\ldots,p_n}$
and $s^{\bullet_{X}} = s[x_1,\ldots,x_n]_{p_1,\ldots,p_n}$
for some pairwise distinct fresh variables $x_1,\ldots,x_n$.
We denote by $u^{\bullet_{X}} = s^{\bullet_{X}}|_p$ each subterm $u = s|_p$ of $s$.
Consider a linear term $\ell$ together with a substitution $\gamma$ such that
$s = \ell\gamma$ with $\Dom(\gamma) = \Var(\ell)$.
% % not clear if this is needed or what exactly is meant; comment for now!
% Clearly, for any $p,q \in \Pos(s)$,
% $\gamma(x) = s|_p = s|_q$ implies $s|_p^\bullet = s|_q^\bullet$.
We define a substitution $\gamma^{\bullet_{X}}$ 
by $\gamma^{\bullet_{X}}(x) = \gamma(x)^{\bullet_{X}}$.
When no confusion arises, the superscript $\bullet_{X}$ will be abbreviated 
by ${\bullet}$.
\end{restatable}

\begin{restatable}{lemma}{LemmaIVxviii}
\label{lem:bullet translation and contexts}
Let $X$ be a set of variables and $s$ a term.
For any subterm $f(u_1,\ldots,u_k)$ of $s$ such that $f \notin \Val$,
we have $f(u_1,\ldots,u_k)^{\bullet_X} = f(u_1^{\bullet_X},\ldots,u_k^{\bullet_X})$.
\end{restatable}
%\LemmaIVxviii*
\begin{proof}
Let $X$ be a set of variables, $s$ a term.
Suppose that $\Pos_{X \cup \Val}(s)= \SET{\seq{p}}$
and $s^{\bullet_X} = s[\seq{x}]_{\seq{p}}$.
Let $s|_p = f(u_1,\ldots,u_k)$ with $f \not\in \Val$ and $p \in \Pos(s)$. 
Then $s(p) = f$ and $s|_{p \cdot j} = u_j$ for each $1 \le j \le k$.
%
Since $s(p) \notin \Val$, we know that $p \notin \SET{\seq{p}}$,
and thus, $s^\bullet(p) = s[\seq{x}]_{\seq{p}}(p) = s(p) = f$.
%
Moreover, $u_j^\bullet = (s|_{p \cdot j})^\bullet = s^\bullet|_{p \cdot j}$ for each $1 \le j \le k$.
Thus, $f(u_1^\bullet,\ldots,u_k^\bullet)
= f(s^\bullet|_{p \cdot 1},\ldots,s^\bullet|_{p \cdot k})
= s^\bullet(p)(s^\bullet|_{p \cdot 1},\ldots,s^\bullet|_{p \cdot k})
= s^\bullet|_p$.
On the other hand, we have
$f(u_1,\ldots,u_k)^\bullet = (s|_p)^\bullet = s^\bullet|_p$ by definition.
This completes the proof.
\end{proof}

\begin{restatable}{lemma}{LemmaIVxix}
\label{lem:bullet translation and back}
Let $X$ be a set of variables and $s$ a term.
Let $s^{\bullet_{X}} = s[x_1,\ldots,x_n]_{p_1,\ldots,p_n}$
and $\sigma = \{ x_i \mapsto s|_{p_i} \mid 1 \le i \le n \}$.
Then, $u^\bullet\sigma = u$ holds for any subterm $u$ of $s$.
\end{restatable}
%\LemmaIVxix*
\begin{proof}
First note that $s^\bullet\sigma = s$ and
suppose $u = s|_p$.
Then $u^\bullet\sigma = (s^\bullet|_{p})\sigma = (s^\bullet\sigma)|_{p} = s|_p  = u$
\end{proof}

\begin{restatable}{lemma}{LemmaIVxx}
\label{lem:bullet translation and substitution}
Let $X$ be a set of variables, $s$ a term, and $\ell$ a linear term
such that $s|_p = \ell\gamma$ with $\Dom(\gamma) = \Var(\ell)$
for a substitution $\gamma$.
If $\ell$ is value-free 
then $s^{\bullet_{X}}|_p = \ell\gamma^{\bullet_{X}}$.
\end{restatable}
%\LemmaIVxx*
\begin{proof}
Let $X$ be a set of variables,
$s$ a term, and $\ell$ a linear term such that $s|_p = \ell\gamma$ for a
substitution $\gamma$ with $\Dom(\gamma) = \Var(\ell)$. Assume further that
$\ell$ is value-free. We prove by induction on the subterms $u$ of $\ell$ that
$(u\gamma)^{\bullet_{X}} = u\gamma^{\bullet_{X}}$ holds.
\begin{itemize}
\item Assume $u = x \in \xV$.
Then $(x\gamma)^\bullet = \gamma(x)^\bullet 
= \gamma^\bullet(x) 
= x\gamma^\bullet$ by definition of $\gamma^\bullet$.
%
\item Assume $u = f(u_1,\ldots,u_n)$. By our assumption we have
that $f \notin \Val$ and $u_1,\ldots,u_n$ are value-free. Thus, using 
\Cref{lem:bullet translation and contexts} and
the
induction hypothesis, we have that
$(u\gamma)^\bullet 
= (f(u_1\gamma,\ldots,u_n\gamma))^\bullet
= f((u_1\gamma)^\bullet,\ldots,(u_n\gamma)^\bullet)
= f(u_1\gamma^\bullet,\ldots,u_n\gamma^\bullet)
= f(u_1,\ldots,u_n)\gamma^\bullet
= u\gamma^\bullet$.
\end{itemize}
Note that if $u = v_i \in \Val$ then $(u\gamma)^\bullet = (v_i)^\bullet =
x_i \neq v_i = u\gamma^\bullet$ for a fresh variable $x_i$.
Thus, the condition of value-freeness of
$\ell$ is essential here. Finally, we conclude $s^\bullet|_p =
(\ell\gamma)^\bullet = \ell\gamma^\bullet$.
\end{proof}

\begin{restatable}{lemma}{LemmaIVxxi}
\label{lem:bullet translation and validity}
Let $X$ be a set of variables and $s$ a term.
Suppose that $\Pos_{X \cup \Val}(s)= \SET{p_1,\ldots,p_n}$
and $s^{\bullet_X} = s[x_1,\ldots,x_n]_{p_1,\ldots,p_n}$.
Then, for any subterm $u$ of $s$, we have
$\vDash_{\xM} (\bigwedge_{i=1}^n (s(p_i) = x_i)) \Rightarrow u = u^{\bullet_X}$.
\end{restatable}
%\LemmaIVxxi*
\begin{proof}
Let $\rho$ be a valuation and suppose that 
$\vDash_{\xM,\rho} \bigwedge_{i=1}^n (s(p_i) = x_i)$.
We show that $\vDash_{\xM,\rho} (u = u^{\bullet_X})$ holds for any subterm $u$ of $s$
by induction on $u$.

\begin{itemize}
\item 
Assume $u = s(p_i)$.
Then $u^\bullet = s(p_i)^\bullet  = s^\bullet|_{p_i}  
= (s[x_1,\ldots,x_n]_{p_1,\ldots,p_n})|_{p_i}  
= x_i$.
Since $\vDash_{\xM,\rho} (s(p_i) = x_i)$ follows
from $\vDash_{\xM,\rho} \bigwedge_{i=1}^n (s(p_i) = x_i)$,
we have $\vDash_{\xM,\rho} (u = u^\bullet)$.

\item 
Assume $u = x \in \Var(s) \setminus X$.
Suppose $x = s(p)$ with $p \notin \SET{\seq{p}}$.
Then, $u^\bullet = s(p)^\bullet  = s^\bullet|_p
= (s[x_1,\ldots,x_n]_{p_1,\ldots,p_n})|_{p}
= s(p) = x$.
Clearly, we have $\vDash_{\xM,\rho} x = x$,
and hence $\vDash_{\xM,\rho} u = u^\bullet$.

\item 
Otherwise, we have $u = f(u_1,\ldots,u_k)$ with $f \notin \Val$.
Using the induction hypothesis, we obtain
$\vDash_{\xM,\rho} (u_j = u_j^\bullet)$ for $1 \le j \le k$.
Thus, 
$\vDash_{\xM,\rho} f(u_1,\ldots,u_k) = f(u_1^\bullet,\ldots,u_k^\bullet)$.
By \Cref{lem:bullet translation and contexts}, we conclude
$\vDash_{\xM,\rho} (f(u_1,\ldots,u_k) = f(u_1,\ldots,u_k)^\bullet)$.
\end{itemize}
From all of this we have
$\vDash_{\xM} (\bigwedge_{i=1}^n (s(p_i) = x_i)) \Rightarrow (u = u^{\bullet_X})$
for all subterms $u$ of $s$.
\end{proof}

