\LemmaIVxxii*
\begin{proof}
Let $p \in \Pos(s)$ and 
$\rho\colon \CRu{Z}{\ell}{r}{\pi}$ be a left-linear constrained rewrite rule
such that $\Var(\rho) \cap \Var(\varphi,s) = \varnothing$.
Suppose $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$.
Then we have~%
(1) $\Dom(\gamma) = \Var(\ell)$,~%
(2) $s|_p = \ell\gamma$,~%
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and~%
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.

Using the notation of \Cref{def:bullet translation},
let us define 
$\PG(\CTerm{X}{s}{\vec{x}}{\varphi}) = \CTerm{X'}{s^{\bullet_{X}}}{\pvec{x}'}{\varphi'}$,
i.e.\
$s^{\bullet_{X}} = s[x_1,\ldots,x_n]_{p_1,\ldots,p_n}$
for some pairwise distinct fresh variables $x_1,\ldots,x_n$,
set of positions $\SET{p_1,\ldots,p_n} = \Pos_{X\cup\Val}(s)$,
$X' = \SET{x_1,\ldots,x_n}$
and $\SET{\pvec{x}'} = \SET{\vec{x}} \cup X$
and 
$\varphi' = (\varphi \land \bigwedge_{i=1}^n (s|_{p_i} = x_i))$.

We first show 
$\CTerm{X'}{s^\bullet}{\pvec{x}'}{\varphi'}$
has a $\rho$-redex at $p$ by $\gamma^\bullet$.
Clearly,~(1') $\Dom(\gamma^\bullet) = \Dom(\gamma) = \Var(\ell)$.
By \Cref{lem:bullet translation and substitution},
we have~(2') $s^\bullet|_p = \ell\gamma^\bullet$.
Suppose $x \in \Var(\ell) \cap Z$.
Then $\gamma(x) \in \Val \cup X$,
which implies $\gamma(x) = s|_{p_i}$ for some $1 \le i \le n$.
Then, 
$\gamma^\bullet(x) 
= \gamma(x)^\bullet
= (s|_{p_i})^\bullet
= s^\bullet|_{p_i}
= (s[x_1,\ldots,x_n]_{p_1,\ldots,p_n})|_{p_i}
= x_i \in X' \subseteq \Val \cup X'$.
Thus,~(3') 
$\gamma^\bullet(x) \in \Val \cup X'$ for any $x \in \Var(\ell) \cap Z$
follows.
It remains to show~%
(4') $\vDash_\xM (\ECO{\pvec{x}'}{\varphi'}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma^\bullet})$.

For this, 
let $\vDash_{\xM,\xi} \ECO{\pvec{x}'}{\varphi'}$
for a valuation $\xi$.
This means,
$\vDash_{\xM,\xi} \ECO{\vec{x},\pvec{x}''}{\varphi \land \bigwedge_{i=1}^n (s|_{p_i} = x_i))}$,
where $\SET{\pvec{x}''}  = X$.
%
By \Cref{lem:bullet translation and validity},
$\vDash_{\xM} 
\bigwedge_{i=1}^n (s(p_i) = x_i)) \Rightarrow (\gamma(x) = \gamma(x)^\bullet)$
holds for any $x \in \xV$.
For, it trivially follows if $x \notin \Dom(\gamma)$,
and otherwise, $\gamma(x)$ is a subterm of $s$,
and thus \Cref{lem:bullet translation and validity} applies.
%
Note that $s(p_i) = s|_{p_i}$ for all $1 \leqslant i \leqslant n$.
This implies that 
$\vDash_{\xM,\xi} \ECO{\vec{x},\pvec{x}''}{\varphi 
\land (\bigwedge_{i=1}^n (s|_{p_i} = x_i))
\land (\bigwedge_{x \in \Var(\pi)}(\gamma(x) = \gamma(x)^\bullet))}$.
%
Hence, we obtain
$\vDash_{\xM,\xi} \ECO{\vec{x},\pvec{x}''}{\varphi \land 
(\bigwedge_{i=1}^n (s|_{p_i} = x_i)) \land (\pi\gamma \Leftrightarrow \pi\gamma^\bullet)}$.
Now, by definition,
there exists a sequence $\vec{v}\in \Val^*$ of values such that
$\vDash_{\xM,\xi} (\ECO{\vec{x}}{\varphi \land 
(\bigwedge_{i=1}^n (s|_{p_i} = x_i)) \land (\pi\gamma \Leftrightarrow \pi\gamma^\bullet)})\kappa$,
where $\kappa = \SET{\pvec{x}'' \mapsto \vec{v}}$.
%
By $\Dom(\kappa) = \SET{\pvec{x}''} = X$, it follows that
$\vDash_{\xM,\xi} \ECO{\vec{x}}{\varphi\kappa \land 
(\bigwedge_{i=1}^n (s|_{p_i}\kappa = x_i)) \land (\pi\gamma\kappa = \pi\gamma^\bullet)}$.
In particular, 
$\vDash_{\xM,\xi} \ECO{\vec{x}}{\varphi\kappa}$ holds and then
by $\Dom(\kappa) \cap \SET{\vec{x}} = \varnothing$,
we have $\vDash_{\xM,\xi} (\ECO{\vec{x}}{\varphi})\kappa$,
i.e.,  $\vDash_{\xM,\xi \circ \kappa} \ECO{\vec{x}}{\varphi}$.
Then, by~(4), it follows $\vDash_{\xM,\xi \circ \kappa} \ECO{\vec{z}}{\pi\gamma}$,
i.e., $\vDash_{\xM,\xi} (\ECO{\vec{z}}{\pi\gamma})\kappa$.
As $\SET{\vec{z}} \cap X = \varnothing$,
this implies $\vDash_{\xM,\xi} \ECO{\vec{z}}{\pi\gamma\kappa}$.
Moreover, by $\SET{\vec{x}} \cap \Var(\pi\gamma\kappa,\pi\gamma^\bullet) = \varnothing$,  
from $\vDash_{\xM,\xi} \ECO{\vec{x}}{(\pi\gamma\kappa \Leftrightarrow \pi\gamma^\bullet)}$
it follows that $\vDash_{\xM,\xi} (\pi\gamma\kappa \Leftrightarrow \pi\gamma^\bullet)$.
Thus, 
we obtain $\vDash_{\xM,\xi} \ECO{\vec{z}}{\pi\gamma^\bullet}$
and have proven~(4').

From all of this we obtain the rewrite step
$\CTerm{X'}{s^\bullet}{\pvec{x}'}{\varphi'}
\R^p_{\rho,\gamma^\bullet} \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$,
where
$t' = s^\bullet[r\gamma^\bullet]$,
$\psi' = \varphi' \land \pi\gamma^\bullet$,
$\SET{\pvec{y}'} = \Var(\psi') \setminus \Var(t')$, and
$Y' = \ExVar(\rho) \cup (X' \cap \Var(t'))$.

It remains to show 
$\CTerm{Y'}{t'}{\pvec{y}'}{\psi'} \sim \CTerm{Y}{t}{\vec{y}}{\psi}$.
For this, we use \Cref{lem:equivalence by mapping}
by taking
$\sigma = \SET{ x_i \mapsto s|_{p_i} \mid 1 \le i \le n, x_i \in Y' }$
and $V = \SET{ x_i \mid 1 \le i \le n, x_i \in Y' }$.
We refer to the conditions~(1)--(6) of \Cref{lem:equivalence by mapping} by~(C1)--(C6).
%
Clearly, (C1) $\sigma\colon V \to \xV  \cup \Val$ with $V \subseteq Y'$.
%
(C2) holds as $t'\sigma 
= s^\bullet[r\gamma^\bullet]\sigma 
= s^\bullet\sigma [r\gamma^\bullet\sigma]
= s[r\gamma] = t$.
%
Let $x_i,x_j \in Y'$ and $\sigma(x_i) = \sigma(x_j)$.
Then, $s|_{p_i} = s|_{p_j}$ and hence $\vDash_{\xM} \psi' \Rightarrow (s|_{p_i} = s|_{p_j})$.
By $x_i,x_j \in Y'$, we know that $x_i,x_j \notin \SET{\pvec{y}'}$,
and hence it follows $\vDash_{\xM} \ECO{\pvec{y}'}{\psi'} \Rightarrow (x_i = x_j)$.
From this we have~(C3).
%
Note that $Y' = \ExVar(\rho) \cup (X' \cap \Var(t'))
= \ExVar(\rho) \cup (\{ x_1,\ldots,x_n \} \cap \Var(t'))
$ and hence $V = \{ x_1,\ldots,x_n \} \cap \Var(t')$
and that $Y = \ExVar(\rho) \cup (\{ s|_{p_1},\ldots, s|_{p_n} \} 
\cap X \cap \Var(t))$.
Since $Y'\setminus V = \ExVar(\rho) = Y \setminus \sigma(V)$,
we have~(C4).
%
For~(C5), let $x \in Y'$ such that $\sigma(x) \in \xV$.
If $x \in V$ then $\sigma(x) \in Y$.
Otherwise $\sigma(x) = x$, and by $s\sigma = t$,
we know $x \in \Var(t)$. Hence $x \in \ExVar(\rho) \subseteq Y$.
Thus,~(C5) holds.
%
In order to show (C6), note first that 
$\FVar(\ECO{\pvec{y}'}{\psi'}) = \Var(\psi') \cap \Var(t')$ and
$\FVar(\ECO{\vec{y}}{\psi}) = \Var(\psi) \cap \Var(t)$.
Note that $\psi'\sigma = (\varphi' \land \pi\gamma^\bullet)\sigma 
= (\varphi \land \bigwedge_i (s|_{p_i} = x_i) \land \pi\gamma^\bullet)\sigma
= (\varphi \land \bigwedge_i (s|_{p_i} = s|_{p_i}) \land \pi\gamma)$
and $\psi = (\varphi \land \pi\gamma)$,
and hence $\Var(\psi'\sigma) =\Var(\psi)$. 
By $t'\sigma = t$
it follows
$\FVar((\ECO{\pvec{y}'}{\psi'})\sigma)
= \sigma(\FVar(\ECO{\pvec{y}'}{\psi'})) 
= \FVar(\ECO{\vec{y}}{\psi})$.
Finally, 
%since 
%$(\ECO{\pvec{y}'}{\psi'})\sigma
%= (\ECO{\pvec{y}'}{ \varphi' \land \pi\gamma^\bullet})\sigma
%= (\ECO{\pvec{y}'}{ (\varphi \land (\bigwedge_{i=1}^n (s|_{p_i} = x_i))) \land \pi\gamma^\bullet})\sigma
%$,
we have
\[
\begin{array}{lcl}
\vDash_\xM (\ECO{\pvec{y}'}{\psi'})\sigma
&\iff& \vDash_\xM 
(\ECO{\pvec{y}'}{ (\varphi \land (\bigwedge_{i=1}^n (s|_{p_i} = x_i))) \land \pi\gamma^\bullet})\sigma\\
&\iff& \vDash_\xM 
\ECO{\pvec{y}'}{ (\varphi \land (\bigwedge_{i=1}^n (s|_{p_i} = x_i\sigma))) \land \pi\gamma^\bullet\sigma}\\
&\iff& \vDash_\xM \ECO{\pvec{y}'}{(\varphi \land (\bigwedge_{i=1}^n (s|_{p_i} = s|_{p_i})) \land \pi\gamma}\\
&\iff& \vDash_\xM \ECO{\pvec{y}'}{ (\psi \land (\bigwedge_{i=1}^n (s|_{p_i} = s|_{p_i}))}\\
&\iff& \vDash_\xM \ECO{\pvec{y}'}{\psi}
\end{array}
\]
Thus, we have $\vDash_\xM (\ECO{\pvec{y}'}{\psi'})\sigma
 \Leftrightarrow (\ECO{\pvec{y}'}{\psi})$.
Since we can eliminate bound variables which do not appear in the constraint,
we conclude $\vDash_\xM (\ECO{\pvec{y}'}{\psi'})\sigma
 \Leftrightarrow (\ECO{\vec{y}}{\psi})$.
%
%It also holds that (C1-b) $\sigma(V) \cap Y \subseteq \SET{\pvec{y}'}$,
%as $\sigma(V) \cap Y \subseteq \Var(t)$,
%$V \subseteq \Var(\psi')$, and $Y' \cap \Var(t) = \varnothing$.
%
%Similarly,~(C4) for any $x,y \in V$,
%$\sigma(x) = \sigma(y)$ implies $\vDash_\xM \psi' \Rightarrow (\sigma(x) = \sigma(y))$
%holds.
\end{proof}

\TheoremIVxxiv*
\begin{proof}
Let $\CTerm{X}{s}{\vec{x}}{\varphi},
\CTerm{Y}{t}{\vec{y}}{\psi}$ be satisfiable existentially constrained terms
and $\rho$ a left-value-free constrained rewrite rule.
Suppose that
\[
\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} 
\gets_\rho 
\CTerm{X}{s}{\vec{x}}{\varphi} 
\sim
\CTerm{Y}{t}{\vec{y}}{\psi}
\]
%
Then by \Cref{lem:equivalence to pattern-general form by left-value-free rules},
there exists an existentially constrained term $\CTerm{X''}{s''}{\pvec{x}''}{\varphi''}$
such that 
\[
\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} 
\sim
\CTerm{X''}{s''}{\pvec{x}''}{\varphi''} 
\gets_\rho 
\PG(\CTerm{X}{s}{\vec{x}}{\varphi})
\]
%%
Since 
\[
\PG(\CTerm{X}{s}{\vec{x}}{\varphi})
\sim 
\CTerm{X}{s}{\vec{x}}{\varphi}
\sim 
\CTerm{Y}{t}{\vec{y}}{\psi}
\sim 
\PG(\CTerm{Y}{t}{\vec{y}}{\psi})
\]
we have
\[
\CTerm{X''}{s''}{\pvec{x}''}{\varphi''} 
\gets_\rho 
\PG(\CTerm{X}{s}{\vec{x}}{\varphi})
\sim 
\PG(\CTerm{Y}{t}{\vec{y}}{\psi})
\]
Hence, by \Cref{lem:commutativity of rewrite steps and equivalence for pattern-general terms},
there exists an existentially constrained term $\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$
such that
\[
\CTerm{X''}{s''}{\pvec{x}''}{\varphi''}
\sim 
\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}
\gets_\rho 
\PG(\CTerm{Y}{t}{\vec{y}}{\psi})
\]
Hence we get
\[
\CTerm{X'}{s'}{\pvec{x}'}{\varphi'} 
\sim
\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}
\gets_\rho 
\PG(\CTerm{Y}{t}{\vec{y}}{\psi}).
\]
\end{proof}

The following two lemmata are straightforward consequences of \Cref{def:existential-extension-and-existential-removing-translations}.

\begin{lemma}
For any non-quantified constrained term $\CTerm{X}{s}{}{\varphi}$,
$\ext(\CTerm{X}{s}{}{\varphi})$ is an existentially constrained term;
for any existentially constrained term $\CTerm{X}{s}{\vec{x}}{\varphi}$
$\rmv(\CTerm{X}{s}{\vec{x}}{\varphi})$ is a non-quantified constrained term.
\qed
\end{lemma}

\begin{lemma}
The translation $\rmv \circ \ext$ is the identity translation on non-quantified constrained terms;
the translation $\ext \circ \rmv$ is the identity translation on existentially constrained terms.
\qed
\end{lemma}

\begin{restatable}{lemma}{LemmaIVxxx}
\label{lem:equivalence of non-quantified terms with extra constraint}
Let $\CTerm{X}{s}{}{\varphi}$ be a non-quantified constrained term.   
Suppose $\vDash_\xM \varphi \Rightarrow \ECO{\vec{z}}{\pi}$
%with $\SET{\vec{z}} \cap (X \cup \Var(s)) = \varnothing$.
%%with \TA{$\SET{\vec{z}} = \Var(\pi) \setminus \Var(\varphi)$
%with \TA{$\SET{\vec{z}} \supseteq \Var(\pi) \setminus \Var(\varphi)$
with $\SET{\vec{z}} = \Var(\pi) \setminus (X \cup \Var(\varphi))$
and $\Var(s) \cap \SET{\vec{z}} = \varnothing$.
Then $\CTerm{X}{s}{}{\varphi} \sim \CTerm{X \cup \Var(\pi)}{s}{}{\varphi \land \pi}$.
\end{restatable}
%\LemmaIVxxx*
