\TheoremIVxxxi*
\begin{proof}
Let $\rho\colon \CRu{Z}{\ell}{r}{\pi}$ be a left-linear constrained rewrite rule and 
suppose that $\CTerm{X}{s}{\vec{x}}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{\vec{y}}{\psi}$ 
such that $\Var(s,\varphi) \cap \Var(\rho) = \varnothing$.
Then we have~%
(1) $\Dom(\gamma) = \Var(\ell)$,~%
(2) $s|_p = \ell\gamma$,~%
(3) $\gamma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$, and~%
(4) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$,
$t = s[r\gamma]$,
$\psi = \varphi \land \pi\gamma$,
$\SET{\vec{y}} = \Var(\psi) \setminus \Var(t)$, and
$Y = \ExVar(\rho) \cup (X \cap \Var(t))$.

Note that we have 
$\rmv(\CTerm{X}{s}{\vec{x}}{\varphi}) = \CTerm{X \cup \SET{\vec{x}}}{s}{}{\varphi}$.
We begin by showing the following equivalence:
\begin{equation}
\tag{5}
\label{eqn:first equivalence step}
\CTerm{X \cup \SET{\vec{x}}}{s}{}{\varphi}
\sim
\CTerm{X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)}
      {s}
      {}
      {\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}
\end{equation}
For this, we use \Cref{lem:equivalence of non-quantified terms with extra constraint}.
By~(4),  %$\xM \JS{\vDash} (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\gamma})$,
we have that $\vDash_\xM \varphi \Rightarrow \ECO{\vec{z}}{\pi\gamma}$ holds.
Since we have $\vDash_\xM \bigwedge_{z \in \ExVar(\rho)} (z = z)$,
also $\vDash_\xM \varphi \Rightarrow \ECO{\vec{z}}{\pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}$
holds.
Now, we have
\[
\begin{array}{cl}
&\Var(\pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z))
\setminus (X \cup \SET{\vec{x}} \cup \Var(\varphi))\\
=& ((\Var(\pi) \setminus \Var(\ell))
\cup (\bigcup_{y \in \Var(\ell) \cap \Var(\pi)} \Var(\gamma(y)))
\cup \ExVar(\rho))
\setminus (X \cup \SET{\vec{x}} \cup \Var(\varphi))\\
=&
((\Var(\pi) \setminus \Var(\ell))
\cup \ExVar(\rho))
\setminus (X \cup \SET{\vec{x}} \cup \Var(\varphi))\\
=& \Var(r,\pi) \setminus \Var(\ell).
\end{array}
\]
%%%
Take 
$\SET{\pvec{z}'} = \Var(r,\pi) \setminus  \Var(\ell) =
\Var(\pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z))
\setminus (X \cup \SET{\vec{x}} \cup \Var(\varphi))$.
By $\Var(\rho) \cap \Var(s) = \varnothing$,
we have $\SET{\pvec{z}'} \cap \Var(s) = \varnothing$.
Furthermore, since $\SET{\pvec{z}'} \supseteq \ExVar(\rho) = \SET{\vec{z}}$,
we have
$\vDash_\xM \varphi \Rightarrow \ECO{\pvec{z}'}{\pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}$.
Thus, by \Cref{lem:equivalence of non-quantified terms with extra constraint},
we conclude the equivalence~(\ref{eqn:first equivalence step}).

We proceed to show the rewrite step
\begin{eqnarray}\label{eqn:intermediate rewrite step}
\setcounter{equation}{6}
&&\CTerm{X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)}
      {s}
      {}
      {\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}\\\nonumber
&\R^p_{\rho'}&
\CTerm{Y \cup \SET{\vec{y}} \cup \ExVar(\rho)}
      {t}
      {}
      {\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}
\end{eqnarray}
over the non-quantified constrained terms, 
by a variant $\rho'\colon \CRu{Z'}{\ell'}{r'}{\pi'}$ of the constrained rewrite rule $\rho$
such that $\Var(\rho) \cap \Var(\rho') = \varnothing$.
Accordingly, we have a variable renaming $\xi$ such 
that $Z = \xi(Z')$, $\ell = \ell'\xi$, $r = r'\xi$, and $\pi = \pi'\xi$.
We also suppose that
$\Var(\rho') \cap
\Var(s,\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)) =
\varnothing$.


%$\CTerm{X}{s}{}{\varphi} \R^p_{\rho,\sigma} \CTerm{Y}{t}{}{\varphi}$
%if there exists a position $p \in \FPos(s)$, a substitution $\sigma$ with
%$\Dom(\sigma) = \Var(\ell,r,\pi)$,
%$\ell\sigma = s|_p$, $\sigma(x) \in \Val \cup X$ for all $x \in Z$, and
%$\xM \JS{\vDash} \varphi \Rightarrow \pi\sigma$,
%where $t = s[r\sigma]_p$ and $Y = X \cap \Var(t, \varphi)$.
%
%Take $\delta = \gamma \cup \SET{ z \mapsto z \mid \textcolor{red}{z \in \Var(r,\pi) \setminus \Var(\ell)} }$.
Take $\delta = \gamma \circ \xi$.
Then, by~(1) and our assumption on $\xi$, 
we have $\Dom(\delta) = \Var(\ell',r',\pi')$. 
%Also, $s|_p = \ell\gamma = \ell\delta$ holds by (2) and the definition of $\delta$.
Also, $\ell'\delta = \ell'\xi\gamma = \ell\gamma = s|_p$ holds
by~(2) and the definition of $\delta$.

We now show $\delta(x) \in \Val \cup X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)$
for all $x \in Z'$.
To this end assume that $x \in Z'$.
If $x \in \Var(\ell')$,
then $\delta(x) = x\xi\gamma = \gamma(y)$ for some $y \in \Var(\ell) \cap Z$.
Hence, $\delta(x) \in \Val \cup X$ by~(3).
Thus, suppose $x \in Z' \setminus \Var(\ell')$.
Then, because of $Z' \subseteq \Var(\ell',r',\pi')$, 
we know $x \in \Var(r',\pi') \setminus \Var(\ell')$.
Thus, $\delta(x) = x\xi\gamma = \gamma(y)$ for some $y \in \Var(r,\pi) \setminus \Var(\ell)$.
Hence, if $y \in \Var(\pi) \setminus \Var(\ell)$ then $\delta(x) = \gamma(y) \in \Var(\pi\gamma)$,
and if $y \in \Var(r) \setminus \Var(\ell)$ then $\delta(x) = \gamma(y) = y \in \ExVar(\rho)$.

Furthermore, we have $\vDash_\xM 
(\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z))
\Rightarrow \pi'\delta$, because $\pi'\delta = \pi'\xi\gamma = \pi\gamma$.
We also have $t = s[r\gamma]_{p} = s[r'\xi\gamma]_p = s[r'\delta]_p$.
Thus, it remains to show that
$Y \cup \SET{\vec{y}} \cup \ExVar(\rho)
= 
(X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)) \cap 
\Var(t, \varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z))$.
%we know by \Cref{lem:bound variables of constraint of reducts}}
%$Y \cup \SET{\vec{y}}
%= \Var(\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z))
%\cup (X \cap \Var(t)) \cup \ExVar(\rho)$.
We denote the right-hand side of the equation by $rhs$, and obtain:
\begin{align*}
(rhs) 
&= ((X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)) \cap \Var(t))\\
& \quad\cup  ((X \cup \SET{\vec{x}} \cup \Var(\pi\gamma) \cup \ExVar(\rho)) \cap 
\Var(\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)))\\
&=  (X \cap \Var(t)) \cup (\Var(\pi\gamma) \cap \Var(t))
\cup \Var(\varphi \land \pi\gamma) \cup \ExVar(\rho)\\
&= 
(X \cap \Var(t)) \cup 
(\Var(\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)))
\cup \ExVar(\rho)\\
&= 
Y \cup \SET{\vec{y}} \cup \ExVar(\rho) 
% \hfill \mbox{by \Cref{lem:bound variables of constraint of reducts}}\\
\qquad \text{(by \Cref{lem:bound variables of constraint of reducts})}
\end{align*}
%\textcolor{red}{our rule is not left-linear? Lemma~4.8 does not apply?}
Putting all of this together gives the rewrite step~(\ref{eqn:intermediate rewrite step}).
To complete the proof, we need to show the equivalence 
\begin{align*}
\CTerm{Y \cup \SET{\vec{y}} \cup \ExVar(\rho)}
      {t}
      {}
      {\varphi \land \pi\gamma \land \bigwedge_{z \in \ExVar(\rho)} (z = z)}
&\sim  \CTerm{Y \cup \SET{\vec{y}}}{t}{\vec{y}}{\varphi \land \pi\gamma})\\
&= \rmv(\CTerm{Y}{t}{\vec{y}}{\psi})
\end{align*}
which should be trivial to see.
\end{proof}

\TheoremIVxxxii*
\begin{proof}
Assume $\CTerm{X}{s}{}{\varphi} \R^p_{\rho,\gamma} \CTerm{Y}{t}{}{\varphi}$
where $\rho\colon\CRu{Z}{\ell}{r}{\pi}$ is a left-linear constrained rewrite rule
with $\Var(\rho) \cap (X \cup \Var(s,\varphi)) = \varnothing$.
Note that this is a rewrite step for non-quantified constrained terms.
Thus,  we have~%
(1) $\Dom(\gamma) = \Var(\ell,r,\pi)$,~%
(2) $s|_p = \ell\gamma$,~%
(3) $\gamma(x) \in \Val \cup X$ for all $x \in Z$, and~%
(4) $\vDash_\xM \varphi \Rightarrow \pi\gamma$.
Furthermore, $t = s[r\gamma]_p$ and $Y = X \cap \Var(t, \varphi)$.
W.l.o.g.\ we assume $\Var(\rho) \cap (Y \cup \Var(t,\varphi)) = \varnothing$.
%
Let $\ext(\CTerm{X}{s}{}{\varphi}) = \CTerm{X\setminus \SET{\vec{x}}}{s}{\vec{x}}{\varphi}$
with $\SET{\vec{x}} = \Var(\varphi) \setminus \Var(s)$
and let $\ext(\CTerm{Y}{t}{}{\psi}) = \CTerm{Y \setminus \SET{\vec{y}}}{t}{\vec{y}}{\psi}$,
with $\vec{y} = \Var(\psi) \setminus \Var(t)$.    

We first show that
$\CTerm{X\setminus \SET{\vec{x}}}{s}{\vec{x}}{\varphi}$ has a $\rho$-redex
at position $p$ using a substitution $\sigma = \gamma|_{\Var(\ell)}$.
For this, we need to show~%
(5) $\Dom(\sigma) = \Var(\ell)$,~%
(6) $s|_p = \ell\sigma$,~%
(7) $\sigma(x) \in \Val \cup (X \setminus \SET{\vec{x}})$ for any $x \in \Var(\ell) \cap Z$, and~%
(8) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\sigma})$,
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$.
(5) is obvious by definition of $\sigma$.
Similarly,~(6) follows as $s|_p = \ell\gamma = \ell\sigma$ by~(2).
%
We have $\sigma(x) \in \Val \cup X$ for any $x \in \Var(\ell) \cap Z$,
because $\sigma(x) = \gamma(x)$ for all $x \in \Var(\ell)$ and $\gamma(x) \in \Val \cup X$ by~(3);
moreover, if $\sigma(x) \in X$, 
then, as $\sigma(x)  \in \Var(\ell\sigma) \subseteq \Var(s)$ by $x \in \Var(\ell)$,
we have $\sigma(x) \in X \cap \Var(s)$, 
which implies that $\sigma(x) \notin \SET{\vec{x}} = \Var(\varphi) \setminus \Var(s)$.
Hence~(7) $\sigma(x)  \in \Val \cup (X \setminus \SET{\vec{x}})$ for any $x \in \Var(\ell) \cap Z$.

It remains to show~%
(8) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\sigma})$.
%
First of all, note that by definition of $\sigma$ and $\Var(\rho) \cap \Var(s) = \varnothing$, 
we have $\gamma = \gamma' \circ \sigma$ where
$\gamma' = \SET{ z \mapsto \gamma(z) \mid z \in \Var(r,\pi) \setminus \Var(\ell) }$.
%
Suppose $\vDash_{\xM,\xi} \ECO{\vec{x}}{\varphi}$ for a valuation $\xi$.
Then, for some $\kappa = \SET{ \vec{x} \mapsto \vec{v} }$ with $\vec{v} \in \Val^*$
we have $\vDash_{\xM,\xi \circ \kappa} \varphi$.
Hence, from~(4) %$\xM \JS{\vDash} \varphi \Rightarrow \pi\gamma$.
it follows $\vDash_{\xM,\xi \circ \kappa} \pi\gamma$.
Then, by $\gamma = \gamma' \circ \sigma$,
we have $\vDash_{\xM,\xi \circ \kappa} \ECO{\vec{z}}{\pi\sigma}$
where $\SET{\vec{z}} = \Var(\pi) \setminus \Var(\ell)$.
Also, $\FVar(\ECO{\vec{z}}{\pi\sigma}) \subseteq \Var(\ell\gamma) \subseteq \Var(s)$.
Since $\Dom(\kappa) = \SET{\vec{x}} = \Var(\varphi) \setminus \Var(s)$,
%we know $\Dom(\kappa) \cap \Var(s) = \varnothing$,
we know $\Dom(\kappa) \cap \FVar(\ECO{\vec{z}}{\pi\sigma}) = \varnothing$,
and thus $(\ECO{\vec{z}}{\pi\sigma})\kappa = \ECO{\vec{z}}{\pi\sigma}$.
Hence, $\vDash_{\xM,\xi} \ECO{\vec{z}}{\pi\sigma}$ follows
and therefore we have shown that~%
(8) $\vDash_\xM (\ECO{\vec{x}}{\varphi}) \Rightarrow (\ECO{\vec{z}}{\pi\sigma})$
holds.

We conclude that $\CTerm{X\setminus \SET{\vec{x}}}{s}{\vec{x}}{\varphi}$ has a $\rho$-redex
at position $p$ using the substitution $\sigma$.
Consequently, we obtain the rewrite step 
$\CTerm{X\setminus \SET{\vec{x}}}{s}{\vec{x}}{\varphi}
\R^p_{\rho,\sigma} \CTerm{Y'}{t'}{\pvec{y}'}{\psi'}$
where
$t' = s[r\sigma]_p$,
$\psi' = \varphi \land \pi\sigma$,
$\SET{\pvec{y}'} = \Var(\psi') \setminus \Var(t')$, and
$Y' = \ExVar(\rho) \cup ((X \setminus \SET{\vec{x}}) \cap \Var(t'))$.

In order to complete the proof, it remains to show
$\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}
\supsetsim \CTerm{Y\setminus \SET{\vec{y}}}{t}{\vec{y}}{\psi}$.

Prior to that, let us show 
$\SET{\vec{y}} \subseteq  \SET{\pvec{y}'}$.
Let $w \in \SET{\vec{y}} = \Var(\varphi) \setminus \Var(t)$.
Since $\SET{\pvec{y}'} = \Var(\varphi \land \pi \gamma ) \setminus \Var(t')$,
it suffices to show that for any $w \in \Var(\varphi)$,
it holds that $w \in \Var(t')$ implies $w \in \Var(t)$.
Since $t' = s[r\sigma]$ and $t = s[r\gamma]$,
the case $w \in \Var(s[~])$ is trivial.
Thus, suppose $w \in \Var(r\sigma)$.
Then either $w \in \ExVar(\rho)$ or
$w \in \Var(x\sigma)$ for some $x \in \Var(\ell) \cap \Var(r)$.
The former case contradicts with $w \in \Var(\varphi)$ because $\Var(\varphi) \cap \Var(\rho) = \varnothing$.
In the latter case, $w \in \Var(r\gamma)$ follows,
as $\sigma(x) = \gamma(x)$ for $x \in \Var(\ell)$.

We proceed to show that 
$\CTerm{Y'}{t'}{\pvec{y}'}{\psi'}
\supsetsim \CTerm{Y\setminus \SET{\vec{y}}}{t}{\vec{y}}{\psi}$.
Let $\theta$ be a 
$(Y \setminus \SET{{\vec{y}}})$-valued substitution
such that $\theta \vDash_{\xM} \ECO{\vec{y}}{\psi}$,
i.e.\ 
$((\Var(\psi) \cup Y) \setminus \SET{{\vec{y}}}) \subseteq \VDom(\theta)$
and $\vDash_{\xM} (\ECO{\vec{y}}{\psi})\theta$.
We will prove there exists a substitution $\theta'$
such that it is $Y'$-valued and $\theta' \vDash \ECO{\pvec{y}'}{\psi'}$, i.e.\ 
$(Y' \cup (\Var(\psi') \setminus \SET{\pvec{y}'})) \subseteq \VDom(\theta')$
and $\vDash_\xM (\ECO{\pvec{y}'}{\psi'})\theta'$,
which satisfies $t\theta  = t'\theta'$.
For this purpose, we assume w.l.o.g.\ 
\begin{itemize}
    \item $\Dom(\theta) \cap \Var(\rho) = \varnothing$,
    \item $\Dom(\theta) \cap \SET{\vec{y}} = \varnothing$, and
    \item $\Var(\theta(z)) \cap \SET{\vec{y}} = \varnothing$ 
    for any $z \in \FVar(\ECO{\vec{y}}{\psi})$.
\end{itemize}
Note here also $\SET{\vec{y}} \cap \Var(t) = \varnothing$, as 
$\SET{\vec{y}} = \Var(\varphi) \setminus \Var(t)$.
%
%Since we assumed $\Var(\rho) \cap (Y \cup \Var(t,\varphi)) = \varnothing$,
%w.l.o.g.\ we further assume $\Dom(\theta) \cap \Var(\rho) = \varnothing$.
Let us define $\theta' = \theta \cup \SET{ z \mapsto z\gamma\theta 
\mid z \in \Var(r,\pi) \setminus \Var(\ell) }$.
%
As a first step, we show that $\theta(\gamma(x)) = \theta'(\sigma(x))$ for
any $x \in \Var(\rho)$.
%
Suppose that $x \in \Var(\ell)$.
Then $\gamma(x) = \sigma(x)$ and since $x\gamma$ is a subterm of $\ell\gamma$,
we have that $\Var(\gamma(x)) \cap \Var(\rho) = \varnothing$.
In particular, $\Var(\gamma(x)) \cap (\Var(r,\pi) \setminus \Var(\ell)) = \varnothing$,
thus, by definition of $\theta'$, we have $\theta'(\gamma(x)) = \theta(\gamma(x))$.
Hence $\theta(\gamma(x)) = \theta'(\gamma(x)) = \theta'(\sigma(x))$.
%
Otherwise, suppose that $x \in (\Var(r,\pi) \setminus \Var(\ell))$.
Then, by definition of $\theta'$, we have $\theta'(x) = \theta(\gamma(x))$.
Since $\Dom(\sigma) = \Var(\ell)$, we have $\sigma(x) = x$ and
thus $\theta(\gamma(x)) = \theta'(x) = \theta'(\sigma(x))$.

We conclude that $\theta(\gamma(x)) = \theta'(\sigma(x))$ for any $x \in \Var(\rho)$.
From this, it follows that $\pi\gamma\theta = \pi\sigma\theta'$
and $r\gamma\theta = r\sigma\theta'$.
We further have $\theta'(x) = \theta(x)$ for any $x \in \Var(s)$
by definition of $\theta'$ as $\Var(s) \cap \Var(\rho) = \varnothing$.
Therefore, we have
$t\theta = s[r\gamma]\theta = s\theta[r\gamma\theta]
= s\theta'[r\sigma\theta'] = s[r\sigma]\theta' =  t'\theta'$.

Let us claim that $\theta'(Y') \subseteq \Val$.
%$Y' = \ExVar(\rho) \cup ((X \setminus \SET{\vec{x}}) \cap \Var(t'))$
Assume $y \in Y'$.
We are now going to show that $\theta'(y) \in \Val$ by distinguishing two cases.
\begin{itemize}
\item 
Assume $y \in \ExVar(\rho)$.
Then, $y \in \Var(r) \setminus \Var(\ell)$ and hence
$\theta'(y) = \theta(\gamma(y))$.
Since $\Var(r,\pi) \setminus \Var(\ell) \subseteq Z$ by the definition of $\rho$,
we have that $\gamma(y) \in \Val \cup X$ by our condition~(3).
%
In case $\gamma(y) \in \Val$,
clearly, $\theta'(y) = \theta(\gamma(y)) = \gamma(y) \in \Val$.
%
Otherwise, we have $\gamma(y) \in X$.
As $y \in \ExVar(\rho)$ and $\Dom(\gamma) = \Var(\ell,r,\pi)$,
$\gamma(y)$ appears in $t = s[r\gamma]$.
Thus, we have $\gamma(y) \in \Var(t)$.
Moreover, by $\SET{\vec{y}} = \Var(\varphi) \setminus \Var(t)$, 
we know that $\gamma(y) \notin \SET{\vec{y}}$.
Thus, $\gamma(y) \in 
(X \cap \Var(t,\varphi)) \setminus \SET{\vec{y}}
= Y \setminus \SET{\vec{y}}$.
As $\theta$ is $(Y \setminus \SET{\vec{y}})$-valued,
we conclude $\theta'(y) = \theta(\gamma(y)) \in \Val$.


\item 
Assume $y \notin \ExVar(\rho)$.
As $Y' = \ExVar(\rho) \cup ((X \setminus \SET{\vec{x}}) \cap \Var(t'))$,
we have $y \in ((X \setminus \SET{\vec{x}}) \cap \Var(t'))$.
%
If $y \notin \Var(t) = \Var(s[r\gamma]_p)$,
then, as $y \in \Var(t') = \Var(s[r\sigma]_p)$ and $\sigma = \gamma|_{\Var(\ell)}$,
we have $y \in \ExVar(\rho)$.
This contradicts our assumption and
therefore $y \in \Var(t)$.
%
Then, since $y \in X$, we have $y \in (X \cap \Var(t,\varphi)) = Y$.
Also, by $\SET{\vec{y}} = \Var(\varphi) \setminus \Var(t)$,
we know that $y \notin \SET{\vec{y}}$.
Thus, it follows that $y \in Y \setminus \SET{\vec{y}}$,
and moreover, that $\theta(y) \in \Val$ as $\theta$ is $(Y \setminus \SET{\vec{y}})$-valued.
% 
As $y \notin \ExVar(\rho)$, we have $\theta'(y) = \theta(y)$
and we obtain $\theta'(y) \in \Val$.
\end{itemize}

It remains to show that 
$\theta' \vDash_{\xM} \ECO{\pvec{y}'}{\psi'}$.
%
First, 
$\FVar(\ECO{\pvec{y}'}{\psi'}) \subseteq \VDom(\theta')$
follows from $\FVar(\ECO{\pvec{y}'}{\psi'}) \subseteq Y'$
and the fact that $\theta'$ is $Y'$-valued as shown above.
%
%Suppose $y \in \FVar(\ECO{\pvec{y}'}{\psi'})$.
%Then $y \in \Var(\psi') \cap \Var(t')$ by the definition of $\SET{\pvec{y}'}$.
%Also, $y \in (\Var(\varphi,\pi\sigma) \setminus \SET{\pvec{y}'})$ by the definition of $\psi'$.
%Thus, we have $y \notin \SET{\pvec{y}'}$,
%and either $y \in \Var(\varphi)$ or $y \in \Var(\pi\sigma)$.
%
%First, suppose $y \in \Var(\varphi)$.
%Then, by $y \in (\Var(\varphi) \setminus \SET{\pvec{y}'})$
%and $\SET{\vec{y}} \subseteq \SET{\pvec{y}'}$,
%we have $y \in \FVar(\ECO{y}{\varphi})$.
%Hence, $\theta(y) \in \Val$ as $\theta$ is 
%$(\Var(\varphi) \setminus \SET{\vec{y}})$-valued.
%Then, by $y \in \Var(\varphi)$,
%we have $\theta'(y) = \theta(y) \in \Val$.
%
%Next, suppose $y \notin \Var(\varphi)$.
%Thus, $y \in \Var(\pi\sigma)$.
%Then, we know either $y \in (\Var(\pi) \setminus \Var(\ell))$
%or $y \in \Var(\sigma(z))$ for some $z \in \Var(\ell)\cap\Var(\pi)$.
%\begin{itemize}
%   \item Assume $y \in (\Var(\pi) \setminus \Var(\ell))$.
%We have already shown $\theta'(x) \in \Val$ for $y \in \Var(r) \setminus \Var(\ell))$.
%Thus, let us consider the case $y \notin \Var(r)$.
%But then we don't have $y \in \Var(t')$,
%and thus this is a contradiction.
%   \item 
%Assume $y \in \Var(\sigma(z))$ for some $z \in \Var(\ell)\cap\Var(\pi)$.
%Then $y \in \Var(t')$,
%$y \in \Var(t)$,
%...
%\end{itemize}
%
%
It remains to show that $\vDash_{\xM} (\ECO{\pvec{y}'}{\psi'})\theta'$.
From $\vDash_{\xM} (\ECO{\vec{y}}{\varphi})\theta$,
there exists a valuation $\eta = \SET{ \vec{y} \mapsto \vec{v} }$ with $\vec{v} \in \Val^*$
such that $\vDash_{\xM} \varphi\eta\theta$.
%%
%Here, w.l.o.g.\ assume 
%$\Var(\pi\gamma\theta) \cap \SET{\vec{y}} = \varnothing$ \textcolor{red}{(?possible?)}
%so that $\theta \JS{\cdot} \eta = \eta \JS{\cdot} \theta$.
%Then, we have $\vDash_\xM \varphi\theta\eta$.
Using the second and third assumption on $\theta$ which we have 
assumed above w.l.o.g.,
it follows that $\vDash_{\xM} \varphi\theta\eta$.
%%
Thus, from~(4), we have that $\vDash_\xM \pi\gamma\theta\eta$,
and hence $\vDash_\xM \pi\sigma\theta'\eta$.
Again, using the second and third assumptions on $\theta$,
it follows that $\vDash_\xM \pi\sigma\eta\theta'$.
%
Also, from $\Var(\rho) \cap \Var(\varphi) = \varnothing$,
we have that $\varphi\theta = \varphi\theta'$,
and using our assumptions on $\theta$ 
it also follows that $\varphi\eta\theta = \varphi\eta\theta'$.
%
Therefore, $\vDash_\xM \varphi\eta\theta'$ holds and we conclude that
$\vDash_\xM (\varphi \land \pi\sigma)\eta\theta'$.
We obtain that $\vDash_\xM \ECO{\vec{y}}(\varphi \land \pi\sigma)\theta'$,
and $\SET{\vec{y}} \subseteq  \SET{\pvec{y}'}$ implies that
$\vDash_\xM \ECO{\pvec{y}'}(\varphi \land \pi\sigma)\theta'$.
We ultimately have $\theta' \vDash_\xM \ECO{\pvec{y}'}{\psi'}$ which concludes 
the proof.
\end{proof}


