\mathbf{H} &= \mathbf{h}(\theta, z) e^{-i (\omega_0 t + k_0 x \cos(\theta) + k_0 y \sin(\theta))} 
\\
\mathbf{E} &= \mathbf{e}(\theta, z) e^{-i (\omega_0 t + k_0 x \cos(\theta) + k_0 y \sin(\theta))} 
