\notag \\
& \hspace{45pt}
- \left(\frac{k_0}{\beta_b}\right) \left(e^{-k_0 d} \hat{h}_z^{(w^+)}  - e^{k0 d} \hat{h}_z^{(w-) }\right)
\end{align}
\end{subequations}
The $x$ and $y$ components of  $\mathbf{h}^{(w^+)} $ and $\mathbf{h}^{(w^-)} $ are found as 
\begin{multline}
\left[
\begin{array}{cc}
