\begin{align}
\mathbf{H}(x,y,z,t) &= \mathcal{R}e \bigg\{ \int_{-\pi/2}^{\pi/2} \mathbf{h}(\theta, z) A(\theta) \kappa({\theta})  \nonumber\\
