\subsection{Physics-Informed Residual Neural Networks (PIRNN): A Refined Solution}

DRNNs outperform NNs in deep learning tasks by addressing the vanishing gradient issue. However, traditional DRNNs are limited by their exclusive reliance on data-driven learning and their inability to incorporate underlying physical laws directly into the modeling process as discussed in section \ref{sec:Numerical Results}. Consequently, this limitation can result in solutions that may lead to rather significant errors as observed in the numerical results.

Physics-Informed Residual Neural Networks (PIRNNs) address this limitation by integrating the governing physical laws directly into the neural network's loss function. This integration ensures that the solutions not only fit the data but also adhere to fundamental physical laws, thereby enhancing their accuracy and reliability for modeling wave propagation problems.  %This approach makes PIRNNs particularly suitable for real-world applications where data may be scarce or expensive to obtain. 
%Let $\boldsymbol{G}(\theta)=[\boldsymbol{G}(\theta, 0), \boldsymbol{G}(\theta, \frac{1}{f_0}),...,\boldsymbol{G}(\theta, \frac{K-1}{f_0})]$,  $F(\boldsymbol{\tau})=[F(\boldsymbol{\tau}, 0), F(\boldsymbol{\tau}, \frac{1}{f_0}),...,F(\boldsymbol{\tau},\frac{K-1}{f_0})]$ and $\boldsymbol{H}=[\boldsymbol{H}(0), \boldsymbol{H}(\frac{1}{f_0}),...,\boldsymbol{H}(\frac{K-1}{f_0})]$
We formulate the proposed PIRNN loss function as follows:
\begin{align}
    \label{eq:loss_pirnn}
    \mathcal{L}_{\text{PIRNN}}(\boldsymbol{\tau}) 
    &=
    \mathbb{E} \left\{\|{\mathcal{\boldsymbol{\mathcal{H}}}} -         \mathcal{R}e \int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} \boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau}) \mathcal{F}(\theta,\boldsymbol{\tau}) d\theta\|^2 \right\}
\end{align}
where $\boldsymbol{\mathcal{H}}$ is given by \eqref{eq:calH}, and $\boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau})$, $\mathcal{F}(\theta,\boldsymbol{\tau})$  are expressed as 
\begin{align}
\label{eq:loss_pirnn_param}
        \boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau})
        &=
        \left[\boldsymbol{G}(\theta, 0;\hat{\Pv}(\boldsymbol{\tau})),... ,\boldsymbol{G}(\theta, \frac{K-1}{f_0};\hat{\Pv}(\boldsymbol{\tau}))\right]\bigg|_{\Penv,\Psen}
        \notag
        \\
    \mathcal{F}(\theta,\boldsymbol{\tau})
        &=
        \left[F(\theta,0;\hat{\Pv}(\boldsymbol{\tau})),...,F(\theta,\frac{K-1}{f_0};\hat{\Pv}(\boldsymbol{\tau}))\right]\bigg|_{\Penv,\Psen}
\end{align}
In \eqref{eq:loss_pirnn_param},  $\hat{\Pv}(\boldsymbol{\tau})$ denotes the estimation of $\Pv$ which is obtained as the output of the PIRNN using the ground truth sample data $\boldsymbol{\mathcal{H}}$ as input. The corresponding physics-informed estimation of $\boldsymbol{\mathcal{H}}$ is denoted by the term   $\mathcal{R}e \int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} \boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau}) \mathcal{F}(\theta,\boldsymbol{\tau}) d\theta$  in \eqref{eq:loss_pirnn}. This term depends on the output of PRINN, $\hat{\Pv}(\boldsymbol{\tau})$ as seen in \eqref{eq:loss_pirnn_param}. 
% \begin{align}
%     \label{eq:loss_pirnn}
%     \mathcal{L}_{\text{PIRNN}}(\boldsymbol{\tau}) 
%     &=
%     \frac{1}{\Ns} \sum_{i=1}^{\Ns} \|\mathbf{H}_i -         \mathcal{R}e \int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} \boldsymbol{G}_i(\theta) F_i(\boldsymbol{\tau}) d\theta\|^2
% \end{align}
%To train the parameters of the neural network ($\boldsymbol{\tau}$), $\Ns$ points for each variable are selected randomly with a uniform distribution from the variable's working space to predict the value of $F(\mathbf{x}_i,\tau)$ in forward propagation neural network. The goal of PIRNN training is to minimize the related loss function using the backpropagation algorithm. 
We adopt the Monte Carlo method to evaluate the integral term in \eqref{eq:loss_pirnn}. This approach is tailored to strengths and adaptability in calculating complex, high-dimensional integral. % which often present challenges for traditional numerical methods. 
Its reliance on random sampling enables accurate estimations even when dealing with intricate, irregular, or discontinuous functions, obviating the need for complex mathematical transformations. 
The integral term in \eqref{eq:loss_pirnn} can be calculated based on the Monte Carlo method as follows:
\begin{multline}
\label{eq:mont-carlo}
\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} \boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau}) \mathcal{F}(\theta,\boldsymbol{\tau}) d\theta
\approx 
\\
\frac{\pi}{N_{\text{mont-carlo}}} \sum_{j=1}^{N_{\text{mont-carlo}}} \boldsymbol{\mathcal{G}}(\theta_j,\boldsymbol{\tau}) \mathcal{F}(\theta_j,\boldsymbol{\tau}), \quad \boldsymbol{\theta}_j \sim \mathrm{U}\left(-\frac{\pi}{2}, \frac{\pi}{2}\right)
\end{multline}
where $\mathrm{U}(\cdot,\cdot)$ is the uniform probability distribution function and $N_{\text{mont-carlo}}$ denotes the number of samples randomly selected within the interval of integration.

%Recognizing the explicit influence of $\Penv$ and $\Psen$ on the value of the integral term in \textbackslash{}eqref\{eq:loss\_pirnn\}, to train the PIRNN, we formulate the input-output data pair corresponding to each dataset sample as follows: 

% \begin{align}
% \label{eq:pIRNN_Input}
%     (\boldsymbol{X},\boldsymbol{Y})=\left(\underbrace{{\boldsymbol{\mathcal{H}}}, {\Penv}, {\Psen}}_{{\boldsymbol{X}}} ,\underbrace{{\Pv}}_{{\boldsymbol{Y}}}\right)
% \end{align}

Two observations are noteworthy in this context. Firstly, it is seen that the values of the environmental and sensor parameters, $\Penv$ and $\Psen$, are directly incorporated into the computation of the PIRNN loss function expressed in \eqref{eq:loss_pirnn}. In contrast, these parameters are not utilized in the loss function of DRNN in \eqref{eq:loss_drnn}.
Secondly, the non-physics-informed loss function in \eqref{eq:loss_drnn} directly depends on the vessel length $\Ls$ as one of the elements of $\Pv$, whereas  the physics-informed loss function in \eqref{eq:loss_pirnn}  depends on the magnetic field $\boldsymbol{\mathcal{H}}$. To compare the efficiency of these two loss functions within the learning algorithm, we propose the error function for the learning algorithm, which is formulated as follows:
\begin{align}
\label{eq:final error}
    \mathcal{E(\boldsymbol{\tau})}= \frac{1}{\Nb} \sum_{i=1}^{\Nb} \|L_i - \hat{L}_i( \boldsymbol{\tau})\|^2
\end{align}
where $\Nb<\Ns$ is the size of  training mini-batch that sampled from training-dataset of size $\Ns$ and $L_i$ is the true vessel length $\Ls$ of the $i$'th sample in the mini-batch dataset and $\hat{L}_i( \boldsymbol{\tau})$ is the corresponding vessel length estimated using DRNN/PIRNN.
%This error function is related to length and analogous to each other and are solely for the purpose of comparing the efficiencies of Algorithms DRNN and PIRNN. 
%The primary objectives minimized in the two algorithms are the loss functions represented in \eqref{eq:loss_drnn} and \eqref{eq:loss_pirnn}, respectively.

\begin{algorithm}
\caption{DRNN/PIRNN training process}
\begin{algorithmic}[1]
%\Statex \hspace{-20pt} \textbf{Main Procedure:}      
\Statex \hspace{-20pt} \textbf{Input Parameters:} 
        %\State $\Ns$: Size of training-dataset
        \State $\{(\boldsymbol{X},\boldsymbol{Y})\}$: Training-dataset
        % \State $\Nb$: Size of training mini-batch
        \State $M$: Number of training iterations

\Statex \hspace{-20pt} \textbf{Output Parameters:} 
    \State $\boldsymbol{\tau}$: Learnable Parameters of the residual neural network for the estimation of  the vessel parameters $\hat{\Pv}(\boldsymbol{\tau})$.
\Statex \hspace{-20pt} \textbf{Initialization:} 
\State Initialize the neural network parameter $\boldsymbol{\tau}$ randomly.
  \Statex \hspace{-20pt} \textbf{Training:}
\For{$m = 1$ to $M$}
    \State \textbf{Mini-batch Sampling:} Select a random mini-batch $\boldsymbol{Z}_{\mathrm{mini-batch}}$ containing $\Nb$ training samples $\boldsymbol{Z}=(\boldsymbol{X},\boldsymbol{Y})$ from the training-dataset.% using a uniform distribution.

    \State \textbf{Forward Propagation:} 
    \State \hspace{10pt} {\it DRNN}:
    For each data sample $\boldsymbol{Z}\in\boldsymbol{Z}_{\mathrm{mini-batch}}$, propagate the training data through the neural network to obtain the output $\hat{\boldsymbol{Y}}_{\text{DRNN}}(\boldsymbol{X}, \boldsymbol{\tau})$  in \eqref{eq:loss_drnn}.
    \State \hspace{10pt} {\it PIRNN}:
     For each data sample $\boldsymbol{Z}\in\boldsymbol{Z}_{\mathrm{mini-batch}}$, calculate $\mathcal{R}e \int_{-\frac{\pi}{2}}^{\frac{\pi}{2}} \boldsymbol{\mathcal{G}}(\theta,\boldsymbol{\tau}) \mathcal{F}(\theta,\boldsymbol{\tau}) d\theta$  in \eqref{eq:loss_pirnn}  corresponding to $\boldsymbol{Z}$, using Monte-Carlo approximation through \eqref{eq:mont-carlo}. 

    \State \textbf{Loss Computation:} Minimize the loss function \eqref{eq:loss_drnn} (for the DRNN) or \eqref{eq:loss_pirnn} (for the PIRNN) using an optimization algorithm like Adam.% or gradient descent.
 \State  \textbf{Backward Propagation:} Update the learnable parameter $\boldsymbol{\tau}$ based on the calculated gradients.
\EndFor
%\Statex \hspace{-20pt} \textbf{Output:} Return the trained neural network learnable parameter $\boldsymbol{\tau}$ and the corresponding approximate solution $\hat{\Pv}(\boldsymbol{\tau})$ to equation \eqref{eq:main_int_eq_section1}
\end{algorithmic}
\end{algorithm}

\subsection{Training-Dataset Generation}
\label{sec:training-dataset}
