\title{CRAWLDoc: A Dataset for Robust Ranking of Bibliographic Documents}


\author[1]{Fabian Karl}[%
orcid=0009-0008-0079-5604,
email=fabian.karl@uni-ulm.de,
]
\cormark[1]
\address[1]{Universität Ulm, Germany}

