\section{Elementary assets}
This section contains a few important aspects for our future investigation.
\subsection{Function spaces, norms and basic definitions}
In this work, we employ the usual notation from Lebesgue and Sobolev space theory \cite{adams1975}. The Sobolev space of order $(m,p)$, abbreviated by $\mbox{W}^m_p(\mathcal{D})$, is defined by  
\begin{equation*}
\mbox{W}^m_p(\mathcal{D})~:=\big\{\varphi \in \mbox{L}^p(\mathcal{D}):\quad D^l \varphi \in \mbox{L}^p(\mathcal{D}),\, |l|\leq m\big\}.
\end{equation*}
for $1\leq p \leq \infty$, equipped with inner product and the norm
\begin{equation*}
(\varphi, \psi)_{m,p,\mathcal{D}}~=~  \sum_{l \leq m}\int_\mathcal{D}  D^l \varphi \cdot D^l \psi\ , dx,   \quad 
\text{and} \quad  
\|\varphi\|_{\mbox{W}^m_p(\mathcal{D})}~=~ \Big(\sum_{|l| \leq m}\int_\mathcal{D}  |D^l \varphi|^p\, dx\Big)^{1/p},   
\end{equation*}
respectively. For $p=\infty$, the norm is given by
\begin{equation*}
\|\varphi\|_{\mbox{W}^m_\infty(\mathcal{D})}~=~ \esssup_{|l| \leq m}\|D^l \varphi\|_{L^\infty(\mathcal{D})}.   
\end{equation*}
Moreover, we write $\mbox{W}^m_2(\mathcal{D}):=\mbox{H}^m(\mathcal{D})$, for $p=2$, and the norm is denoted by $\|\cdot\|_{\mbox{H}^m(\mathcal{D})}$. Further, for $p=2$ and $m=1$, we now set $\mathbb{V}=\mbox{H}^1(\mathcal{D})$. We now introduce the function spaces for fixed $t=t_j$, which are crucial in our further study. Define
\begin{subequations}
\begin{eqnarray}
&& \mathbb{V}_d:=\big\{\varphi \in \mathbb{V}\,|~~\varphi=0~~ \text{on}~~ \Omega_D \big\},   \\
&& \mathbb{V}_c:=\big\{\varphi \in \mathbb{V}\,|~~ \varphi=0 ~~ \text{on}~~ CR(t_{j-1}) \big\},\\
\text{and} \nonumber\\
&& \mathbb{V}_f:=\big\{\varphi \in \mathbb{V}\,|~~ \varphi=f(t_j)~~ \text{on}~~ \Omega_D \big\},
\end{eqnarray}
\end{subequations}
respectively. 

Moreover, let $\mathscr{H}^d$ and $\mathscr{L}^d$ be the $d$-dimensional Hausdorff and Lebesgue measures, respectively. 
\begin{definition}[Total variation of $w$] Given a function $w \in L^1(\mathcal{D})$, then the total variation of $w$ in $\mathcal{D}$ is defined as 
\begin{align*}
\mathbb{V}(w, \mathcal{D}):=~ \sup\Big\{\int_{\mathcal{D}}w\,\div(\varphi)\,dx~:~~ \varphi \in C^1_0(\mathcal{D}; \mathbb{R}^d),\, |\varphi|\leq 1\Big\}.
\end{align*}
\end{definition}
\begin{definition}[Bounded variation]
The space of functions with bounded variation ($\mbox{BV}$ functions) can be defined as 
\begin{align*}
\mbox{BV}(\mathcal{D}):= \big\{w\in \mbox{L}^1(\mathcal{D})~:~~ \mathbb{V}(w, \mathcal{D})<+\infty \big\}. 
\end{align*}
\end{definition}
A function with bounded variation may have discontinuities that are represented in its distributional gradient $Dw$. This may be disassembled as
\begin{align*}
Dw~=~ \nabla w \mathscr{L}^d+ (w^+(x)-w^-(x)) \otimes \nu_{w}(x) \mathscr{H}^{d-1}\,\oldfactorial J(w)+D^cw,
\end{align*}
where $\nabla w$ and $J(w)$ denote the approximate gradient of $w$ and the jump set of $w$, while the $w^\pm$  denotes the inner and outer traces of $w$ on $J(w)$ with respect to $\nu_w$ (the unit normal vector to $J(w)$). Further, $D^c(w)$ represents the Cantor part of the derivative. For a more understanding of these notations, we refer to \cite{Ambrosio2002}. 
\begin{definition}[Special bounded variation] Let $SBV(\mathcal{D})$ be the collection of all bounded variation functions $w$ such that the Cantor part of the derivative of $w$ is zero, and defined as 
\begin{align*}
\mbox{SBV}(\mathcal{D}):=\big\{w\in \mbox{BV}(\mathcal{D})~:~~ D^c(w)=0\big\}.
\end{align*}   
\end{definition}
At this point, we are in the position to define the model problem.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{A mathematical framework} 
% A successful approach in the literature is a regularization of the total energy $\mathcal{J}(u, \, \Gamma)$ to track the crack set.
% In the context of $\Gamma$-convergence, the regularized functional is adopted to  similar approach [12].  Using a regularization of $\mathcal{J}$ instead is an effective strategy as it can more easily express the crack set using numerical techniques.

For $\kappa >0$ and $\epsilon >0$, we define the regularized elastic energy  $E \colon \mbox{H}^1(\mathcal{D}; \mathbb{R})\times \mbox{H}^1(\mathcal{D}; [0, 1]) \to \mathbb{R}^+_\infty$, where $\mathbb{R}^{+}_{\infty}=\mathbb{R}\cup \{+\infty\}$, and the regularized crack-surface energy $\mathcal{H} \colon \mbox{H}^1(\mathcal{D}; [0, 1]) \to \mathbb{R}$, respectively, as
\begin{subequations}\label{minmization}
\begin{align}
&E(u, \, v):= \frac{1}{2} \int_{\mathcal{D}} \dfrac{|T|^2}{\left(  1 + \beta^{\alpha}\,|T|^{2\alpha} \right)^{1/\alpha}}\; dx, \\ \text{and}~~~& \nonumber\\
 &\mathcal{H}(v):=\dfrac{1}{c_w}\int_{\mathcal{D}} \left[ \frac{(1-v)}{\epsilon} + \epsilon \; |\nabla v|^2  \right]  \; dx,
\end{align}
\end{subequations}
respectively, where $T:= T(u,v)= \sqrt{ (( 1- \kappa) v^2 + \kappa  )} \;  \nabla u$.
Then, the total energy is given by the functional  $\mathcal{J}_{\epsilon}: \mbox{H}^1(\mathcal{D}; \mathbb{R})\times \mbox{H}^1(\mathcal{D}; [0, 1]) \longmapsto \mathbb{R}$ such that
\begin{align}
\mathcal{J}_{\epsilon}(u, \, v) &:=   E(u, \, v) + \lambda_c \;  \mathcal{H}(v) \notag \\
&= \frac{1}{2} \int_{\mathcal{D}} \dfrac{|T|^2}{\left(  1 + \beta^{\alpha}\, | T|^{2\alpha} \right)^{1/\alpha}}\; dx +\dfrac{\lambda_c}{c_w}\int_{\mathcal{D}} \left[ \frac{(1-v)}{\epsilon} + \epsilon \; |\nabla v|^2  \right]  \; dx. \label{reg:energy}
\end{align}
Here $v \in \mbox{H}^{1} \left(\mathcal{D}; [0, \; 1] \right) $ represents a scalar \textit{phase-field function}, while the regularization parameter for the bulk energy term is considered to be 
$\kappa \ll 1$. Moreover, the normalization constant $c_w$  is chosen to be  $8/3$ for the \textit{damage field energy}.
Note that the phase-field variable $v \approx 0$ indicates an approximation to the crack-set, while $v=1$ represents the non-fractured zone, if
$v > 0$. However, the phase-field variable $v \in (0,1)$ depicted the critical length of the diffusive zone. For $\kappa\approx 0$, the bulk energy disappears, then the the crack energy only takes into account while $v=0$. In contrast, if $v = 1$, the fracture energy is zero, hence only the bulk energy needs to be taken into account. Therefore,  we interpolate nonzero fracture and bulk energies in the diffusive zone.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
For the notational simplicity for boundary conditions, we define the following set 
\begin{equation} 
\mathrm{Q}(f(t)) :=\left\{ u \in \mbox{SBV}(\Omega) ~\colon~~ u|_{\Omega_D} = f(t) \right\},
\end{equation}
while the varying load $f\in \mbox{L}^\infty([0,T];\mbox{W}^1_{\infty}(\mathcal{D}))\cap \mbox{W}^1_1([0,T];\mbox{H}^1(\mathcal{D}))$ is applied on a open subset $\Omega_D\subset \mathcal{D}$. Consider the set of time points $\mathcal{S}_{t}=\{t_0,\, t_1,\, t_2,\,\ldots,\, t_{N_T}\}$ such that $0=t_0< t_1< t_2<t_3<\ldots< t_{N_T}=T$ with $k=\max\{k_j\,|\; k_j=t_j-t_{j-1},\; j=1,\,2,\ldots,\, N_T\}$ be the time points in a time domain $[0, T]$. So finally the quasi-static minimization problem reads as: 
 At time $t=t_0$, given $v(t_0, \, x) =1, \; \forall x \in \Omega$, find 
\begin{equation}
u_{\epsilon}(t_j, \, x) = \argmin \left\{E_{\epsilon}(\hat{u}, v(x)=1) \colon \hat{u} \in \mathbb{V}, \; \hat{ u}(x)=f(t_0) \;  \forall x \in \Omega_D \right\}.
\end{equation}
At the subsequent times $t=t_j$, $k=1, \ldots, m$, find $\left( u_{\epsilon}(t_j, \, x), \, v_{\epsilon}(t_j, \, x) \right)$ satisfying 
\begin{align}
\left( u_{\epsilon}(t_j), \, v_\epsilon(t_j, \, x) \right) = \argmin \big\{ &E_{\epsilon}(\hat{u},  \, \hat{v}) \colon \hat{u} \in \mathbb{V}, \; \hat{ u}(x)=f(t_j) \;  \forall x \in \Omega_D; \notag \\
&\hat{v} \in  \mathbb{V}, \, \hat{v} \leq v(t_{j-1}) \; \forall x \in \Omega \big\}. \label{eq_min_con}
\end{align}
The last term in the above equation \eqref{eq_min_con} imposes the crack irreversibility  \cite{Giacomini2005} and the condition is where we only allow the crack to propagate but not bonding or without self healing. At a fixed time $t=t_j$, the pair $(u_{\epsilon}(t_j), v_{\epsilon}(t_j))$ is an approximation for the Airy stress function $u(t_j)$ and the crack set $\Gamma(t_j)$ with
$u_{\epsilon}(t_j) \to u(t_j) \; \mbox{in} \; \mbox{L}^{1}(\Omega), \; \mbox{as} \; v \to 0.$

Since, the maximum principle concept is applicable to the phase-field variable. It is observed that the non-increasing character of the phase-field variable is a direct result of the truncation argument, making the following assertion easy to prove.
\begin{proposition}
The phase-field variable satisfy the maximum principle as 
\begin{equation}
0 \leq  v_{\epsilon}( x, \, t_j) \leq v_{\epsilon}(x, \, t_{j-1}) \quad \forall \; x \in \Omega, \quad \mbox{and} \quad \forall \; j \geq 1.
\end{equation}  
\end{proposition}
The quasi-static formulation can formulated as a successive global minimization  \cite{FrancfortBourdi2000} for the equilibrium solution as:
\begin{subequations}\label{eq:minmization}
\begin{align}
u(t_j) := \underset{v \in \mathcal{D}(f(t_j))}{\argmin} E_B(v) + E_S(J(v) + \Gamma(t_{k-1})), \quad \text{and} \quad 
\Gamma(t_j) := J(u(t_j)) \cup \Gamma(t_{k-1}).
\end{align}
\end{subequations}
Note that $(u(t_j), \Gamma(t_j))$ must satisfy the following crack irreversibility and global stability conditions.

\noindent 
\textbf{(i) \tt Crack irreversibility criteria:} The quasi-static evolution $t \mapsto \Gamma(t)$ requires that: 
\begin{equation}
\Gamma(t) \; \mbox{is increasing in time, i.e.} \; \Gamma(t_{j-1}) \subseteq \Gamma(t_j), \quad  \forall \; 0 \leq t_{j-1} \leq t_j \leq T
\end{equation}
The above condition can also be written as 
\begin{equation}\label{crack-irr-1}
 \partial_t v(x, t) \leq 0
 \end{equation}
  enforces the \textit{crack-irreversibility}. But, one can also impose the equality constraint as: If at time $t = t_{j-1}, \; j \in \left\{ 1, 2, \ldots, N_T \right\}$, define a set, for any $0 < c_{j} < 1$, 
\begin{equation}
v(t_{j-1}):= \left\{ x \in \overline{\mathcal{D}} \; \colon \; v_{\epsilon} (x,\, t_{j-1}) < c_{j} \right \},
\end{equation}
We note that the set $v(t_{j})$ is nonempty. Then the crack-irreversibility condition \eqref{crack-irr-1} be written as 
\begin{equation}
v_{\epsilon}(x, \, t_j) =0 \quad \forall \; x \in v(t_{j-1}) \; \mbox{and} \; \forall \; j \; \mbox{such that} \; k \leq j \leq N.
\end{equation} 
This simplifies minimization, as setting $v_{\epsilon}(x, \, t_j) $ to $0$ implies that the process be linear rather than nonlinear.  This clearly indicates that the point $x$ is on the crack path and continues to be on the crack-path until the end of the simulation. But the difficulty is that we may see \textit{crack widening} effect. This is easy to see, as setting $v_{\epsilon}(x, \, t_{j-1})$ to zero causes $v_{\epsilon}$ to remain below the value $c_{j}$ at points in a neighborhood of $x$, which will then be set to zero at $t=t_j$. One way to avoid the \textit{crack widening} effect is to choose $c_{j}$ less than the smallest mesh size. \smallskip

\noindent
\textbf{(ii) \tt Global stability criteria:} The sequence $(u(t_j), \Gamma(t_j)),\, j=1,\, \ldots,\, N_T$ for all $v\in \mathcal{Q}(f(t_{j-1}))$ and $\Gamma(t_j) \subset \Gamma$, satisfies 
\begin{align*}
E(u(t_j), \Gamma(t_j)) \leq E(v, \Gamma).
\end{align*}
For the problem formulated within non-linear elasticity, the existence of a solution to the Francfort-Marigo model has been shown in \cite{DeGiorgi1989,FrancfortLarsen2003}. But to the authors' best knowledge there is no such proof of existence of solutions available for the discrete-time quasi-static evolution model proposed within the setting of nonlinear limiting strain models introduced in \cite{yoon2021quasi}. 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Now we rewrite the functional $\mathcal{J}$ from $ \mathbb{V}_g\times \mathbb{V}_c$ to $\mathbb{R}^{+}_{\infty}$ by considering the constants $\kappa$, $\epsilon$, and $\lambda_c$ as fixed parameters:
\begin{align}
\mathcal{J}(u, \, v)~=~ \int_{\mathcal{D}}\Big[\dfrac{|T|^2}{2\left(  1 + \beta^{\alpha}\, |T|^{2\alpha} \right)^{1/\alpha}} + \rho\, |\nabla v|^2 + \delta \,(1-v)  \Big] \; dx, \label{minmizationfunc1.7}
\end{align}
with $\rho=\dfrac{\lambda_c\, \epsilon}{c_w }$ and  $\delta =\dfrac{\lambda_c}{c_w \,\epsilon}$, respectively. 

The following proposition demonstrates that the functional $\mathcal{J}$ is Fréchet differentiable at any $(u, v)\in \mathbb{V}\times \mathbb{V}_{T}$, where $\mathbb{V}_{T}=\mbox{H}^1(\mathcal{D})\cap L^\infty(\mathcal{D})$. 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}[Fr\'{e}chet-differentiablity of $\mathcal{J}$]
For any $(u, v)\in \mathbb{V}\times \mathbb{V}_{T}$, then the functional  $\mathcal{J}$ from $\mathbb{V}_f\times \mathbb{V}_c $ to $\mathbb{R}^{+}_{\infty}$  is Fr\'{e}chet-differentiable in $\mathbb{V}\times \mathbb{V}_{T}$. 
\end{proposition}
\begin{proof} 
To examine the differentiability of $\mathcal{J}$ at $(u, v)\in \mathbb{V}\times \mathbb{V}_{T}$, we first compute the directional derivative in the direction $(\psi, \varphi)\in \mathbb{V}\times \mathbb{V}_{T}$, which yields
\begin{align}
\mathcal{J}^\prime(u, v; \psi, \varphi)=~ \mathcal{A}(v; u, \psi)+ \mathcal{B}(u; v, \varphi), \label{3.18jprim}
\end{align}
where
\begin{subequations}
\begin{align}
&\mathcal{A}(v; u, \psi)=~ \int_{\mathcal{D}}\Big[\dfrac{\big((1-\kappa)v^2+\kappa \big)}{\left(1 + \beta^{\alpha}\, |T|^{2\alpha}\right)^{\frac{1}{\alpha}+1}}\; \nabla u \cdot \nabla \psi \Big] \, dx, \label{ddofJA}\\
\text{and}~~~~& \nonumber\\
&\mathcal{B}(u; v, \varphi)=~ \int_{\mathcal{D}}\Big[2\,\rho\, \nabla v \cdot \nabla \varphi - \delta \, \varphi + \dfrac{(1-\kappa)\,|\nabla u|^2}{\left( 1 + \beta^{\alpha}\, |T|^{2\alpha}\right)^{\frac{1}{\alpha}+1}}\;v \, \varphi \Big] \, dx,  \label{ddofJb}
\end{align}   
\end{subequations}
respectively. To establish Fréchet differentiability, we need to verify that the remainder term $\frac{|\mathcal{R}(u, v; \psi, \varphi)|}{~\|\psi\|_{\mathbb{V}}+\|\varphi\|_{\mathbb{V}}+\|\varphi\|_{L^\infty(\mathcal{D})}}$ tends to zero at a rate consistent with $\|\psi\|_{\mathbb{V}}+\|\varphi\|_{\mathbb{V}}+\|\varphi\|_{L^\infty(\mathcal{D})}$ approaching zero. To this end, we will compute the remainder term $\mathcal{R}$ using the following definition
\begin{align}
&\big|\mathcal{R}(u, v; \psi, \varphi)\big|=~ \big|\mathcal{J}(u+\psi, v+\varphi)-\mathcal{J}(u, v)- \mathcal{J}^\prime(u, v; \psi, \varphi)\big|\nonumber\\
&~~~~~~\leq~\int_{\mathcal{D}}\rho\, |\nabla \varphi|^2\, dx+\Big|\int_{\mathcal{D}}\Big[\dfrac{((1-\kappa)(v+\varphi)^2+\kappa)|\nabla (u+\psi)|^2}{2\,[1 + \beta^{\alpha} ((1-\kappa)(v+\varphi)^2+\kappa)^\alpha|\nabla (u+\psi)|^{2\alpha} ]^{1/\alpha}}\nonumber\\
&~~~~~~~~~- \dfrac{((1-\kappa)v^2+\kappa)|\nabla u|^2}{2\,[1 + \beta^{\alpha} ((1-\kappa)v^2+\kappa)^\alpha\,|\nabla u|^{2\alpha} ]^{1/\alpha}} 
-\dfrac{\big((1-\kappa)v^2+\kappa \big)\; \nabla u \cdot \nabla \psi\,}{[ 1 + \beta^{\alpha}\,\big((1-\kappa)v^2+\kappa )\big)^\alpha\,| \nabla u|^{2\alpha}]^{\frac{1}{\alpha}+1}} \nonumber\\
&~~~~~~~~~ -\dfrac{(1-\kappa)\,|\nabla u|^2\;v \, \varphi}{[ 1 + \beta^{\alpha}\,\big((1-\kappa)v^2+\kappa )\big)^\alpha\, | \nabla u|^{2\alpha}]^{\frac{1}{\alpha}+1}} \Big]\,dx\Big| \nonumber\\
&~~~~~~:=~I_1+I_2. \label{3.20resbdd}
\end{align}
We proceed to evaluate each term individually. First, we estimate the term $I_1$ as
\begin{align*}
I_1\leq~ \rho\,\|\varphi\|^2_{\mathbb{V}}.
\end{align*}
Moving on to the next term using the fact $[ 1 + \beta^{\alpha}\,\big((1-\kappa)v^2+\kappa )\big)^\alpha | \nabla u|^{2\alpha}]^{\frac{1}{\alpha}+1}\geq [ 1 + \beta^{\alpha}\,\big((1-\kappa)v^2+\kappa )\big)^\alpha | \nabla u|^{2\alpha}]^{\frac{1}{\alpha}}$ and $1/[1 + \beta^{\alpha} ((1-\kappa)(v+\varphi)^2+\kappa)^\alpha\, |\nabla (u+\psi)|^{2\alpha} ]^{1/\alpha}\leq 1/[ 1 + \beta^{\alpha}\,\big((1-\kappa)v^2+\kappa )\big)^\alpha | \nabla u|^{2\alpha}]^{\frac{1}{\alpha}+1}$, we can estimate $I_2$ as
\begin{align*}
I_2&\leq~ \Big[ |1-\kappa|\,\|\varphi\|^2_{L^2(\mathcal{D})}\,\|\nabla u\|^2_{L^2(\mathcal{D})}+\|(1-\kappa)\,v^2+\kappa\|_{L^\infty(\mathcal{D})}\,\|\nabla \psi\|^2_{L^2(\mathcal{D})}+|1-\kappa|\,\|\varphi\|^2_{L^\infty(\mathcal{D})}\\
&~~\times \|\nabla \psi\|^2_{L^2(\mathcal{D})}+2\,|1-\kappa|\,\|v\|_{L^\infty(\mathcal{D})}\,\|\varphi\|_{L^\infty(\mathcal{D})}\,\|\nabla \psi\|^2_{L^2(\mathcal{D})}+4\,|1-\kappa|\,\|v\|_{L^\infty(\mathcal{D})}\,\,\|\nabla u\|_{L^2(\mathcal{D})}\\
&~~\times\|\varphi\|_{L^\infty(\mathcal{D})}\,\|\nabla \psi\|_{L^2(\mathcal{D})}+2\,|1-\kappa|\, \|\nabla u\|_{L^2(\mathcal{D})} \|\varphi\|^2_{L^\infty(\mathcal{D})}\,\|\nabla \psi\|_{L^2(\mathcal{D})}
\Big]{\Big/} [1 + \beta^{\alpha} \\ 
&~~\times \big((1-\kappa)v^2+\kappa )\big)^\alpha \| \nabla u\|^{2\alpha}]^{\frac{1}{\alpha}+1}.
\end{align*}
By substituting the estimates for $I_1$ and $I_2$ into \eqref{3.20resbdd}, we obtain $\frac{|\mathcal{R}(u, v; \psi, \varphi)|}{~\|\psi\|_{\mathbb{V}}+\|\varphi\|_{\mathbb{V}}+\|\varphi\|_{L^\infty(\mathcal{D})}}\longrightarrow 0$ as $\|\psi\|_{\mathbb{V}}+\|\varphi\|_{\mathbb{V}}+\|\varphi\|_{L^\infty(\mathcal{D})}\longrightarrow 0$. This concludes the proof of the lemma.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
It is observed that, the functional $\mathcal{J}$ lacks G$\hat{a}$teaux-differentiability over the entire $\mathbb{V}\times \mathbb{V}$. To circumvent this, we restrict our analysis to critical points within the subspace $\mathbb{V}_c^\infty=\mathbb{V}_c\cap \mbox{L}^\infty(\mathcal{D})$ of $\mathbb{V}_c$.
 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{definition}[Critical point of $\mathcal{J}$] \label{crtitptsdef}
A pair $(u, v) \in \mathbb{V}_f \times \mathbb{V}_c^\infty$ is said to be a critical point of  $\mathcal{J}$ if  $(u, v)$ satisfy the condition $\mathcal{J}^{\prime}(u,v; \psi, \phi)=0$, $\forall \, (\psi, \phi) \in  \mathbb{V}_d \times \mathbb{V}_c^{\infty}$.
\end{definition}
It is well-known that any local minimizer pair $(u, v)$ of the functional $\mathcal{J}$ must satisfy the required condition $0\leq v(x)\leq 1$, which may be simply proven by using the truncation argument. So we omit the details of the proof, however, the statement is precisely laid out in the following proposition.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition} \label{prop3.2:v}
Let $(u, v)\in \mathbb{V}_f \times \mathbb{V}_c^\infty$ is a critical point of  $\mathcal{J}$, then $v \in \mathbb{V}_c^\infty$ satisfy the condition $0 \leq v(x) \leq 1$ for {\it a.e.} $x\in \mathcal{D}$.
\end{proposition}
