\section{Convergence Analysis}
In this section, we evaluate the impact of split point selection, aggregation frequency, data sensing volume and locations of UAVs on the proposed SFLSCC through conducting a detailed convergence analysis.

\subsection{Basic Assumptions}
Prior to embarking on the convergence analysis, several widely accepted assumptions are presented as follows:

%*********假设1
\textbf{Assumption 1.} \textit{Each local loss function $\mathcal{L}_m\left(\boldsymbol{w}\right)$ is uniformly $\beta$-smooth with respect to any $\boldsymbol{w}$ and $\boldsymbol{w}^{\prime}$, thus we have}
\begin{equation}
    \left\|\nabla \mathcal{L}
    _m\left(\boldsymbol{w}\right)-\nabla \mathcal{L}_m\left(\boldsymbol{w}^{\prime}\right)\right\|\leq \beta\left\|\boldsymbol{w}-\boldsymbol{w}^{\prime}\right\|, \forall m,
\end{equation}
\textit{where $\beta$ represents the Lipschitz constant corresponding to $\mathcal{L}\left(\cdot\right)$}.

%*********假设2
\textbf{Assumption 2.} \textit{The variance and second moments of stochastic gradients for each layer are bounded by}
\begin{equation}
\mathbb{E}\left[\Vert \mathbf{g}_m - \nabla \mathcal{L}_m(\boldsymbol{w}) \Vert^2 \right] \leq \frac{\sum\limits_{l=1}^L \sigma_l^2}{b}, \forall m, \forall \boldsymbol{w},
\end{equation}
\textit{and}
\begin{equation}
\mathbb{E}\left[\Vert \mathbf{g}_m \Vert^2 \right] \leq\sum\limits_{l=1}^{L_c}G_l^2, \forall m, \forall \boldsymbol{w},
\end{equation}
\textit{where $\sigma_l^2$ and $G_l^2$ denote the variance and second moments' upper bound for l-th layer of model $\boldsymbol{w}$, respectively.}

%*********假设3
\textbf{Assumption 3.} \textit{The heterogeneity which exists in the local datasets can by assessed by}
\begin{equation}
    \mathbb{E}\left[\left\|\nabla\mathcal{L}_m\left(\boldsymbol{w}\right)-\nabla\mathcal{L}\left(\boldsymbol{w}\right)\right\|^2\right]\leq \Lambda_m^2
\end{equation}
\textit{where $\Lambda_l^2$ represents a positive constant.}

%*********假设4
\textbf{Assumption 4.} \textit{The stochastic gradients exhibit unbiasedness, which can be denoted as}
\begin{equation}
    \mathbb{E}\left[\mathbf{g}_m\right]=\nabla\mathcal{L}_m\left(\boldsymbol{w}\right).
\end{equation}

\subsection{Convergence Analysis}
Before establishing the convergence rate, some key Lemmas are presented as follows.
%*********引理1
\begin{Lemma}
According to \textbf{Assumption 1}, we can derive
\begin{equation}
    \mathbb{E}\left[\left\|\boldsymbol{w}_c^{t}-\boldsymbol{w}_{c,m}^{t}\right\|^2\right] \leq 4\eta^2I^2\sum\limits_{l=1}^{L_c}G_l^2.
\end{equation}
\begin{proof}
See APPENDIX A.
\end{proof}
\end{Lemma}

%*********引理2
\begin{Lemma}
Under \textbf{Assumption 1} and \textbf{Lemma 1}, we have
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\langle \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right),\boldsymbol{w}^t-\boldsymbol{w}^{t-1} \rangle\right]\\
&\leq
\eta \sum\limits_{m=1}^M \varphi_m^2 \left(\sum\limits_{m=1}^M \Lambda_m^2 +4M\beta^2\eta^2I^2\sum\limits_{l=1}^{L_c}G_l^2\right)\\
&- \frac{\eta}{2} \mathbb{E}\left[\left\|\sum\limits_{m=1}^M \varphi_m \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right)\right\|^2\right].
\end{aligned}
\end{equation}

\begin{proof}
See APPENDIX B.
\end{proof}
\end{Lemma}

%*********引理3
\begin{Lemma}
According to \textbf{Assumption 3} and \textbf{Assumption 4}, it holds that
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\|\boldsymbol{w}^t-\boldsymbol{w}^{t-1}\|^2\right] < \frac{2\eta^2}{M}\sum\limits_{m=1}^M \varphi_m\frac{\sum\limits_{l=1}^{L_c} \sigma_l^2}{b}+\frac{4\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2\\&+4\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-\bar{q}_s)^2+\bar{q}_s^2\right)\Lambda_m^2\\&+32\beta^2\eta^4I^2\sum\limits_{l=1}^{L_c}G_l^2+8\eta^2\mathbb{E}\left[\|\nabla\mathcal{L}(\boldsymbol{w}^{t-1})\|^2\right].
\end{aligned}
\end{equation}
\begin{proof}
 See APPENDIX C.   
\end{proof}
\end{Lemma}

\begin{theorem}
We consider the learning rate $\eta$ of proposed SFLSCC satisfies that
\begin{equation}
0<\eta<\frac{\sum\limits_{m=1}^M\varphi_m}{8\beta}.
\label{etacon}
\end{equation}

Under \textbf{Assumption} 1-4 and \textbf{Lemma} 1-3, we can obtain
\begin{equation}
\begin{aligned}
&\frac{1}{N}\sum\limits_{t=1}^N\mathbb{E}\left[\|\nabla\mathcal{L}(\boldsymbol{w}^{t-1})\|^2\right]\leq\frac{2}{\eta\left(\sum\limits_{m=1}^M\varphi_m\right)^2-8\beta\eta^2}\cdot\\&\quad\Bigg(\frac{\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{0}\right)\right]-\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{*}\right)\right]}{N}+\frac{\sum\limits_{l=1}^{L} \beta\eta^2\sigma_l^2}{Mb}\\& \quad+\frac{2\beta\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2+16\beta^3\eta^4I^2\sum\limits_{l=1}^{L_c}G_l^2\\&\quad+2\beta\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-\bar{q}_s)^2+\bar{q}_s^2\right)\Lambda_m^2\\&\quad+  \sum\limits_{m=1}^M \eta\Lambda_m^2 +4M\beta^2\eta^3I^2\sum\limits_{l=1}^{L_c}G_l^2\Bigg).
\end{aligned}
\label{theorem}
\end{equation}

\begin{proof}
    See APPENDIX D.
\end{proof}


Eq. \eqref{theorem} indicates that when the UAVs have varying target sensing probabilities, the adverse effects resulting from data heterogeneity $2\beta\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-q_s)^2+q_s^2\right)\Lambda_m^2$ will be amplified. For alleviating this adverse effects, we assume the UAVs have the uniform target sensing probabilities, thus $q_{s,m}=q_s$. Moreover, we can derive the following corollary.
\end{theorem}

