Under the constraint of learning rate $\eta$ as shown in Eq. \eqref{etacon}, when the UAVs have uniform target sensing probabilities, we can obtain the expression of $\varphi_m$ and $\kappa_m$, which can be given by
\begin{equation}
\begin{aligned}
\varphi_m = \frac{q_s}{\left[1-(1-q_s)^M\right]M}.
\end{aligned}
\end{equation}
\begin{proof}
    See APPENDIX E.
\end{proof}
\begin{equation}
    \kappa_m = \frac{2}{Mq_s^M}.
\end{equation}
\begin{proof}
    See APPENDIX B of \cite{ISAC-2306}.
\end{proof} 
\end{corollary}
%****************推论2
\begin{corollary}
When $\frac{1}{N}\sum\limits_{t=1}^{N} \mathbb{E}\left[\|\nabla \mathcal{L}\left(\mathbf{w}^{t-1}\right)\|^{2}\right] \leq \varepsilon$, it represents the SFLSCC has converged to the target convergence accuracy $\varepsilon$, and the training rounds demanded can be represented as
\begin{equation}
\begin{aligned}
N \geq \frac{\vartheta}{\varepsilon^{\prime}-\Gamma_1\sum\limits_{l=1}^{L_c}G_l^2I^2-\frac{\Gamma_2}{b}-\frac{\Gamma_3}{q_s^{M-2}}-\Gamma_4}
\end{aligned}
\end{equation}
with
\begin{subequations}
\begin{align}
&\vartheta=\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{0}\right)\right]-\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{*}\right)\right],\\
&\varepsilon^{\prime}=\eta\varepsilon\left(\frac{q_s}{4\left[1-(1-q_s)^M\right]M}\right)^2-4\varepsilon\beta\eta^2,\\
&\Gamma_1=16\beta^3\eta^4+4M\beta^2\eta^3,\\
&\Gamma_2=\frac{\sum\limits_{l=1}^{L} \beta\eta^2\sigma_l^2}{M},\\
&\Gamma_3=8U\beta^2\gamma^2,\\
&\Gamma_4=\sum\limits_{m=1}^M \eta\Lambda_m^2+\frac{2\beta\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2.
\end{align}
\end{subequations}
\end{corollary}
