\section{Problem Formulation and Solution
Algorithm}
As previously highlighted, balancing training performance and energy consumption is critical due to the limited battery capacity of UAVs. To address this, we formulate an energy consumption minimization problem with convergence guarantees by jointly optimizing the aggregation frequency \( I \), split point selection \( L_c \), UAV 3-D coordinates \( \{\boldsymbol{u}_m\} \), and data sensing volume \( b \).
\begin{subequations}
\begin{align}
\mathcal{P} 1: & \min_{I,L_c,\{\boldsymbol{u}_m\},b} \sum_{m=1}^MTE_m(I,L_c,\boldsymbol{u}_m,b) \\
 \text{s.t.} & \quad \frac{1}{N} \sum_{n=1}^{N} \mathbb{E}[\|\nabla \mathcal{L}(\boldsymbol{w}_m)\|^2] \leq \varepsilon, \label{eq35b}\\
& \quad 0< L_c \leq L, \label{eq35c}\\
& \quad q_{s,m}\left(\boldsymbol{u}_m\right)=q_{s,m^{\prime}}\left(\boldsymbol{u}_{m^{\prime}}\right), \forall m,m^{\prime} \in \mathcal{M},\label{qscon}\\
& \quad \theta_{s}\left(\boldsymbol{u}_m\right)\geq \theta_0, \forall m \in \mathcal{M},\label{thetascon}\\
& \quad I \in \mathbb{N}^{+},\label{eq35e}\\
& \quad b \in \mathbb{N}^{+}\label{bfan},
\end{align}
\end{subequations}
where \( T = \frac{N}{I} \) represents the total number of communication cycles required to achieve model convergence. Eq. \eqref{eq35b} ensures that the number of training rounds \( N \) satisfies the global convergence accuracy, while Eq. \eqref{eq35c} specifies the valid range of the split point \( L_c \). The constraint Eq. \eqref{qscon} originates from \textbf{Corollary 1}, which requires that UAVs maintain a consistent target sensing probability. To ensure reliable target sensing quality, we impose the constraint in Eq. \eqref{thetascon}. Eqs. \eqref{eq35e} and \eqref{bfan} ensure that the aggregation frequency \( I \) and data sensing volume \( b \) are positive integers.


Based on \textbf{Corollary 2}, we set $N$ to its minimum value and explicitly express $T$. Thus, problem $\mathcal{P}1$ can be rewritten as
\begin{subequations}
\begin{align}
\mathcal{P} 2: & \min_{I,L_c,\{\boldsymbol{u}_m\},b} \Xi\left(I,L_c,\{\boldsymbol{u}_m\},b\right)\\
 \text{s.t.} & \quad \rm Eq.~\eqref{eq35c}- \rm Eq.~\eqref{bfan}\label{eq37b},
\end{align}
\end{subequations}
where
\begin{equation}
    \Xi\left(I,L_c,\{\boldsymbol{u}_m\},b\right)=\frac{\sum\limits_{m=1}^M\vartheta E_m(I,L_c,\boldsymbol{u}_m,b)}{I\left(\varepsilon^{\prime}-\Gamma_1\sum\limits_{l=1}^{L_c}G_l^2I^2-\frac{\Gamma_2}{b}-\frac{\Gamma_3}{q_s^{M-2}}-\Gamma_4\right)}.
\label{Xi}
\end{equation}

Evidently, problem $\mathcal{P} 2$ exhibits non-convex characteristics due to the presence of both coupled integer and continuous variables. To address this, we decompose the problem into four sub-problems. When the split point $L_c$, 3-D coordinates of UAVs $\{\boldsymbol{u}_m\}$, and data sensing volume $b$ are fixed, problem $\mathcal{P} 2$ reduces to
\begin{subequations}
\begin{align}
\mathcal{P} 3: & \min_{I} \Xi\left(I\right) \\
 \text{s.t.} &   \quad \rm Eq. ~ \eqref{eq35e},
\end{align}
\end{subequations}

Then we can easily calculate the optimal client-side aggregation frequency $I^*$ by Newton Raphson's method, which is
\begin{equation}\label{I*}
I^*=\left\{\begin{array}{cc}1&I^{\prime}\leq1\\\arg\min_{I\in\{\lfloor I^{\prime}\rfloor,\lceil I^{\prime}\rceil\}}\Xi\left(I\right)&I^{\prime}>1\end{array}\right.
\end{equation}
where $I^{\prime}$ is an an extreme point of the derivative of $\Xi\left(I\right)$.

Similarly, when aggregation frequency $I$, split point $L_c$ and 3-D coordinates of UAVs $\{\boldsymbol{u}_m\}$ are fixed, the problem $\mathcal{P} 2 $ becomes
\begin{subequations}
\begin{align}
\mathcal{P} 4: & \min_{b} \Xi\left(b\right) \\
 \text{s.t.} &  \quad \rm Eq.~ \eqref{bfan}.
\end{align}
\end{subequations}

Next, the optimal data sensing volume $b$ can be given by
\begin{equation}
b^*=\left\{\begin{array}{cc}1&b^{\prime}\leq1\\\arg\min_{b\in\{\lfloor b^{\prime}\rfloor,\lceil b^{\prime}\rceil\}}\Xi\left(b\right)&b^{\prime}>1\end{array},\right.
\end{equation}
where $b^{\prime}$ is an an extreme point of the derivative of $\Xi\left(b\right)$.

Moreover, when we fix the aggregation frequency $I$, UAV 3-D coordinates $\{\boldsymbol{u}_m\}$ and data sensing volume $b$, the problem $\mathcal{P} 2$ can be rewritten as
\begin{subequations}
\begin{align}
\mathcal{P} 5: & \min_{L_c} \Xi\left(I^{*},L_c,\{\boldsymbol{u}_m\},b^{*}\right)\\
 \text{s.t.} &  \quad \rm Eq.~\eqref{eq35c}.
\end{align}
\end{subequations}

Given that the split point $L_c$ is discrete and its variable space is small, the optimal split point $L_c^{*}$ can be directly obtained using the traversing method. Specifically, the split point $L_c^{*}$ that yields the minimum value of the problem $\mathcal{P} 5$ is selected as the optimal solution.
Finally, based on $I^*$, $L_c^*$ and $b^*$, the problem $\mathcal{P} 2$ can be converted into

\begin{subequations}
\begin{align}
\mathcal{P} 6: & \min_{\{\boldsymbol{u}_m\}} \Xi\left(I^{*},L_c^*,\{\boldsymbol{u}_m\},b^{*}\right)\\
 \text{s.t.} &  \quad \rm Eq.~\eqref{thetascon}.
\end{align}
\end{subequations}

According to \textbf{\textit{Proposition 1}} in \cite{ISAC-2306}, when given $q_s$, the optimal position $\boldsymbol{u}_m^{*}$ of each UAV $m$ to maximize $R_m\left(\boldsymbol{u}_m\right)$ and then minimize $\Xi\left(I^{*},L_c^*,\boldsymbol{u}_m,b^{*}\right)$ can be derived from
\begin{equation}
    x_{m}^{*}=x_{m,v}-\frac{H(x_{m,v}-x_{s})}{\tan\theta_{s}\|\boldsymbol{u}_s-\boldsymbol{u}_m\|}
\end{equation}
and
\begin{equation}
    y_{m}^{*}=y_{m,v}-\frac{H(y_{m,v}-y_{s})}{\tan\theta_{s}\|\boldsymbol{u}_s-\boldsymbol{u}_m\|}.
\end{equation}

Based on $\boldsymbol{u}_m$ with given $q_s$, the transmission rate $R_m\left(\boldsymbol{u}_m\right)$ can be converted into $\hat{R}_m\left(q_s\right)$, and the problem $\mathcal{P} 6$ can be rewritten as
\begin{subequations}
\begin{align}
\mathcal{P} 6^{\prime}: & \min_{q_s} \Xi\left(I^{*},L_c^*,q_s,b^{*}\right)\\
 \text{s.t.} &  \quad \rm Eq.~\eqref{thetascon}.
\end{align}
\end{subequations}
which can be solved by SCA algorithm and get optimal $q_s^*$.  And based on this, we
employ the iterative block-coordinate descent(BCD)-based
algorithm to solve problem $\mathcal{P} 2$.
