\section{Conclusion}
This paper presents a novel SFL framework for UAV-enabled integrated sensing, computation, and communication, named SFLSCC, addressing key challenges in UAV-assisted FEL systems. By leveraging the unique capabilities of UAVs for local data collection and computation, SFLSCC optimizes the trade-off between training accuracy and energy consumption. Our theoretical analysis provides insights into the convergence behavior of SFLSCC, establishing upper bounds for the convergence gap based on UAV deployment, split point selection, and data sensing volume. We also propose a joint optimization approach to minimize energy consumption while ensuring the desired model accuracy. The non-convex nature of the problem is tackled with a low-complexity algorithm that efficiently delivers near-optimal solutions. Extensive experiments on a target motion recognition task demonstrate the superiority of SFLSCC in terms of convergence performance and energy efficiency compared to existing methods.

\section*{APPENDIX A}
Let's fix the training round at $t \geq 1$. Identify the largest $t_0 \leq t$ and $t_0$ is a multiple of $I$ (i.e. $t_0$ mod $I=0$). It should be noted that such a $t_0$  definitely exists and the difference $t-t_0$ is at most $I$. According to the Eq.\eqref{modelcm} which are used to update the model weights, we have
\begin{equation}
    \boldsymbol{w}_{c,m}^t = \boldsymbol{w}_{c}^{t_0}-\eta\sum\limits_{\tau=t_0}^{t-1}\alpha_{m}^{\tau}\mathbf{g}_{c,m}^{\tau}
\end{equation}
and by Eq.\eqref{modelc}, we have
\begin{equation}
    \boldsymbol{w}_{c}^t = \boldsymbol{w}_{c}^{t_0}-\eta\sum\limits_{\tau=t_0}^{t-1}\frac{1}{M}\sum\limits_{m=1}^M\alpha_{m}^{\tau}\mathbf{g}_{c,m}^{\tau}.
\end{equation}

Thus, we have
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\left\|\boldsymbol{w}_c^{t}-\boldsymbol{w}_{c,m}^{t}\right\|^2\right] \\
&=\eta^2\mathbb{E}\left[\left\|\sum\limits_{\tau=t_0}^{t-1}\frac{1}{M}\sum\limits_{m=1}^{M}\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}-\sum\limits_{\tau=t_0}^{t-1}\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2\right] \\
&\overset{\left(a\right)}{\leq}
2\eta^2\mathbb{E}\left[\left\|\sum\limits_{\tau=t_0}^{t-1}\frac{1}{M}\sum\limits_{m=1}^{M}\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2+\left\|\sum\limits_{\tau=t_0}^{t-1}\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2\right]\\
&\overset{\left(b\right)}{\leq}
2\eta^2\left(t-t_0\right)\mathbb{E}\left[\sum\limits_{\tau=t_0}^{t-1}\left\|\frac{\sum\limits_{m=1}^{M}\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}}{M}\right\|^2+\sum\limits_{\tau=t_0}^{t-1}\left\|\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2\right]\\
&\overset{\left(c\right)}{\leq}
2\eta^2\left(t-t_0\right)\mathbb{E}\left[\frac{\sum\limits_{\tau=t_0}^{t-1}\sum\limits_{m=1}^{M}\left\|\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2}{M}+\sum\limits_{\tau=t_0}^{t-1}\left\|\alpha_m^{\tau}\mathbf{g}_{c,m}^{\tau}\right\|^2\right]\\
&\overset{\left(d\right)}{\leq}
4\eta^2\left(t-t_0\right)^2\sum\limits_{l=1}^{L_c}G_l^2\\
&\leq 4\eta^2I^2\sum\limits_{l=1}^{L_c}G_l^2,
\end{aligned}
\end{equation}
where inequality $\left(a\right)-\left(c\right)$ follows from $\|\sum\limits_{i=1}^nx_i\|^2\leq n\sum\limits_{i=1}^n\|x_i\|^2$, and inequality $\left(d\right)$ is due to \textbf{Assumption 2}.
