\section*{APPENDIX B}
To begin with, we derive the expectation expression of $\boldsymbol{w}^t-\boldsymbol{w}^{t-1}$.
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\frac{\sum\limits_{m=1}^M\alpha_m^{t-1}\mathbf{g}_m^{t-1}}{M}\Bigg|\sum\limits_{m=1}^M\alpha_m^{t-1}\neq 0\right]\\&=\mathbb{E}\left[\sum\limits_{l=1}^M\sum\limits_{\substack{|\mathcal{M}_1|=l\\|\mathcal{M}_2|=M-l}}^{\mathcal{M}_1\cup \mathcal{M}_2=\mathcal{M}} Pr\Bigg(\alpha_{m_1}^{t-1} = 1 \forall m_1 \in \mathcal{M}_1,\alpha_{m_2}^{t-1} = 0 \right.  \\
& \left. \quad \forall m_2 \in \mathcal{M}_2 \Bigg|\sum\limits_{m=1}^M\alpha_m^{t-1}\neq0\Bigg)\frac{1}{M}\sum\limits_{m_1 \in \mathcal{M}_1}\mathbf{g}_{m_1}^{t-1}\right]\\&= \mathbb{E}\left[\sum\limits_{l=1}^M\sum\limits_{\substack{|\mathcal{M}_1|=l\\|\mathcal{M}_2|=M-l}}^{\mathcal{M}_1\cup \mathcal{M}_2=\mathcal{M}}\frac{1}{M}\sum\limits_{m_1 \in \mathcal{M}_1}\mathbf{g}_{m_1}^{t-1} \right.  \\
& \left.\quad\cdot\frac{\prod\limits_{m_1 \in \mathcal{M}_1}q_{s,m_1}\prod\limits_{m_2 \in \mathcal{M}_2}(1-q_{s,m_2})}{1-\prod\limits_{m \in M}(1-q_{s,m})}\right]\\&
\overset{\triangle}{=}\sum\limits_{m=1}^M\varphi_m\mathbb{E}\left[\mathbf{g}_m^{t-1}\right],
\end{aligned}
\end{equation}
where $\mathcal{M}_1$ represents the set of UAVs which succeed in sensing the target, while $\mathcal{M}_2$ denotes the set of UAVs which fail to do that. Besides, $\varphi_m, \forall m \in \mathcal{M}$ is related to $q_{s,m}$ and $\sum\limits_{m=1}^M\varphi_m\leq1$, this can be observed by setting $\mathbf{g}_m^{t-1}=1$.

Next, we prove \textbf{Lemma 2} as follows
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\langle \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right),\boldsymbol{w}^t-\boldsymbol{w}^{t-1}\rangle\right]\\
&= -\eta\mathbb{E}\left[\left\langle \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right), \frac{\sum\limits_{m=1}^M \alpha_m^{t-1} \mathbf{g}_m^{t-1}}{M}\right\rangle\right]\\
&=
-\eta \mathbb{E}\left[\left\langle \nabla\mathcal{L}\left(\boldsymbol{w}^{t-1}\right), 
\sum\limits_{m=1}^M \varphi_m \nabla \mathcal{L}_m\left(\boldsymbol{w}_m^{t-1}\right)\right\rangle\right]\\
&\leq
-\eta \mathbb{E}\left[\left\langle \sum\limits_{m=1}^M \varphi_m \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right), 
\sum\limits_{m=1}^M \varphi_m \nabla \mathcal{L}_m\left(\boldsymbol{w}_m^{t-1}\right)\right\rangle\right]\\
