&+2\underbrace{\mathbb{E}\left[\frac{\left\|\sum\limits_{m=1}^M \alpha_m^{t-1} \left(\nabla\mathcal{L}(\boldsymbol{w}^{t-1}_m)\right)\right\|}{M^2}^2\right]}_{Y_3}, 
