\begin{aligned}
Y_2 &= \mathbb{E}\left[\sum\limits_{l=2}^M\sum\limits_{\substack{|M_1|=l\\|M_2|=M-l}}^{M_1\cup M_2=M} Pr\Bigg(\alpha_{m_1}^{t-1} = 1 \forall m_1 \in M_1,\alpha_{m_2}^{t-1} = 0 \right.  \\
& \left. \quad \forall m_2 \in M_2 \Bigg|\sum\limits_{m=1}^M\alpha_m^{t-1}\geq2\Bigg)\frac{1}{M^2}\sum\limits_{i=1}^{M_1}\sum\limits_{\substack{j=1,j\neq i}}^{M_1}\Phi_i\Phi_j\right]\\&
