& \left. \quad \forall m_2 \in M_2 \Bigg|\sum\limits_{m=1}^M\alpha_m^{t-1}\geq2\Bigg)\frac{1}{l^2}\sum\limits_{i=1}^{M_1}\sum\limits_{\substack{j=1,j\neq i}}^{M_1}\Phi_i\Phi_j\right]\\&
= \mathbb{E}\left[\sum\limits_{l=2}^M\sum\limits_{\substack{|M_1|=l\\|M_2|=M-l}}^{M_1\cup M_2=M}\frac{1}{l^2}\sum\limits_{i=1}^{M_1}\sum\limits_{\substack{j=1,j\neq i}}^{M_1}\Phi_i\Phi_j \right.  \\
& \left.\quad\cdot\frac{\prod\limits_{m_1 \in M_1}q_{s,m_1}\prod\limits_{m_2 \in M_2}(1-q_{s,m_2})}{1-\prod\limits_{m \in M}(1-q_{s,m})-\sum\limits_{m \in M}\prod\limits_{\substack{m' \in M \\ m' \neq m}}(1-q_{s,k'})}\right]\\&
\leq \sum\limits_{l=2}^M\sum\limits_{\substack{|M_1|=l\\|M_2|=M-l}}^{M_1\cup M_2=M}\mathbb{E}\left[\sum\limits_{i=1}^{M_1}\sum\limits_{\substack{j=1,j\neq i}}^{M_1}q_{s,i}\Phi_iq_{s,j}\Phi_j\right]\cdot \frac{1}{l^2} \\&
\quad \cdot \frac{\prod\limits_{m_2 \in M_2}(1 - q_{s,m_2})}{1 - \prod\limits_{m \in M}(1 - q_{s,m}) - \sum\limits_{m \in M} \prod\limits_{\substack{m' \in M \\ m' \neq m}} \left( 1 - q_{s,m'} \right)} \\&
