%**********************附录D
\section*{APPENDIX D}
Based on the smoothness of the loss function $\mathcal{L}(\cdot)$, for any training round $t\geq0$, the second-order Taylor expansion of $\mathcal{L}(\cdot)$ can be expressed as
\begin{equation}
\begin{aligned}
\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^t\right)\right]&\leq \mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{t-1}\right)\right]+\frac{\beta}{2}\mathbb{E}\left[\|\boldsymbol{w}^t-\boldsymbol{w}^{t-1}\|^2\right]\\&\quad+\mathbb{E}\left[\langle \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right),\boldsymbol{w}^t-\boldsymbol{w}^{t-1}\rangle\right].
\end{aligned}
\end{equation}

And according to \textbf{Lemma 2} and \textbf{Lemma 3}, we have
\begin{equation}
\begin{aligned}
\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^t\right)\right]&\leq\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{t-1}\right)\right]+\frac{\sum\limits_{l=1}^{L_c} \beta\eta^2\sigma_l^2}{Mb}\\&\quad +\frac{2\beta\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2+16\beta^3\eta^4I^2\sum\limits_{l=1}^{L_c}G_l^2\\&\quad+2\beta\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-\bar{q}_s)^2+\bar{q}_s^2\right)\Lambda_m^2\\&\quad+\eta  \left(\sum\limits_{m=1}^M \Lambda_m^2 +4M\beta^2\eta^2I^2\sum\limits_{l=1}^{L_c}G_l^2\right)\\
&\quad- \frac{\eta}{2} \mathbb{E}\left[\left\|\sum\limits_{m=1}^M \varphi_m \nabla \mathcal{L}\left(\boldsymbol{w}^{t-1}\right)\right\|^2\right]\\&
\quad +4\beta\eta^2\mathbb{E}\left[\|\nabla\mathcal{L}(\boldsymbol{w}^{t-1})\|^2\right].
\end{aligned}
\label{fuluD}
\end{equation}

Next, we rearrange Eq. \eqref{fuluD} and divide its both sides by $\frac{\eta\left(\sum\limits_{m=1}^M\varphi_m\right)^2-8\beta\eta^2}{2}$:
\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\|\nabla\mathcal{L}(\boldsymbol{w}^{t-1})\|^2\right]\leq\frac{2}{\eta\left(\sum\limits_{m=1}^M\varphi_m\right)^2-8\beta\eta^2}\cdot\\&\quad\Bigg(\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{t-1}\right)\right]-\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{t}\right)\right]+\frac{\sum\limits_{l=1}^{L} \beta\eta^2\sigma_l^2}{Mb}\\& \quad+\frac{2\beta\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2+16\beta^3\eta^4I^2\sum\limits_{l=1}^{L_c}G_l^2\\&\quad+2\beta\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-\bar{q}_s)^2+\bar{q}_s^2\right)\Lambda_m^2\\&\quad+  \sum\limits_{m=1}^M \eta\Lambda_m^2 +4M\beta^2\eta^3I^2\sum\limits_{l=1}^{L_c}G_l^2\Bigg).
\end{aligned}
\end{equation}

For ensuring the convergence of split federated learning process, we let $\eta\left(\sum\limits_{m=1}^M\varphi_m\right)^2-8\beta\eta^2 > 0$, which leads to $0<\eta<\frac{\sum\limits_{m=1}^M\varphi_m}{8\beta}$. Furthermore, adding up the aforementioned terms from $t=1$ to $N$ and then dividing both sides by $N$ results in
\begin{equation}
\begin{aligned}
&\frac{1}{N}\sum\limits_{t=1}^N\mathbb{E}\left[\|\nabla\mathcal{L}(\boldsymbol{w}^{t-1})\|^2\right]\leq\frac{2}{\eta\left(\sum\limits_{m=1}^M\varphi_m\right)^2-8\beta\eta^2}\cdot\\&\quad\Bigg(\frac{\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{0}\right)\right]-\mathbb{E}\left[\mathcal{L}\left(\boldsymbol{w}^{*}\right)\right]}{N}+\frac{\sum\limits_{l=1}^{L} \beta\eta^2\sigma_l^2}{Mb}\\& \quad+\frac{2\beta\eta^2}{M^2} \sum\limits_{m=1}^M \Lambda_m^2+16\beta^3\eta^4I^2\sum\limits_{l=1}^{L_c}G_l^2\\&\quad+2\beta\eta^2\sum_{m=1}^M\kappa_m\left((q_{s,m}-\bar{q}_s)^2+\bar{q}_s^2\right)\Lambda_m^2\\&\quad+ \sum\limits_{m=1}^M \eta\Lambda_m^2 +4M\beta^2\eta^3I^2\sum\limits_{l=1}^{L_c}G_l^2\Bigg),
\end{aligned}
\end{equation}
where $\boldsymbol{w}^*$ is the optimal model.

