=\frac{1}{M}\mathbb{E}\left[\sum\limits_{m=1}^M\frac{q_s^m(1-q_s)^{M-m}}{1-(1-q_s)^M}\sum\limits_{\substack{|\mathcal{M}_1|=m\\|\mathcal{M}_2|=M-m}}^{\mathcal{M}_1 \cup \mathcal{M}_2=\mathcal{M}}\sum\limits_{m_1 \in \mathcal{M}_1}\mathbf{g}_{m_1}^{t-1}\right]\\&
=\frac{1}{M}\mathbb{E}\left[\sum\limits_{m=1}^M\frac{q_s^m(1-q_s)^{M-m}}{1-(1-q_s)^M}C_{M-1}^{m-1}\sum\limits_{m \in \mathcal{M}}\mathbf{g}_{m}^{t-1}\right]
%=\frac{1}{M}\mathbb{E}\left[\sum\limits_{m=0}^{M-1}\frac{q_s^{m+1}(1-q_s)^{M-m-1}}{1-(1-q_s)^M}C_{M-1}^{m}\sum\limits_{m \in %\mathcal{M}}\mathbf{g}_{m}^{t-1}\right]
\\&
=\frac{q_s}{\left[1-(1-q_s)^M\right] \cdot M} 
\mathbb{E}\left[\sum\limits_{m=0}^{M-1}q_s^{m}(1-q_s)^{M-m-1} \right. \\
& \quad \left. C_{M-1}^{m} \sum\limits_{m \in \mathcal{M}} \mathbf{g}_{m}^{t-1} \right]\\&
=\frac{q_s}{\left[1-(1-q_s)^M\right] \cdot M}\sum\limits_{m\in \mathcal{M}}\mathbb{E}\left[\mathbf{g}_m^{t-1}\right].
