% \paragraph{Prominence Mechanisms}
 % In general, this policy requires a \textit{BuyBox mechanism} for choosing the prioritized seller: 
\begin{definition}
A \emph{prominence mechanism} $\mathcal M$ maps a price profile $\mathbf p = \avector{p}{m}$ to $\mathbf x^{\mathcal M} (\mathbf p):= \avector{x}{m}$, with $\sum x_i \leq 1$, where $x_i$ is the probability that seller~$i$ wins prominence.
\end{definition}
% In this work, we focus on the market outcomes of various Buy Box mechanisms, especially those that induce low prices in pure equilibria.
% One can imagine some natural implementation of Buy Box mechanisms, for example, simply awarding the Buy Box to the sellers that offer the lowest price, or the highest product quality, etc.

% \vskip 12pt
If one aims to drive down prices, it is tempting to simply give prominence to the seller with the lowest price:

\begin{definition}
    The \emph{Lowest Price First (LPF) Mechanism} gives prominence to the seller with the lowest price, breaking ties uniformly at random.
\end{definition}

% Proposition \ref{proposition_no_symmetric} and Theorem \ref{theorem:no_BB_no_eq} naturally extends to the LPF mechanism: the following corollary demonstrate that, despite some action is taken in alleviating the buyer's inspection obstacle by placing the lowest-price seller in a Buy Box, the market yet again admit no pure equilibrium.
It takes only a moment of thought to realize that, compared with the plain presentation, LPF only offers more incentive for the sellers to undercut each other, and can no better sustain equilibria.
% The proof of the following proposition can be found in the appendix.

\begin{restatable}{proposition}{proplpf}% [LPF mechanism is just as bad as plain presentation]
  \begin{enumerate}[(a)]
    \item % The LPF mechanism does not support any pure symmetric equilibrium.
      For any $p> 0$, the symmetric price profile $\mathbf p = (p, \ldots, p)$ is not an equilibrium under the LPF mechanism.
      If $\theta_0 \geq V$, LPF admits no symmetric equilibrium.

    \item With two sellers, the LPF mechanism admits no pure equilibrium.
  \end{enumerate}
\end{restatable}


\subsection{The Dictator Mechanisms}
\label{sec:dictator}

% To fix the issue, specifically, consider the following Dictator-$t$ mechanism

We now introduce a family of powerful mechanisms, where a seller has to post a price dictated by the platform to win prominence.
It turns out that these mechanisms encompass all symmetric equilibria in a natural family of mechanisms
(Definition~\ref{def:standard}, Theorem~\ref{thm:dict}). 

\begin{definition} [Dictator-$t$ mechanism]
  The \emph{Dictator-$t$ mechanism} is a mechanism parameterized with a target price~$t > 0$. It assigns prominence to sellers who set their prices at $t$, breaking ties uniformly at random.
  Formally, for any price profile $\mathbf{p} = (p_1, p_2, \ldots, p_m)$, the prominence allocation vector $\mathbf{x}(\mathbf{p})$ is 
    $$
    \mathbf{x}^\text{Dictator-$t$}(\mathbf{p}) = \left(\frac{\mathbb{I}[p_1 = t]}{N_t},\  \frac{\mathbb{I}[p_2 = t]}{N_t}, \ \ldots,\  \frac{\mathbb{I}[p_m = t]}{N_t} \right),
    $$
    where $N_t = \sum_{i \in [m]} \mathbb{I}[p_i = t]$ is the number of sellers pricing at~$t$, and $\mathbb{I}[\cdot]$ is the indicator function.
\end{definition}

% A mechanism can sometimes be designed to be arbitrary and unfair. For instance, assigning the Buy Box to a particular seller regardless of the prices set by others. To ensure that the mechanisms we study are fair in general and foster competition, we focus on the following specific class of nontrivial mechanisms that are \textit{anonymous} and \textit{always allocate}.
% We next show that the Dictator-$t$ mechanism obtains the lowest possible price at equilibrium among a class of nontrivial mechanisms.

\begin{definition}
\label{def:standard}
 A prominence mechanism is said to be
    \begin{itemize}
        \item[(a)] \emph{anonymous}, if for any permutation $\sigma$ on $[m]$ and any price profile $\mathbf{p} := \avector{p}{m}$, the allocation satisfies $x_i(\mathbf{p}) = x_{\sigma(i)}(p_{\sigma(1)}, \dots, p_{\sigma(m)})$ for every $i \in [m]$;
        \item[(b)] \emph{always allocating in equilibrium}, if for any symmetric equilibrium $\mathbf{p}$, $\sum_{i=1}^{m} x_i(\mathbf{p}) = 1$.
    \end{itemize}
    A mechanism is said to be \emph{standard} if it is both anonymous and always allocating in equilibrium.
\end{definition}

\begin{restatable}{theorem}{thmDictatorOpt}
\label{theorem:dictator_opt}
\label{thm:dict}
    For any standard prominence mechanism $\mathcal{M}$, if $\mathbf p = (p, \dots, p)$ is a symmetric equilibrium, then $\mathbf p$ is also an equilibrium for the Dictator-$p$ mechanism.
\end{restatable}

The theorem is proved by observing that, in any standard mechanism, at a symmetric pure equilibrium price~$p$, each seller must be in the Buy Box with probability $\frac 1 m$, the same as in the Dictator-$p$  mechanism.
It remains only to show that a deviation in the dictator mechanism cannot be more profitable than the same deviation in any other standard mechanism.

