\propHighPriceWhenCTooBig*
    \begin{proof}
    Consider the Dictator's Mechanism that sets the target price at the monopoly price:
    \[
    p^\star := \arg\max_p \, p \, (1 - F(p)).
    \]
    As long as the inspection cost is high enough ($c > \mathbb{E}[v] - \frac{p^\star}{m}$), it is optimal for every seller to maintain the monopoly price $p^\star$. This is because any seller deviating to a price $p' \neq p^\star$ would lose the prominent status and could only be inspected if all other sellers' values satisfy $(v - p^\star)_+ \leq \theta_0 - p'$. This requires that $p'$ is low enough: $p' \leq \theta_0$. Therefore, the deviating seller's revenue is at most $\theta_0$.

    Furthermore, as long as the monopoly profit satisfies:
    $$
    \frac{p^\star}{m} \geq \theta_0,
    $$
    and under our assumption of a high enough inspection cost $c$:
    $$
    \mathbb{E}\left[(v - \theta_0)^+\right] = c > \mathbb{E}\left[\left(v - \tfrac{p^\star}{m}\right)^+\right] \implies \frac{p^\star}{m} \geq \theta_0,
    $$
    the monopoly price vector $\vec{p}^\star = (p^\star, \dots, p^\star)$ will be an equilibrium.
    \end{proof}

\lemmaDcxExpression*
    \begin{proof}

    Since the equilibrium is symmetric, without loss of generality, assume that the deviating seller is seller~\(1\). We may occasionally omit the seller subscript when there is no ambiguity. Let \( x = p' - t \), where \( p' \) is the deviated price. We will analyze the demand case by cas with respect to $x$'s value.

    \begin{itemize}
        \item \textbf{Case \( x \leq -1 \) (i.e., \( p' < t + 1 \)).} This scenario is covered in the proof of Lemma~\ref{lemma:lemma_1_extension_for_Buy_Box}. In this case, the seller's demand is equal to \(1\).

        \item \textbf{Case \( -1 < x < 0 \) (i.e., \( t - 1 < p' < t \)).} Note that, in general, \( p' \) could be less than \(0\). However, this does not affect our analysis of the demand, although setting such a price would result in negative revenue for the seller.

        Under the Dictator Mechanism, the deviating seller is not prominent. Since all other sellers are identical, to analyze the deviating seller's demand, we assume that seller~\(2\) is prominent. There are two mutually exclusive scenarios in the buyer's search behavior that result in a purchase from seller~\(1\):

        \begin{itemize}
            \item \textbf{Scenario 1:} The buyer sees seller~\(2\) (prominent), inspects seller~\(1\) (not prominent), buys from seller~\(1\), and then leaves. This requires:
            \begin{enumerate}[(i)]
                \item The buyer chooses to inspect seller~\(1\) after observing seller~\(2\)'s value:
                \[
                v_2 - t < \theta_0(c) - p' \: \Leftrightarrow \ : v_2 < \theta_0(c) - x.
                \]
                \item After inspecting seller~\(1\), the buyer prefers seller~\(1\) over seller~\(2\):
                \[
                \label{condition_2.1}
                v_1 - p' \geq v_2 - t \: \Leftrightarrow \: v_1 \geq v_2 + x.
                \]
                \item After inspecting seller~\(1\), the buyer does not inspect any additional sellers:
                \begin{align*}
                    & \max(v_1 - p', v_2 - t) \geq \theta_0(c) - t  \\
                    \Leftrightarrow\: & \underbrace{\max(v_1 - x, v_2) = v_1 - x}_{\text{by condition~\ref{condition_2.1}}} \geq \theta_0(c).
                \end{align*}
            \end{enumerate}
            The demand contribution from this scenario is
            \[
            \int_V^{\max(\theta_0(c) - x, V)} \int_{\max(\theta_0(c) + x, v_2 + x)}^{V + 1} \dd F(v_1)\, \dd F(v_2).
            \]

            \item \textbf{Scenario 2:} The buyer first inspects seller~\(2\), then inspects all sellers, compares all products, and finally buys from seller~\(1\). This requires:
            \begin{enumerate}[(i)]
                \item The buyer chooses to inspect seller~\(1\) after observing seller~\(2\)'s value:
                \[
                v_2 - t < \theta_0(c) - p' \: \Leftrightarrow \: v_2 < \theta_0(c) - x.
                \]
                \item After inspecting all sellers, the buyer prefers seller~\(1\)'s product:
                \label{condition_2.2}
                \begin{align*}
                & v_1 - p' \geq \max_{i = 2, \ldots, m} \{ v_i - t \} \\
                \Leftrightarrow \: &  v_1 - x \geq \max_{i = 2, \ldots, m} \{ v_i \}.
                \end{align*}
                \item The buyer chooses to inspect all remaining sellers (\( i = 3, \ldots, m \)):
                \begin{align*}
                    \max\left(v_1 - p', \max_{i = 2, \ldots, m} \{ v_i - t \}\right) \geq \theta_0(c) - t \\
                    \Leftrightarrow \underbrace{\max\left(v_1 - x, \max_{i = 2, \ldots, m} \{ v_i \}\right) = v_1 - x}_{\text{by condition~\ref{condition_2.2}}} \geq \theta_0(c).
                \end{align*}
            \end{enumerate}
            The demand contribution from this scenario is
            % \[
            % \int_V^{\max(\theta_0(c) - x, V)} \int_{v_2 + x}^{\max(\theta_0(c) + x, v_2 + x)} F^{m-2}(v_1 - x) \, \dd F(v_1)\, \dd F(v_2).
            % \]
            \begin{align*}
                \int_V^{\max(\theta_0(c) - x, V)} & \int_{v_2 + x}^{\max(\theta_0(c) + x, v_2 + x)} \\
                & F^{m-2}(v_1 - x) \, \dd F(v_1)\, \dd F(v_2).
            \end{align*}
        \end{itemize}

        These two scenarios are mutually exclusive. Therefore, the total demand of the deviating seller when setting the price \( p' = t + x \) for \( x \in (-1, 0) \) is
        % \begin{align*}
        %     \D_c(x) &:= \int_V^{\max(\theta_0(c) - x, V)} \int_{\max(\theta_0(c) + x, v_2 + x)}^{V + 1} \dd F(v_1)\, \dd F(v_2)\\
        %     & \quad + \int_V^{\max(\theta_0(c) - x, V)} \int_{v_2 + x}^{\max(\theta_0(c) + x, v_2 + x)} F^{m-2}(v_1 - x) \, \dd F(v_1)\, \dd F(v_2).
        % \end{align*}
        \begin{align*}
            & \quad \D_c(x) :=  \\
            &\int_V^{\max(\theta_0(c) - x, V)} \int_{\max(\theta_0(c) + x, v_2 + x)}^{V + 1} \dd F(v_1)\, \dd F(v_2) \\
            &\quad + \int_V^{\max(\theta_0(c) - x, V)} \int_{v_2 + x}^{\max(\theta_0(c) + x, v_2 + x)} \\
            &\quad\quad F^{m-2}(v_1 - x) \, \dd F(v_1)\, \dd F(v_2).
        \end{align*}
        \item \textbf{Case \( 0 \leq x < \theta_0(c) - V \) (i.e., \( t \leq p' < \theta_0(c) \)).} In this case, particularly for \( p' = t \) and define \( \D_c(0) := \lim_{x \to 0^+} \D_c(x) \). For \( x \in (0, \theta_0(c) - V) \), since the deviating seller's price \( p' = t + x > t \), they are inspected last only if the values of all other sellers \( i = 2, \ldots, m \) satisfy \( v_i \leq \theta_0(c) - x \). Additionally, the deviating seller~\(1\) is purchased from only if
        \[
        v_1 - p' \geq \max_{i = 2, \ldots, m} \{ v_i - t \}.
        \]
        These conditions translate to
        \[
        \D_c(x) = \int_V^{\theta_0(c) - x} \left(1 - F(v + x)\right) \, \dd F^{m - 1}(v).
        \]

        \item \textbf{Case \( x \geq \theta_0(c) - V \) (i.e., \( p' > \theta_0(c) \)).} In this scenario, the deviating seller~\(1\) will never be inspected. Suppose that seller~\(2\) is prominent and yields a value \( v_2 \):
        \begin{align*}
            v_2 - t & \geq V - t \\
            & = V - (p' - x) = V - x - p' \geq \theta_0(c) - p'.
        \end{align*}
        Since buyers will never choose to inspect seller~\(1\), the seller's demand is zero.
    \end{itemize}

    This concludes the proof. The deviating seller's demand is thus expressed as a function of the deviation \( x = p' - t \), \emph{independent from $t$}, where \( p' \) is the deviated price and \( t \) is the symmetric equilibrium price of the remaining sellers.
    \end{proof}

\thmTc*
    \begin{proof}
    Theorem \ref{theorem:dictator_opt} states that it is sufficient to consider dictator's mechanism for any implementable equilibrium price. Consider Dictator mechanism setting target price at $t$, inducing symmetric equilibrium $(t, t, \ldots, t)$. 

    If any seller deviates to $p' = t + x$, Lemma~\ref{lemma:D_c_independent_of_t} gives the seller's post-deviate demand expressed in $x$: $\D_c(\cdot)$. The equilibrium condition can then be expressed as:
    \begin{align}
    \label{key_EQ_condition}
        \underbrace{(x + t)}_{p' = x + t} \cdot \underbrace{\D_c(x)}_{\text{seller $1$'s demand}}  \le \underbrace{\frac1m t}_{\text{Eq. revenue}}, & \quad \forall x \in \mathbb R
    \end{align}
    By transforming this condition algebraically, we obtain
    \begin{align}
    \label{key_EQ_condition_variant}
    \left(\frac 1m - \D_c(x)\right)t \ge x\D_c(x).
    \end{align}

    Discuss over potential value of $x$ (i.e. $p' = t + x$).
    \begin{itemize}
        \item \textbf{Case $x > 0$ (i.e. $p = x + t > t$}). It's evident that post-deviate demand $\D_c(x) < \frac 1m$. Hence the above condition translates to
        $$
        t \ge \frac{x\D_c(x)}{\frac 1m - \D_c(x)}, \forall x > 0.
        $$
        This gives a lower bound for implementable price $t$.
        \item \textbf{Case $x < 0$ (i.e. $p = x + t < t$}). Notice that the left-hand-side of the inequality~\ref{key_EQ_condition_variant}, $x\D_c(x) < 0$ --- so the condition automatically holds for $\frac1m - \D_c(x) \ge 0$. Now considers $x$ such that $\D_c(x) > \frac1m$, inequality~\ref{key_EQ_condition_variant} translates to
        $$
        t \le \frac{(-x)\D_c(x)}{\D_c(x) - \frac1m},\quad  \forall x < 0 \text{ and }\frac1m - \D_c(x) < 0
        $$.
    \end{itemize}
    And this sums up to be the condition for the theorem.
\end{proof}


 \exampleTc*
 \begin{proof}[Find $t^*(c), \bar t(c)$ for two uniform seller.] 

 For convenience, use $\theta$ to denote $\theta_0(c)$.
 First calculate $\D_c(x)$:
 \begin{align*}
     \D_c(x) = \begin{cases}
        1 & x < - 1\\
        \frac12 x^2  + \frac12 & x \in [-1, \theta - 3)\\
        -x + \frac12(\theta - 2)^2 & x\in [\theta - 3, 0)\\
        -\frac12 x^2 + \frac12 (\theta - 2)^2 & x \in [0, \theta - 2)\\
        0 & x\ge \theta - 2
     \end{cases}
 \end{align*}
Find $t^*(c)$ and $\bar t(c)$: let
$$
\chi^c(x) := \frac{x \D_c(x)}{\frac12 - \D_c(x)}
$$
then
$$
\chi^c{}'(x) = \frac1{(\frac12 - \D_c(x))^2}\left(\D_c(x)(\frac12 - \D_c(x)) + \frac12 x D_c'(x)\right).
$$
Let $\tilde \chi(x) := \D_c(x)(\frac12 - \D_c(x)) + \frac12 x D_c'(x)$,
$$
\tilde \chi^c{}'(x) = \D'_c(x)(1 - 2\D_c(x)) + \frac12 x \D_c''(x).
$$
To get $t^*(c) = \sup_{x > 0}\chi^c(x)$, notice that only needs to consider $x\in (0, \theta - 2)$ where $\D_c(x) > 0$. Within this region, $\D_c(x) < \frac12$, $\D_c(x) = -x < 0$ and $\D_c''(x) = -1$, therefore
$$
\tilde \chi^c{}'(c) \le 0.
$$
And
\begin{small}
    $$
    \tilde \chi^c(x) =  - \frac14 x^4 + (\frac12(\theta - 2)^2 - \frac12)x^2 + \frac12(\theta - 2)^2 \left(\frac12 - \frac12(\theta - 2)^2\right).
    $$
\end{small}
So we can solve for the unique interior supremum point $x^*$ that maximizes $\chi^c(x)$:
$$
(x^*_c)^2= -(\hat \theta + \frac12) + \sqrt{2\hat \theta + \frac14},
$$
where $\hat\theta = 1- (\theta - 2)^2$.
Plug in $x^*_c$ into $\chi^c(x)$ (because $t^*(c) = \sup_{x > 0}\chi^c(x)$) we obtain 
\begin{align*}
    t^*(c) & = \frac{x^*_c \D_c(x^*_c)}{\frac12 - \D_c(x^*_c)}\\
    & =  \frac{\sqrt{-(\hat \theta + \frac12) + \sqrt{2\hat \theta + \frac14}}\times \frac12\left(\frac32 - \sqrt{2\hat \theta + \frac14}\right)}{\frac12\sqrt{2\hat \theta + \frac14} - 1}\\
    & = \frac{\sqrt{-((2\sqrt{2c} - 2c) + \frac12) + \sqrt{2(2\sqrt{2c} - 2c) + \frac14}}}{\frac12\sqrt{2(2\sqrt{2c} - 2c) + \frac14} - 1}\\
    & \quad \times \frac12\left(\frac32 - \sqrt{2(2\sqrt{2c} - 2c) + \frac14}\right)
\end{align*}
Vice versa, we can directly calculate $\bar t(c)$.

For $x\in [\theta - 3, 0)$, let $\tilde \theta = (\theta - 2)^2$, so $\D_c(x) = -x + \frac12 \tilde \theta$, and
\begin{small}
\begin{align*}
\chi^c(x) & = \frac{x(-x + \frac12 \tilde \theta)}{\frac12 - ( -x + \frac12 \tilde \theta)}\\
& = (\frac12 \tilde \theta -x - \frac12) + \frac{\frac14(1 - \tilde \theta)}{(\frac12 \tilde \theta -x - \frac12)} + 1 - \frac12 \tilde \theta\\
& \ge 2.
\end{align*}
\end{small}
As for $x\in [-1, \theta - 3)$,
\begin{align*}
    \chi^c(x) & = \frac{x(-x^2 + \frac12)}{-\frac12 x^2}\\
    & = -(x + \frac1x) \ge 2.
\end{align*}
Therefore,
$$
\bar t(c) \equiv 2.
$$
\end{proof}

\propTStarProperties*
    \begin{proof}[Proof of Proposition~\ref{prop:t_star_properties}]
    We will first prove that $t^*(\cdot)$ is monotonically decreasing and continuous. Then prove its endpoint property.
    \paragraph{Monotonicity of $t^*(c)$.}
    Theorem~\ref{theorem:m_seller_general_T(c)} gives
    $$t^*(c) := \sup_{x > 0} \left\{\frac{x \D_c(x)}{\frac1m - \D_c(x)} \right\}.$$
    Fix $ x $, consider inspection costs $ c_1 \leq c_2 $ with $\theta_0(c_1) \geq \theta_0(c_2)$, we have, for $x \ge 0$:    
    \begin{align*}
        \D_{c_1}(x) - \D_{c_2}(x) 
        & = \int_V^{\theta_0(c_1) - x} (1 - F(v + x))\, \dd F^{m-1}(v) \\
        & \quad - \int_V^{\theta_0(c_2) - x} (1 - F(v + x))\, \dd F^{m-1}(v) \\
        & = \int_{\theta_0(c_2) - x}^{\theta_0(c_1) - x} (1 - F(v + x))\, \dd F^{m-1}(v) \geq 0.
    \end{align*}
    So, fix $x$, $\D_c(x)$ decreases as $c$ increases. Therefore, for any $c_1 \ge c_2$, $\D_{c_1}(x) \le \D_{c_2}(x)$. For any $x > 0$:
    \begin{align*}
        \frac{x\D_{c_1}(x)}{\frac1m - \D_{c_1}(x)} 
        & = (-x) + \frac{\frac1m}{\frac1m - \mathcal D_{c_1}(x)} \\
        & \le (-x) + \frac{\frac1m}{\frac1m - \mathcal D_{c_2}(x)} = \frac{x\D_{c_2}(x)}{\frac1m - \D_{c_2}(x)}.
    \end{align*}

    This implies $t^*(c_2) \ge t^*(c_1)$, hence proving $t^*(\cdot)$ monotonically decreases. 

    \paragraph{Continuity of $t^*(c)$.} 
    The expression $t^*(c) := \sup_{x > 0} \left\{\frac{x \D_c(x)}{\frac1m - \D_c(x)} \right\}$ takes supremum over $x > 0$. Because $\D_c(x) = 0$ for $x\ge \theta_0(c) - V$, it suffices to consider the open interval $x\in (0, \theta_0(c) - V)$. 

    Define $\phi(c, x) := \frac{x\D_c(x)}{\frac{1}{m} - \D_c(x)}$. The function $\phi$ is jointly continuous in $(c, x)$ for $x > 0$. Given that the supremum point $x^*$ that maximizes $\phi(c, x)$ within the interval $(0, \theta_0(c) - V)$ is obtained in an interior point, by pointwise convergence, $t^*(c) = \inf_{x \in (0, \theta_0(c) - V)} \phi(c, x)$ will also exhibit continuity. 

    \paragraph{The limiting convergence as $c \to \bar c^-$.}
    Discuss over the region of $x$ that we're taking supremum over for $t^*(c) := \sup_{x > 0} \left\{\frac{x \D_c(x)}{\frac1m - \D_c(x)} \right\}$:
    \begin{itemize}
        \item $x\in [\theta_0(c) - V, \infty)$, $\D_c(x) = 0$. So this part doesn't contribute to $t^*(c)$.
        \item $x \in (0, \theta_0(c) - V)$:
        Look at $\D_c(x)$ as $x\to 0^+$:
        \begin{align*}
            \lim_{x\to 0^+} \D_c(x) & = \lim_{x\to 0^+} \int_V^{\theta_0(c) - x} \left(1 - F(v + x)\right) \, \dd F^{m-1}(v)\\
            & = \int_V^{\theta_0(c)} \left(1 - F(v)\right) \, \dd F^{m-1}(v)\\
            & = \int_V^{\theta_0(c)} \dd F^{m-1}(v) - \frac{m-1}m \int_V^{\theta_0(c)} \dd F^m(v)\\
            & = F^{m-1}(\theta_0(c)) - \frac{m-1}m F^m(\theta_0(c)),
        \end{align*}
        we have, as $x\to 0^+$
        \begin{align*}
            & \quad  \lim_{x\to 0^+}\left(\frac1m - \D_c(x)\right) \\
            & = \frac1m - \left(F^{m-1}(\theta_0(c)) - \frac{m-1}m F^m(\theta_0(c))\right).
        \end{align*}
        Let $g(\alpha) = \frac1m - \left(\alpha^{m-1} - \frac{m-1}m \alpha^m \right)$, for $\alpha\in [0, 1]$. $g(1) = 0$, $g'(\alpha) = -(m - 1)\alpha^{m-2}(1 - \alpha) < 0, \forall \alpha\in (0, 1)$. So $g(\alpha) > 0, \forall \alpha \in (0, 1)$. As $c \to \bar c^+$, $\theta_0(c) \to V$ so for sure $F(\theta_0(c)) \in(0, 1)$ (actually $F(\theta_0(c))$ is bounded far away from $1$). Plug in $\alpha = F(\theta_0(c))$, we have
        $$
        \lim_{x\to 0^+}\left(\frac1m - \D_c(x)\right) = g(F(\theta_0(c))) > 0.
        $$
        Notice that as $c\to c^-$, $\theta_0(c) \to V^+$:
        \begin{align*}
            & \quad \lim_{c\to \bar c^-} \sup_{x\in (0, \theta_0(c) - V)} \left\{\frac{x \D_c(x)}{\frac1m - \D_c(x)} \right\} 
            \\
            & \le \lim_{c\to \bar c^-} \left(\theta_0(c) - V\right) \sup_{x\in (0, \theta_0(c) - V)} \left\{\frac{\D_c(x)}{\frac1m - \D_c(x)} \right\} \\
            & \le \lim_{c\to \bar c^-} \left(\theta_0(c) - V\right) \sup_{x\in (0, \theta_0(c) - V)} \left\{\frac{1}{\frac1m - \D_c(x)} \right\}
            \\
            & = 0.
        \end{align*}
    \end{itemize}
    Taking together the two regions of $x$ discussed above, $\lim_{c\to \bar c^-}  t^*(c) = 0$.
    \paragraph{The limiting convergence as $c \to 0^+$.}
    First, consider the equilibrium \textbf{without} inspection cost. In this case, the demand function for the deviated seller $\D_c(x)$ naturally extends to $c = 0$, when $\theta_0(0) = V + 1$:
        $$
        \D_0(x) = \int_V^{V + 1 - x} (1 - F(v + x))\, \dd F^{m-1}(v).
        $$
        Denote the equilibrium price as $(t_0, t_0, \ldots, t_0)$. The equilibrium condition for any deviate $x\in [\max(-1, -t_0), 1]$:
        \begin{align}
                & \quad\: (t_0 + x) \D_0(x) \le \frac 1m t\\
                \label{eq_condition:c=0}
                & \Leftrightarrow \D_0(x) \le \frac1m\frac{t_0}{t_0 + x}, \forall x\in [\max(-1, -t_0), 1)
        \end{align}
        Notice that, the inequality is strict at $x = 0$---when $\D_0(x) = \frac1m  = \frac1m\frac{t_0}{t_0 + x}\big |_{x = 0}$. And since $\D_0(x)$ is continuous, this situation implies that the slope of $\D_0$ and the right-hand side's equal-revenue curve coincide, yielding:
        $$
        t_0 = \frac{1}{m(m-1)\int_V^{V + 1}F^{m-2}(v)f^2(v)\, \dd v}.
        $$
        If (\ref{eq_condition:c=0}) holds for $t_0$, then $(t_0, \ldots, t_0)$ constitutes the unique symmetric equilibrium when the market is free of inspection costs. 

        As for the limiting equilibrium price when inspection cost approaches zero, $t^*(0)$, because $t^*(c) = \inf_x \phi(c, x)$ is continuous in $c$, all that remains is to verify $\sup_x \phi(0, x) = t_0$. This is confirmed at the limit as $x \to 0^+$:
        \begin{align*}
            \lim_{x \to 0^+}\phi(0, x) & = \lim_{x \to 0^+}\frac{x\D_0(x)}{\frac{1}{m} - \D_0(x)} \\
            & = \frac{\frac{\partial}{\partial x}x\D_0(x)}{\frac{\partial}{\partial x}[\frac{1}{m} - \D_0(x)]}\bigg|_{x = 0}\\
            & = \frac{1}{m(m-1)\int_V^{V + 1}F^{m-2}(v) f(v)^2\, \dd v}.
        \end{align*}
        By the monotonicity and continuity of $t^*(c)$, it would be contradictory for some $x > 0$ if $\phi(0, x) > t_0$, as this would imply, for some negligible cost of inspection $\epsilon \to 0$, that $\phi(\epsilon, x) > t_0$, leading to a contradiction. Therefore, presuming $t_0$ exists as a symmetric equilibrium absent inspection costs, $\lim_{c \to 0^+}t^*(c) = t_0$.
     \end{proof}

\propTBarProperties*
    \begin{proof}
        Theorem~\ref{theorem:m_seller_general_T(c)} states that
        $$
        \bar t(c) := \inf_{x < 0} \left\{\left(\frac{(-x) \D_c(x)}{\D_c(x) - \frac1m}\right)^+\right\}\setminus \{0\},
        $$
        so we focus on $x < 0$ and study the behavior of $\D_c(x)$ with respect to $c$. For convenience, denote
        \begin{small}
            \begin{align*}
                \tilde h_x(c)  & = \D_c(x) \\
                & = \int_V^{\theta_0(c) -x} \int_{\max(\theta_0(c) + x, v_2 + x)}^{V + 1} \, \dd F(v_1)\, \dd F(v_2) \\
                & \quad + \int_V^{\theta_0(c) -x} \int_{v_2 + x}^{\max(\theta_0(c) + x, v_2 + x)} F^{m-2}(v_1 - x)\, \dd F(v_1)\, \dd F(v_2).
            \end{align*}
        \end{small}

    Note that this is still inconvenient. Let
    \begin{small}
    \begin{align*}
        h_x(\theta) & := \tilde h_x(c) \circ \theta_0(c) \\
        & = \int_V^{\theta -x} \int_{\max(\theta + x, v_2 + x)}^{V + 1} \, \dd F(v_1)\, \dd F(v_2) \\
        & \quad + \int_V^{\theta -x} \int_{v_2 + x}^{\max(\theta + x, v_2 + x)} F^{m-2}(v_1 - x)\, \dd F(v_1)\, \dd F(v_2)\\
        & = \int_V^\theta \left(1 - F(\theta + x)\right)\, \dd F(v_2) \\
        & \quad + \int_V^\theta \int_{v_2 + x}^{\theta + x} F^{m-2}(v_1 - x)\, \dd F(v_1) \, \dd F(v_2)\\
        & \quad + \int_{\theta}^{\theta - x} \int_{v_2 + x}^{V + 1}\, \dd F(v_1)\, \dd F(v_2)\\
        & = \left(1 - F(\theta + x)\right) F(\theta) \\
        & \quad + \int_V^\theta \int_{v_2 + x}^{\theta + x} F^{m-2}(v_1 - x)\, \dd F(v_1) \, \dd F(v_2)\\
        & \quad + \int_\theta^{\theta - x} \left(1 - F(v_2 + x)\right)\, dF(v_2)
    \end{align*}
    \end{small}
    So
    \begin{align*}
        h_x'(\theta) & = -f(\theta + x) F(\theta) + \int_V^\theta F^{m-2}(\theta)f(\theta + x)\, \dd F(v_2)\\
        & \quad + \left(1 - F(\theta)\right) f(\theta - x) - \left(1 - F(\theta + x)\right) f(\theta)\\
        & = \left(F^{m-2}(\theta) - 1\right) f(\theta + x)F(\theta) + \left(1 - F(\theta)\right) f(\theta - x).
    \end{align*}
    Since $\theta_0(c)$ is the solution for $\mathbb E[v - \theta]^+ = c$, $\theta_0'(c) \le 0$, and this implies
    $$
    \tilde h_x'(c) = \theta_0'(c) h_x'(\theta).
    $$
    When $m = 2$
    $$
    h_x'(\theta) = \left(1 - F(\theta)\right) f(\theta - x) \ge 0.
    $$
    This implies that $\tilde h_x'(c)\le 0$, and that the demand for deviated seller with $p' > t$ would decrease as inspection cost $c$ increases.
    Thus, $ c_1 \leq c_2 \Rightarrow \D_{c_1}(x)\ge  \D_{c_2}(x), \forall x < 0$ when $m = 2$. So $ \forall x < 0$,
    \begin{align}
        \frac{(-x) \D_{c_1}(x)}{\D_{c_1}(x) - \frac1m} & = (-x) + \frac{(-x)\frac1m}{\D_{c_1}(x) - \frac1m} \\
        & \le (-x) + \frac{(-x)\frac1m}{\D_{c_2}(x) - \frac1m} = \frac{(-x) \D_{c_2}(x)}{\D_{c_2}(x) - \frac1m}.
    \end{align}
    And this implies $\bar t(c_1) \le \bar t(c_2), \forall 0 < c_1 \le c_2 \le \bar c$, thereby confirming the monotone property of $ \bar t(c) $.
    \end{proof}

