\thmThresholdTc*
    \begin{proof}
        We investigate the robustness of the Threshold-$t$ mechanism in sustaining an equilibrium.
        Assume that symmetric equilibrium $(t, t, \ldots, t)$ holds, where $t$ is the threshold below which a seller would win prominence uniformly at random. Consider seller $1$ who deviates from equilibrium price $t$ to $p_1' = t + x$. When $x > 0$, the buyer will find seller $1$'s offer least attractive and only inspected him at last if all other sellers are not satisfying enough (exactly similar to the case in Dictator's mechanism)
        \begin{align*}
            D_1^{\text{Threshold}}(p_1', t) = \D_c(p_1' - t).
        \end{align*}
        When seller $1$ deviates to a lower price, i.e. $x < 0$, he wins prominence with probability $1/m$. For the rest $1 - 1/m$, he is not prominent, conditional on which his demand corresponds to the case as if he is in Dictator mechanism. We can derive seller $1$'s demand as follows:
        \begin{align*}
            D_1^{\text{Threshold}}(p_1', t) 
            & = \frac1m D_{BB}(p_1', t) + (1 - \frac1m)\D_c(x)
        \end{align*}
        where, $D_{BB}(p_1', t)$ is seller $1$'s demand when he is prominent:
        \begin{small}
            \begin{align*}
                D_{BB}(p_1', t) & = P[\text{buyer buys seller $1$ without inspecting others}] \\
                & \quad + P[\text{buyer inspect all sellers and buys $1$}]\\
                & = P[v_1 - p_1' + t \ge \theta] \\
                & \quad + P[v_1 - p_1' + t \ge \theta \text{ and } v_1 - p_1' \ge \max_{i = 2, \ldots, m} v_i - t]\\
                & = P[v_1 - x \ge \theta] + P[v_1 - x \ge \theta \text{ and } v_1 - x \ge \max_{i = 2, \ldots, m} v_i]\\
                & = 1 - F(\theta + x) + \int_V^{\theta + x} (1 - F(v + x))\,\dd F^{m-1}(v).
            \end{align*}
        \end{small}
        Notice that, the demand of the deviated seller can again be delineated w.r.t. the price differential $x$. Denote $\tilde \D_c(x) := D_1^{\text{Threshold}}(p, t)$ as the demand of seller $1$. Specifically, for $x = 0$, let $\tilde \D_c(x) = \frac1m t$ so that it's left-continuous. And $\tilde \D_c(x)$ can be summarized as:
        % \begin{align*}
        %     \tilde \D_c(x) & = \begin{cases}
        %         \frac1m \D_c(x) + (1 - \frac1m)\left(1 - F(\theta_0(c) + x) + \int_V^{\theta_0(c) - x} (1 - F(v + x))\,\dd F^{m-1}(v)\right) & x < 0\\
        %         \D_c(x) = \int_{V}^{\theta - V} (1 - F(v + x))\, \dd F^{m-1}(v) & x > 0.
        %     \end{cases}
        % \end{align*}
    \begin{small}
        \begin{align*}
            \tilde \D_c(x) & = \begin{cases}
                \frac{1}{m} \D_c(x) + (1 - \frac{1}{m})\times \\
                \quad \left(1 - F(\theta_0(c) + x) + \int_V^{\theta_0(c) - x} (1 - F(v + x))\,\dd F^{m-1}(v)\right) \\
                \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad  \text{for } x < 0 \\
                \D_c(x) = \int_{V}^{\theta - V} (1 - F(v + x))\, \dd F^{m-1}(v) \\
                \quad \quad \quad \quad \quad \quad 
                \quad \quad \quad \quad \quad \quad \text{for } x > 0.
            \end{cases}
        \end{align*}
    \end{small}

        Threshold-$t$ mechanism can sustain a symmetric equilibrium $(t,t, \ldots, t)$ if and only if $t \in \tilde T(c)$, for $\tilde T(c)$ being articulated as:
        \begin{align*}
            \tilde T(c) := \left\{t : (x + t)\tilde \D_c(x) \le \frac{1}{m} t, \forall x \in [\max(-1, -t), 1]\right\}.
        \end{align*}

        Following the methodological approach in the proof of Theorem \ref{theorem:m_seller_general_T(c)}, $\tilde T(c)$, for $t\in \tilde (c)$ should satisfies the following criteria simultaneously:
        \begin{align*}
        t & \le \inf_{x < 0}\frac{(-x)\tilde \D_c(x)}{\tilde \D_c(x) - \frac{1}{m}},\\
        t & \ge \sup_{x > 0}\frac{x\tilde \D_c(x)}{\frac{1}{m} - \tilde \D_c(x)}.
        \end{align*}
        The set $\tilde T(c)$ is nonempty, indicating the existence of a symmetric equilibrium $(t, \ldots, t)$, if and only if:
        $$
        \sup_{x > 0}\frac{x\tilde \D_c(x)}{\frac{1}{m} - \tilde \D_c(x)} \le \inf_{x < 0}\frac{(-x)\tilde \D_c(x)}{\tilde \D_c(x) - \frac{1}{m}}.
        $$
        Let $\hat t(c) := \inf_{x < 0}\frac{(-x)\tilde \D_c(x)}{\tilde \D_c(x) - \frac{1}{m}}, t^*(c) := \sup_{x > 0}\frac{x\tilde \D_c(x)}{\frac{1}{m} - \tilde \D_c(x)}$. For the Threshold-$t$ mechanism with inspection cost $c$, $t$ can sustain an equilibrium if and only if $t^*(c) \le \hat t(c)$. If so, the implementable region of $t$ for Threshold mechanism is given by the following interval
        \begin{align*}
            [t^*(c), \hat t(c)].
        \end{align*}
    \end{proof}

