        \begin{align*}
            \partial_\theta \SW(\theta) & = -\theta f(\theta) + F(\theta)(1 - F(\theta)) \\
            & \quad + \theta f(\theta) (1 - F(\theta)) - \theta F(\theta)f(\theta) + 2\theta F(\theta) f(\theta)\\
            & = F(\theta)(1 - F(\theta)) \ge 0
        \end{align*}
        When $\theta = V$, $\SW(\theta) = \mathbb E[v]$. So that social welfare can be written in the following simplified form
        $$
        \SW(\theta) = \mathbb E[v] + \int_V^\theta F(s)(1 - F(s)).\ ds
        $$
    \end{proof}

\propCSsufficientcondition*

\begin{proof}

\newcommand{\DD}{{\mathcal {D}}} % D(\theta, x)
\newcommand{\g}{{\gamma}} % g(\theta) = D(\theta, x^*(theta))
\newcommand{\DDD}{{\mathbb D}} % D(\theta) = \partial_\theta D(\theta, \rho(\theta))
\newcommand{\h}{{h}} % h(\theta) = \partial_x D(\theta, x) composite x^*(\theta)

    When the inspection cost takes its upper bound $\bar c = \mathbb E[v] - V$, at which buyers simply ignore all non-prominent sellers at any symmetric equilibrium, the equilibrium price can be arbitrarily close to 0 (Proposition \ref{prop:t_star_properties}). 
    In this case, social welfare coincide with the consumer surplus (Proposition~\ref{prop:t_star_properties}, Lemma~\ref{lemma:SW_closed_form}):
    $$
    \SW(\bar c) = \CS(\bar c) = \mathbb E[v].
    $$

    By Lemma~\ref{lemma:SW_closed_form}, when the inspection cost $c$ drops in the range $(0, \bar c)$, social welfare rises to
    $$
    \SW(c) = \int_V^{\theta_0(c)} F(v)(1 - F(v))\, \dd v + \SW(\bar c)
    $$
    But the lowest equilibrium price $t^*(c)$ rises as well (Proposition~\ref{prop:t_star_properties}). Starting at $\bar c$, we wish to decrease inspection cost to increase consumer surplus using the prominence mechanism. Lowering inspection cost increases social welfare, meanwhile we would wish the rise in (implementable) equilibrium price lowerbound does not offset the rise in social welfare. Put together the two forces, consumer surplus would be better off if, for inspection cost $c$ that is slightly around the left-neighbourhood of $\bar c$:
    \begin{align}
        \SW(c) - \SW(\bar c) & > t^*(c) - 0\\
        & \Leftrightarrow \\
        \label{expression:consumer_surplus_rising}
        \int_V^{\theta} F(v)(1 - F(v))\, \dd v 
        & > \sup_{x\in (0, \theta - V)} \frac{x\D_c(x)}{\frac12 - \D_c(x)}
    \end{align}
    With a slight abuse of notation, define $\DD:[V, V +1]\times \mathbb R \to \mathbb R$ as:
    $$
    \DD(\theta, x) := \int_V^{\theta_0(c) - x} (1 - F(v + x))\, \dd F(v) \equiv \D_c(x) .
    $$
    Then, the condition for consumer surplus being better off (\ref{expression:consumer_surplus_rising}) can be expressed in the following equivalent form:
    \begin{align}
        & \exists \theta \in (V, V + 1), \exists x \in (0, \theta - V) \text{ such that:}\\
        \label{expression:consumer_surplus_rising_rearranged}
        & x\DD({\theta}, x)+ \varphi(\theta)\DD({\theta}, x) - \frac12 \varphi(\theta) < 0,
    \end{align}
    where, $\varphi(\theta) := \int_V^\theta F(v)(1 - F(v))\, \dd v$.
    To find $\theta, x$ such that (\ref{expression:consumer_surplus_rising_rearranged}) holds, define $\mu :\mathbb R^2 \to \mathbb R$ as
    \label{expression:mu_theta_x}
    \begin{align}
        \mu(\theta, x) := \begin{cases}
            x\DD({\theta}, x) + \varphi(\theta)\DD({\theta}, x) - \frac12 \varphi(\theta), \\
            \quad \quad \quad  \text{for }\theta \in (V, V + 1), x \in (0, \theta - V);\\
            0, \\
            \quad \quad \quad  \text{otherwise}.
        \end{cases}
    \end{align}
    Notice that $\lim_{x \to 0}\mu(\theta, x) = \lim_{x\to \theta - V}\mu(\theta, x) = 0$. Let
    \begin{align*}
        x^*(\theta) & := \begin{cases}
            \arg\min_x \mu(\theta, x) & \theta \in (V, V + 1)\\
            0 & \text{otherwise}.
        \end{cases}
    \end{align*}
    $x^*(\theta)$ is thus a well defined continuous function with $\lim_{\theta \to V} x^*(\theta) = 0$. Let $g(\theta) := \mu(\theta, x^*(\theta))$. Then, $g(V) = 0$. Study the derivative of $g(\cdot)$ when $\theta \to 0^+$.
    By envelope's theorem
    \begin{align*}
        g'(\theta) & = \pder[\mu]{\theta}{(\theta, x^*(\theta))}\\
        & = (x^*(\theta) + \varphi(\theta)) \pder[\DD]{\theta}{({\theta}, {x^*(\theta)})} + \varphi'(\theta)(\DD({\theta}, x^*(\theta)) - \frac12),
    \end{align*}
    and
    \begin{align*}
        \pder[\mathcal D]{\theta}{(\theta, x)}
        & = \pder{\theta}{\int_V^{\theta - x} (1 - F(v + x))\, \dd F(v)},\\
        & = (1 - F(\theta))f(\theta - x)\\
        \varphi'(\theta) & = F(\theta)(1 - F(\theta)),
    \end{align*}
    which jointly implies
    \begin{align*}
        g'(\theta) & = (1 - F(\theta))f(\theta - x^*(\theta))(x^*(\theta) + \varphi(\theta)) \\
        & \quad + F(\theta)(1 - F(\theta))(\DD({\theta}, {x^*(\theta)}) - \frac12)\\
        & = (1 - F(\theta))\left(f(\theta - x^*(\theta))(x^*(\theta) + \varphi(\theta))\right)\\
        & \quad + (1 - F(\theta))\left(F(\theta)(\DD({\theta}, {x^*(\theta)}) - \frac12)\right).
    \end{align*}
    Since $\varphi(V) = 0, x^*(V) = 0$:
    \begin{align*}
        \lim_{\theta \to V^+} g'(\theta) = 0.
    \end{align*}
    Unfortunately, this implies that we need to study higher order derivatives of $g$ and how they behave around $\theta \to V^+$. For convenience, in the subsequent analysis, for any general function $f(\cdot)$, denote $\lim_{x \to V^+} f(x)$ as $f(V^+)$. We first solve $x^*{}'(V^+)$ and $x^*{}''(V^+)$:

    Taking a step back: for general $\rho:[V, V + 1] \to \mathbb R$, define $\DDD_\rho(\theta) := \DD(\theta, \rho(\theta))$, so that:
    \begin{align*}
        \DDD_\rho(\theta) & = \int_V^{\theta - \rho(\theta)}(1 - F(v + \rho(\theta)))\, \dd F(v)
    \end{align*}
    and its first-order derivative:
    \begin{align*}
        \DDD'_\rho(\theta) & = (1 - \rho'(\theta))(1 - F(\theta))f(\theta - \rho(\theta)) \\
        & \quad - \rho'(\theta)\left(\int_V^{\theta - \rho(\theta)} f(v)f(v + \rho(\theta))\, \dd v\right),
    \end{align*}
    and, second-order derivative:
    \begin{align*}
        \DDD''_\rho(\theta) & = (1 - F(\theta))f'(\theta - \rho(\theta))(1 - \rho'(\theta))^2 \\
        & \quad + (1 - F(\theta))f(\theta - \rho(\theta))( - \rho''(\theta))\\
        & \quad - \rho''(\theta)\int_V^{\theta - \rho(\theta)} f(v)f(v + \rho(\theta))\, \dd v\\
        & \quad - \rho'(\theta)\Biggr[(1 - \rho'(\theta))f(\theta - \rho(\theta))f(\theta) \\
        & \quad \quad \quad + \int_V^{\theta - \rho(\theta)} f(v)f'(v + \rho(\theta))\rho'(\theta)\, \dd v\Biggr].
    \end{align*}
    Plug in $\rho = x^*, \theta \to V^+$:
    \begin{align}
    \label{expression:DDD_V_plus_primes_1}
        \DDD'_{x^*}(V^+) & = (1 - x^*{}'(V^+))f(V^+)\\
    \label{expression:DDD_V_plus_primes_2}
        \DDD''_{x^*}(V^+) & = f'(V^+)(1 - x^*{}'(V^+))^2 - f(V^+)(x^*{}''(V^+)) \\
        & \quad - x^*{}'(V^+) (1 - x^*{}'(V^+))f^2(V^+) 
    \end{align}

     Recall, $x^*(\cdot)$ is defined as the $x^*$ that achives $\inf_x \mu(\theta, x)$. Since $\mu(\theta, x) = 0 $ for $x\notin (0, \theta - V)$, fix $\theta$, $\mu(\theta, x)$'s minimum is attained at some interior $x \in (0, \theta - V)$, thus for $x^*(\theta) = \arg\min_x \mu(\theta, x)$:
    \begin{align}
        \label{expression:partial_x_D_equals_0}
        \pder[\mu]{x}(\theta, x^*(\theta)) = \pder[\DD]{x}(\theta, x^*(\theta))(x^*(\theta) + \varphi(\theta)) + \DD(\theta, x^*(\theta)) \equiv 0
    \end{align}
    Define $\h(\theta) := \pder[\DD]{x}{(\theta, x^*(\theta))}$, there is
    \begin{align*}
        \h(\theta) & = -(1 - F(\theta))f(\theta - x^*(\theta)) \\
        & \quad - \int_V^{\theta - x^*(\theta)}f(v)f(v + x^*(\theta))\, \dd v\\
        \h'(\theta) & = f(\theta)f(\theta - x^*(\theta)) \\
        & \quad - (1 - F(\theta))f'(\theta - x^*(\theta))(1 - x^*{}'(\theta)) \\
        &\quad  - \Biggr [(1 - x^*{}'(\theta))f(\theta - x^*(\theta))f(\theta) \\
        & \quad \quad \quad + \int_V^{\theta - x^*(\theta)}f(v)f'(\theta - x^*(\theta)) x^*{}'(\theta)\,\dd v \Biggr].
    \end{align*}

    Notice that $\h(V^+) = -f(V^+)$, $\h'(V^+) = \frac 12 f^2(V^+) - \frac12 f'(V^+)$. On the basis of notation $\h(\cdot)$ the preceding condition (\ref{expression:partial_x_D_equals_0}) of 
    $\pder[\mu]{x}(\theta, x^*  (\theta))\equiv 0$ is equivalent to
    \begin{align}
        \label{expression:partial_x_D_equals_0_transformed}
        \h(\theta)(x^*(\theta) + \varphi(\theta)) + \DD(\theta, x^*(\theta)) \equiv 0, \forall \theta \in (V, V + 1).
    \end{align}
    Essentially, taking double derivative of (\ref{expression:partial_x_D_equals_0_transformed}) w.r.t. $\theta$ on both side yields
    \begin{align}
    \label{expression:once_der_of_partial_x_D_equals_0_transformed}
        \text{(once) } & \h'(\theta)(x^*{}(\theta) + \varphi(\theta)) \\
        & \quad + \h(\theta)(x^*{}'(\theta) + \varphi'(\theta))  + \DDD'_{x^*}(\theta)= 0\\
    \label{expression:twice_der_of_partial_x_D_equals_0_transformed}
        \text{(twice) } & 2\h'(\theta)(x^*{}'(\theta) + \varphi'(\theta)) \\
        & \quad + \h''(\theta)(x^*(\theta) + \varphi(\theta)) \\
        & \quad + \h(\theta)(x^*{}''(\theta) + \varphi''(\theta)) + \DDD''_{x^*}(\theta) = 0.
    \end{align}
    And $\varphi'(\theta) = F(\theta)(1 - F(\theta))$, $\varphi''(\theta) = f(\theta) - 2F(\theta)f(\theta)$. So, (\ref{expression:once_der_of_partial_x_D_equals_0_transformed}), adding (\ref{expression:DDD_V_plus_primes_1}) simplifies to 
    $$-f(V^+)x^*{}'(V^+) + (1 - x^*{}'(V^+))f(V^+) = 0\\
    \Rightarrow x^*{}'(V^+) = \frac12$$
    Notice that $x^*(V^+) + \varphi(V^+) = 0$, so that we need not further calculate $h''(V^+)$. Integrating $x^*{}'(V^+) = \frac12$ into \ref{expression:DDD_V_plus_primes_2} we obtain
    $$
    \DDD''_{x^*}(V^+) = \frac14 f'(V^+) - f(V^+)x^*{}''(V^+) - \frac14 f^2(V^+)
    $$
    plug in \ref{expression:once_der_of_partial_x_D_equals_0_transformed} solves
    \begin{align*}
        x^*{}''(V^+)
        % & = \frac{-\frac14 f'(V^+) - \frac34 f^2(V^+)}{2f(V^+)}\\
        & = - \frac{f'(V^+) + 3f^2(V^+)}{8f(V^+)}
    \end{align*}

    Back to the function $g$. $g(V^+) = 0 = g'(V^+) = 0$. To study its higher-order derivatives, take $g'(\theta) = (1 - F(\theta))\g(\theta)$, we'd have
    \begin{align*}
        \g(\theta) & := f(\theta - x^*(\theta))(x^*(\theta) + \varphi(\theta)) + F(\theta)(\DD({\theta}, {x^*(\theta)}) - \frac12)\\
        \g'(\theta) & = (1 - x^*{}'(\theta))f'(\theta - x^*(\theta))(x^*(\theta) + \varphi(\theta)) \\
        & \quad + f(\theta - x^*(\theta))(x^*{}'(\theta) + \varphi'(\theta))\\
        & \quad + f(\theta)(\DDD_{x^*}(\theta) - \frac12) + F(\theta)\DDD'_{x^*}(\theta)\\
        \g''(\theta) & = (x^*(\theta) + \varphi(\theta))f''(\theta - x^*(\theta)) \\
        & \quad + 2f'(\theta - x^*(\theta))(1 - x^*{}'(\theta))(x^*{}'(\theta) + \varphi'(\theta))\\
        & \quad + f(\theta - x^*(\theta))(x^*{}''(\theta) + \varphi''(\theta)) + f'(\theta)(\DDD_{x^*}(\theta) - \frac12)\\
        & \quad + 2f(\theta)\DDD'_{x^*}(\theta) + F(\theta)\DDD''_{x^*}(\theta)
    \end{align*}
    Interestingly, $\g'(V^+) = 0$. But
    \begin{align*}
        \g''(V^+) & = \frac12 f'(V^+) + f(V^+)(x^*{}''(V^+) + f(V^+)) - \frac12 f'(V^+)\\
        & = f(V^+)\left(x^*{}''(V^+) + 2f(V^+)\right)\\
        & = \frac18\left(13 f^2(V^+) -  f'(V^+)\right)
    \end{align*}
    Therefore, when $f^2(V^+) < f'(V^+)$, $\exists \theta^\star \in N^+(V)$ such that $g( \theta^\star) < 0$, corresponding to $\mu(\theta^\star, x^*(\theta^\star) < 0 $ --- that starting from its upper bound $\bar c$, decrease in inspection cost (at least, with a small amount) will benefit consumer surplus.
\end{proof}

