\section{Local bound on the objective}\label{sec:obj_in_btw}

In the previous sections, we presented a fast way of computing the optimal objective value for all $\lambda \in \Lambda$ for a given optimal basis $B$. A typical representation of such an output would be a piecewise-linear plot, where the function $o^*(\lambda)$ would be represented by a piecewise-linear approximation based on the computed $o^*(\lambda_i)$ for $\lambda_i \in \Lambda$. However, $o^*(\lambda)$ is non-linear 
%This makes an implicit assumption that $o^*(\lambda)$ does not behave too erratically between two sampled points; this is, however, not always the case, as $o^*(\lambda)$ is typically non-linear.

In this section, we compute an upper bound on the following:
\begin{align}
    \max_{\lvert \delta \rvert \leq \Delta} \lvert o^*(\lambda+\delta) - o^*(\lambda) \rvert.
\end{align}
This bound assesses the maximum deviation of the objective function around a known precomputed point $\lambda$ up to a distance $\Delta$. For this, we first need the following Lemma:

\begin{lemma}
    \label{theorem_x}
    Given an optimal basis $B$ for $\mathcal{P}(0)$, and $\lambda$ and $\delta$ such that $I+\lambda E_B$ and $I+(\lambda+\delta) E_B$ are non-singular. Then,
    \begin{align}
        x_B(\lambda+\delta) - x_B(\lambda) =
         -\delta (I + (\lambda + \delta) E_B)^{-1} E_B x_B(\lambda)
    \end{align}
\end{lemma}
\begin{proof}
    We first write down some relations:
    \begin{align}
        (I + \lambda E_B + \delta E_B) &= (I + \lambda E_B)(I + \delta (I + \lambda E_B)^{-1} E_B)\\
        (I + \lambda E_B + \delta E_B)^{-1} &= (I + \delta (I + \lambda E_B)^{-1} E_B)^{-1}(I + \lambda E_B)^{-1} \label{eq:lemma2-bis}
    \end{align}
    Moreover, for any $X$ such that $(I + X)$ is invertible:
    \begin{align}
        (I + X)^{-1} - I &= (I + X)^{-1} - (I + X)^{-1}(I + X) = -(I + X)^{-1}X. \label{eq:lemma2-ter}
    \end{align}
    Starting from \eqref{eq:xb_fct_x0}:
    \begin{align}
    & x_B(\lambda+\delta) - x_B(\lambda)\\
         = &\ (I + \lambda E_B + \delta E_B)^{-1}A_B^{-1}b - (I + \lambda E_B)^{-1}A_B^{-1}b & \text{[from \eqref{eq:xb_fct_x0}]}\\
        = & \left((I + \lambda E_B + \delta E_B)^{-1} - (I + \lambda E_B)^{-1}\right)A_B^{-1}b\\
        = & \left((I + \delta (I + \lambda E_B)^{-1}E_B)^{-1} - I\right)(I + \lambda E_B)^{-1}A_B^{-1}b & \text{[using \eqref{eq:lemma2-bis}]}\\
        = & \left((I + \delta (I + \lambda E_B)^{-1}E_B)^{-1} - I\right)x_B(\lambda) & \text{[from \eqref{eq:xb_fct_x0}]}\\
        = & -\delta (I + \delta (I + \lambda E_B)^{-1}E_B)^{-1} (I + \lambda E_B)^{-1}E_B x_B(\lambda) & \text{[using \eqref{eq:lemma2-ter}]}\\
        = & -\delta (I + (\lambda + \delta) E_B)^{-1} E_B x_B(\lambda) \quad \qed & \text{[using \eqref{eq:lemma2-bis}]}
    \end{align}
\end{proof}

One can use this result and apply the decomposition methods presented earlier. However, this leads to a system of $m$ non-linear (but rational) equations. Instead, we propose to use sub-multiplicative norms:

\begin{theorem}
\label{theorem:bound_delta_1}
Given a basis $B$ which provides an optimal solution for $\mathcal{P}(0)$, $\mathcal{P}(\lambda)$ and a valid solution for $\mathcal{P}(\lambda+\delta)$. Then, for any sub-multiplicative matrix norm $\lVert . \rVert$,
\begin{align}
    \lvert o^*(\lambda + \delta) - o^*(\lambda) \rvert \leq \frac{\left\lvert\delta \right\rvert \left\lVert c_B^t \right\rVert \left\lVert E_B x_B(\lambda) \right\rVert}{1 -  \lvert\lambda + \delta \rvert \cdot \lVert E_B \rVert}
    \label{b3}
\end{align}
if $\lVert (\lambda + \delta) E_B \rVert_\infty < 1$ and $\lVert (\lambda + \delta) E_B \rVert < 1$.
\end{theorem}
\begin{proof}
    Using the definition of $o^\star$ and Lemma 2,
    \begin{align}
        \lVert o^*(\lambda + \delta) - o^*(\lambda) \rVert &= \left\lVert c^t_B \left(x_B(\lambda+\delta) - x_B(\lambda)\right)\right\rVert\\
        &= \left\lVert-\delta c_B^t(I + (\lambda + \delta) E_B)^{-1} E_B x_B(\lambda)\right\rVert
    \end{align}
    By using the sub-multiplicative property of the norm:
    \begin{align}
        \lVert o^*(\lambda + \delta) - o^*(\lambda) \rVert &\leq \left\lVert-\delta c_B^t \right\rVert \cdot \left\lVert(I + (\lambda + \delta) E_B)^{-1}\right\rVert \cdot \left\lVert E_B x_B(\lambda) \right\rVert\label{eq63}
    \end{align}
    As $\lVert (\lambda + \delta) E_B \rVert_\infty < 1$ by hypothesis, we can use the Neumann series, which we bound using sub-multiplicativity. We then use the geometric series $\sum^{\infty}_i q^i = \frac{1}{1-q}$ if $|q| < 1$ to obtain the following result:
    \begin{align}
        \lVert (I + (\lambda + \delta) E_B)^{-1} \rVert &= \lVert \sum_{i=0}^\infty -((\lambda + \delta) E_B)^i \rVert\\
        &\leq \sum_{i=0}^\infty \lVert -((\lambda + \delta) E_B)^i \rVert 
        \leq \sum_{i=0}^\infty \lVert (\lambda + \delta) E_B \rVert^i\\
        &\leq \frac{1}{1 - \lVert (\lambda + \delta) E_B \rVert}\label{eq67}
    \end{align}
    Using \eqref{eq67} in \eqref{eq63} proves the theorem.\qed
\end{proof}

