Theorem \ref{theorem:bound_delta_1} thus provides an easy-to-compute bound around the modification on the objective, if we can first ensure that the basis $B$ provides a valid solution for $\mathcal{P}(\lambda+\delta)$. The following theorem gives sufficient conditions for this:
%Elementary vectors and matrices have all sorts of useful properties, but we will focus on two of them:
%\begin{itemize}
%    \item $e_{i}^T E_{ii} = e_{i}^T$
%    \item $E_{ii} ^ j = E_{ii}\ \forall j \in \mathbb{N}^0$
%\end{itemize}


\begin{theorem}\label{theo:2}
    Given a scalar $\delta$, a basis $B$ which provides an optimal solution for $\mathcal{P}(0)$ and $\mathcal{P}(\lambda)$, and $\lVert . \rVert$ a sub-multiplicative matrix norm. Then, $B$ provides a feasible solution for $\mathcal{P}(\lambda+\delta)$ if the following four conditions are satisfied:
    \begin{align}
        \lVert (\lambda + \delta) E_B \rVert_\infty &< 1 \label{b1}\\
        \lVert (\lambda + \delta) E_B \rVert &< 1 \label{b2}\\
        (I + (\lambda + \delta)E_B) & \text{ is not singular}\\
        \frac{\left\lvert\delta \right\rvert \left\lVert e_i \right\rVert \left\lVert E_B x_B(\lambda) \right\rVert}{1 -  \lvert\lambda + \delta \rvert \cdot \lVert E_B \rVert} &\leq (x_B(\lambda))_i\ \forall i \label{b4}
    \end{align}
\end{theorem}

\begin{proof}
    As $(I + (\lambda + \delta)E_B)$ is not singular, we can generate a candidate solution to $\mathcal{P}(\lambda+\delta)$:
    \begin{align}
        x_B(\lambda+\delta) = (I + (\lambda + \delta)E_B)^{-1}A_B^{-1}b
    \end{align}
    This solution is feasible only if it respects the other constraints, namely that the variables are nonnegative: $(x_B(\lambda+\delta))_i \geq 0 \ \forall i$. 

    By hypothesis, as $B$ provides an optimal solution for $x_B(\lambda)$, we have that $x_B(\lambda) \geq 0$. Under this assumption, the following is a sufficient condition for the variables at $\lambda+\delta$ to be nonnegative:
    \begin{align}
        \lvert (x_B(\lambda+\delta) - x_B(\lambda))_i \rvert \leq (x_B(\lambda))_i \Rightarrow (x_B(\lambda+\delta))_i \geq 0 \quad \forall i.\label{s_impl}
    \end{align}


    By using Lemma \ref{theorem_x} and the Neumann series ($\lVert (\lambda + \delta) E \rVert_\infty < 1$ by hypothesis) on the main part of the condition, we obtain $\forall i$:
    \begin{align}
        \lvert (x_B(\lambda+\delta) - x_B(\lambda))_i \rvert &= \left\lvert e_{i}^T\left(x_B(\lambda+\delta) - x_B(\lambda) \right) \right\rvert\\
        &= \left\lvert -\delta e_{i}^T(I + (\lambda + \delta) E_B)^{-1} E_B x_B(\lambda)\right\rvert\\
        &= \left\lvert -\delta e_{i}^T\sum_{j=0}^\infty(-(\lambda + \delta) E_B)^{j} E_B x_B(\lambda)\right\rvert,
    \end{align}
    where $e_i$ is the $i$th elementary vector.
    We can then use the same techniques as in the previous proof to find 
    \begin{align}
        \lvert (x_B(\lambda+\delta) - x_B(\lambda))_i \rvert & \leq \frac{\left\lvert\delta \right\rvert \left\lVert e_i \right\rVert \left\lVert E_B x_B(\lambda) \right\rVert}{1 -  \lvert\lambda + \delta\rvert \cdot \lVert E_B \rVert}\quad \forall i.\label{bound_s}
    \end{align}

    Thus from \eqref{bound_s} and \eqref{s_impl}, we have the following implication:
    \begin{align}
        \frac{\left\lvert\delta \right\rvert \left\lVert e_i \right\rVert \left\lVert E_Bx_B(\lambda) \right\rVert}{1 -  \lvert\lambda + \delta \rvert \cdot \lVert E_B \rVert} \leq (x_B(\lambda))_i \Rightarrow (x_B(\lambda + \delta))_i \geq 0 \quad \forall i.
    \end{align}

    This condition is respected by hypothesis, proving that all slack variables are nonnegative, the solution is thus feasible.\qed
\end{proof}

We can combine the two results to obtain a way to upper bound the function $o^*(\lambda)$ around a given $\lambda$. Here we consider a specific result for $\lambda, \delta \geq 0$ (so as to simplify the absolute values) but the results are similar in the other cases.
\begin{theorem}
    Given $\epsilon$ (the maximal error), $\lambda \geq 0$, a basis $B$ which provides an optimal solution for $\mathcal{P}(0)$ and $\mathcal{P}(\lambda)$, and $\lVert . \rVert$ a sub-multiplicative matrix norm, let $N$ be the set of eigenvalues of $E_B$ and 
    \begin{align}
        \Delta &= \min \begin{cases}
            \frac{1}{\lVert E_B \rVert_\infty}-\lambda\\
            \frac{1}{\lVert E_B \rVert}-\lambda\\
            \frac{\epsilon(1-\lambda \lVert E_B \rVert)}{\lVert c^t_B \rVert \lVert E_Bx_B(\lambda)\rVert + \epsilon \lVert E_B \rVert}\\
            \frac{(x_B(\lambda))_i(1-\lambda \lVert E_B \rVert)}{\lVert e_i \rVert \lVert E_Bx_B(\lambda)\rVert + (x_B(\lambda))_i \lVert E_B \rVert} & \forall i
        \end{cases}
    \end{align}
    Then, $\forall \delta \in [0, \Delta] \setminus \{\frac{-1}{\nu} - \lambda \mid \nu \in N\}$:
    \begin{itemize}
        \item the basis $B$ provides a valid solution for $\mathcal{P}(\lambda+\delta)$;
        \item $\lvert o^*(\lambda+\delta) - o^*(\lambda) \rvert \leq \epsilon$.
    \end{itemize}
\end{theorem}
\begin{proof}
    Direct from the two previous theorems. The bounds on $\Delta$ are respectively the ones from equations \eqref{b1}, \eqref{b2}, \eqref{b3}, \eqref{b4}, rewritten under the assumption that $\lambda, \delta \geq 0$. The conditions on $\delta$ ensures that the matrix $I + (\lambda + \delta) E_B$ is non-singular. \qed
\end{proof}



