\title{A Note on the Reliability of Goal-Oriented Error
Estimates for Galerkin Finite Element Methods with Nonlinear Functionals}
\author[sandia]{Brian N. Granzow\corref{correspondence}}
\author[sandia]{Stephen D. Bond}
\author[sandia]{D. Thomas Seidl}
\author[luh]{Bernhard Endtmayer}
\address[sandia]{Sandia National Laboratories \\
