    \includegraphics[scale=1.32]{CAE.pdf}
    \caption{Architecture of the employed convolutional autoencoder with a probabilistic output layer, approximating the multi-fidelity conditional $p(\Yhf|\Zlf)$.}
    \label{fig:cae}
\end{figure}

