\subsection{Algorithmic summary}
\label{sec: algo_summary}

To conclude the method section, we provide an overview of BMFIA in form of pseudo-algorithms for its initial training phase in Algorithm \ref{alg:offline_bmfia} and its inference phase (with continuous updates for the multi-fidelity conditional) in Algorithm \ref{alg:online_bmfia}. The VB-EM Algorithm \ref{alg:vb_em_tau} for the MF likelihood precision $\tau$ (which is part of the inference phase \ref{alg:online_bmfia}) is presented in Appendix \ref{sec:vb_em_tau}. 
In the first \emph{initial training phase} of BMFIA (Algorithm \ref{alg:offline_bmfia}), we generate training inputs $\bx_i$ sampled from the (joint) prior model $\bx_i\sim p(\bx)$ (see Section \ref{sec: training_data}). Afterwards, we realize the associated LF and HF simulations $\Ylf_i = \Mlf(\bx_i)$, and $\Yhf_i = \Mhf(\bx_i)$ to gather the training data $\mathcal{D}=[\Zlf_i,\Yhf_i]$, with $\Zlf_i=\{\Ylf_i,X_i\}$. We then train the probabilistic regression model, approximating the multi-fidelity conditional $p(\Yhf|\Zlf)$ on $\mathcal{D}$. 
Once the probabilistic regression model is trained, we transition to the inference phase of BMFIA, which is given in Algorithm \ref{alg:online_bmfia}. Here, the probabilistic regression model approximates the multi-fidelity conditional and gives rise to the multi-fidelity log-likelihood. In this phase, we conduct sparse variational inference (see Section \ref{sec: svi} along with variational Bayes Expectation-Maximization (VB-EM) (see Sections \ref{sec:small_data_approx} and \ref{sec: svi}) to iteratively calculate updates for the variational parameters $\bphi$ in the variational distribution $q_{\mathrm{MF}}(\bx|\bphi)$, which approximates the multi-fidelity posterior $\pmf(\bx|\Yobs)$. In the inference phase, we only need to evaluate the LF model $\Mlf(\bx)$ and the adjoint LF model $\Alf\left(\bx,\nabla_{\Ylf}\lmf(\Ylf)\right)$ for the involved gradients, which is a crucial advantage of BMFIA. Optionally, we can update the multi-fidelity conditional after some iterations of the SVI algorithm by adding additional training data sampled from the current variational posterior approximation using Algorithm \ref{alg:offline_bmfia} (with the current posterior approximation instead of the prior) and continuously retraining the multi-fidelity approximation. 

% ----------------------- BMFIA offline -------------------------------------
\begin{algorithm}[htbp]
\SetAlgoLined

Generate initial samples from the joint-prior (or current variational distribution for refinements): 
\[
\{\bx_i\}|_{i=1}^{N_{\mathrm{init}}}\sim p(\bx,\delta), \qmf(\bx|\bphi)
\]

Evaluate LF and HF model (at coordinates $C=[\bc_i^T]$):
\[
\Ylf_i \gets \Mlf(\bx_i), \quad \Yhf_i \gets \Mhf(\bx_i), \quad i=1,\dots,N_{\mathrm{init}}
\]

Interpolate and evaluate the input field at the same spatial coordinates $C=[\bc_i^T]$ (see Equations \eqref{eqn: rf_fe} -  \eqref{eqn: input_field}):
\[
X_i(\bx_i) \gets [\tilde{\bx}_i(\bc_j)] = \left[S_{\mathrm{ele}}(\bc_j)\cdot \bx_{\mathrm{ele}}]=[S_{\mathrm{ele}}(\bc_j)\cdot\mathfrak{R}[\bx]\right]
\]

Compose multi-fidelity training dataset:
\[
\mathcal{D} = \{(\Zlf_i, \Yhf_i)\},\quad\text{with}\quad\Zlf_i=[\Ylf_i,X_i]
\]

Train probabilistic regression model to approximate multi-fidelity conditional density:
\[
p(\Yhf | \Zlf) \approx \mathcal{N}\left[\Yhf | M(\Zlf), \diag\left(V(\Zlf)\right)\right] \gets \mathcal{D},\ \text{untrained ProbabilisticRegression}
\]

\Return Multi-fidelity conditional approximation $p(\Yhf | \Zlf) \approx \mathcal{N}\left[\Yhf | M(\Zlf), \diag\left(V(\Zlf)\right)\right]$
\caption{Multi-Fidelity Conditional Training (initial training phase)}
\label{alg:offline_bmfia}
\end{algorithm}

% --------- BMFIA online ------------------------------------------------
\begin{algorithm}[htbp]
\SetAlgoLined
Initialize variational parameters: $\bphi, \bphi_{\tau}\gets\bphi_0,\bphi_{0,\tau}$

\While{not converged}{
Sample $\nsamples$ samples from variational distribution $\qmf(\bx|\bphi)$ using reparameterization trick:
\[
\{\bx_i\}|_{i=1}^{\nsamples} =\bmu(\bphi) + L(\bphi)\cdot \{\br_i\}|_{i=1}^{\nsamples} \gets \{\br_i\}|_{i=1}^{\nsamples}\sim \mathcal{N}\left(\br|\boldsymbol{0},I\right)
\]

Evaluate LF model and input field for sample batch $\{\bx_i\}|_{i=1}^{\nsamples}$:
\[
\{\Zlf_i\}|_{i=1}^{\nsamples}\gets\{\Ylf_{i},X_i\}|_{i=1}^{\nsamples}\gets \{\Mlf(\bx_{i}),X(\bx_i)\}|_{i=1}^{\nsamples}
\]



VB-EM for likelihood precision $\tau$ (not given in closed-form), see Algorithm \ref{alg:vb_em_tau}:
\[
\{\nabla_{\Ylf}\lmf(\Zlf_i)\}|_{i=1}^{\nsamples}\gets \mathrm{Algorithm}\ \ref{alg:vb_em_tau}\ \left(\bphi_{0,\tau},q(\tau|\bphi_\tau), \lmf, \{\Zlf_i\}|_{i=1}^{\nsamples},p(\tau),\Yobs \right)
\]



Evaluate LF adjoint model for sample batch for MF log-likelihood partial gradients (right-hand side):
\[
\{\nabla_{\bx}\lmf(\bx_{i})\}|_{i=1}^{\nsamples}\gets \{\Alf\left(\bx_i, \nabla_{\Ylf}\lmf(\Zlf_i)\right)\}|_{i=1}^{\nsamples}
\]

Conduct VB-EM for prior $p(\bx)$, given in closed-form and get prior gradient $\nabla_\bx p(\bx)$:
\[
\{\nabla_{\bx} p(\bx_i)\}|_{i=1}^{\nsamples}\gets \mathrm{VB-EM}\left(p(\bx|\delta), p(\delta), \{\bx_i\}|_{i=1}^{\nsamples}\right)
\]

Apply chain rule from reparameterization to yield gradients \wrt $\bphi$:
\[
\{\nabla_{\bphi}\lmf(\bx_i(\bphi)), \nabla_{\bphi}p\left(\bx_i(\bphi)\right)\}|_{i=1}^{\nsamples}\gets \bx=\bx(\bphi)
\]

Compute ELBO gradient:
\[
\nabla_{\bphi}\mathrm{ELBO}\gets\{\nabla_{\bphi}\lmf(\bx_i(\bphi)), \nabla_{\bphi}p\left(\bx_i(\bphi)\right)\}|_{i=1}^{\nsamples}\]

Update variational parameters $\bphi$ (\eg SGD, ADAM):
\[
\bphi\gets \text{Stochastic optimizer step}\left(\bphi,\nabla_{\bphi}\mathrm{ELBO}\right)
\]

\If{refinement in iteration active}{
Draw additional samples from $\qmf(\bx|\bphi)$ and update the ProbabilisticRegression using Algorithm \ref{alg:offline_bmfia}\;
}
}
\Return optimized posterior approximation $\qmf(\bx|\bphi)$
\caption{BMFIA with Sparse Variational Inference and Expectation-Maximization (inference phase)}
\label{alg:online_bmfia}
\end{algorithm}

\FloatBarrier

