Mathematically, the boundary conditions are formulated as follows:
\begin{subequations}
\begin{align}
    \bdisp^{\text{s}}\cdot \bn_{\mathrm{top}} = 0, &\qquad \text{ on } \Gamma^{\text{s}}_{0,\text{top}} \times \left[t_0; t_\text{F}\right]
    \label{eqn: poro_elastic_bcs_a} \\
     \bdisp^{\text{s}} = \boldsymbol{0}, &\qquad \text{ at } P^{\text{s}}_{0} \times \left[t_0; t_\text{F}\right]
      \label{eqn: poro_elastic_bcs_point} \\
    \bdisp^{\text{s}} \cdot \bn_{\mathrm{bottom}} = 0, &\qquad \text{ on } \Gamma^{\text{s}}_{0,\text{bottom}} \times \left[t_0; t_\text{F}\right]
    \label{eqn: poro_elastic_bcs_b} \\
    \left( \bF \bS \right) \cdot \bN_{0,\mathrm{left,right}} = \bnil, &\qquad \text{ on } \Gamma^\text{s}_{0,\text{left}} \cup \Gamma^\text{s}_{0,\text{right}} \times \left[t_0; t_\text{F}\right]
    \label{eqn: poro_elastic_bcs_c} \\
    \left(\bu^\text{f} - \bu^\text{s} \right)\cdot \bn_{\mathrm{left, right}} = 0, & \qquad \text{ on } \Gamma^\text{f}_{t,\text{left}} \cup \Gamma^\text{f}_{t,\text{right}} \times \left[t_0; t_\text{F}\right]
    \label{eqn: poro_elastic_bcs_d} \\
    p^\text{f} = 0, &\qquad \text{ on } \Gamma^\text{f}_{t,\text{left}} \cup \Gamma^\text{f}_{t,\text{right}} \times \left[t_0; t_\text{F}\right]
     \label{eqn: poro_elastic_bcs_e}\\
     p^{\text{f}} = 0.02\cdot\pi\cdot\sin(0.4\cdot\pi\cdot t), &\qquad \text{ on } \Gamma^{\text{f}}_{t, \text{top}} \times \left[t_0; t_\text{F}\right]
     \label{eqn: poro_elastic_bcs_f}
\end{align}
\end{subequations}
where $\bdisp^\text{s}$ is the structural displacement field. $\bn$ and $\bN_0$ denote the outward boundary normal vectors in the spatial and reference configurations, respectively.
Complementing the boundary conditions, the initial conditions are homogeneous in the whole domain:
\begin{subequations}
\begin{align}
    \bdisp^{\text{s}} = \boldsymbol{0}, &\qquad \text{ in } \Omega^{\text{s}}_{0} \times \left[t_0\right]
    \label{eqn: poro_elastic_ics_d} \\
    \bu^{\text{s}} = \boldsymbol{0}, &\qquad \text{ in } \Omega^{\text{s}}_{0} \times \left[t_0\right]
    \label{eqn: poro_elastic_ics_us} \\
     \bu^{\text{f}} = \boldsymbol{0}, &\qquad \text{ in } \Omega^{\text{f}}_{0} \times \left[t_0\right]
      \label{eqn: poro_elastic_ics_uf} \\
    p^{\text{f}} = 0, &\qquad \text{ in } \Omega^{\text{f}}_{0} \times \left[t_0\right]
    \label{eqn: poro_elastic_ics_pf}
\end{align}
\end{subequations}

