\section{Variational Bayes Expectation Maximization for the Multi-Fidelity Likelihood}
\label{sec:vb_em_tau}

We start by considering the multi-fidelity (MF) log-likelihood initially dependent on the unknown precision parameter $\tau$. Subsequently, we use the following expression interchangeably: $\lmf(\bx)=\log \pmf(\Yobs|\bx)$, as well as $\lmf(\bx,\tau)=\log \pmf(\Yobs|\bx,\tau)$. To account for uncertainty in $\tau$, we introduce a probabilistic model treating $\tau$ as a latent variable with a specified prior $p(\tau)$:
\begin{subequations}
\begin{align}
\lmf(\bx)&=\log \pmf(\Yobs|\bx) = \log \int \pmf(\Yobs|\bx, \tau)\cdot p(\tau) \dd \tau \\
&= \log \Ex{p(\tau)}{\pmf(\Yobs|\bx,\tau)} \\
&= \Ex{p(\tau|\Yobs,\bx)}{\log \left(\frac{\pmf(\Yobs|\bx,\tau)\cdot p(\tau)}{p(\tau|\Yobs,\bx)}\right)} \label{eqn:latent_mf_loglik}
\end{align}
\end{subequations}
Equation \eqref{eqn:latent_mf_loglik} can be derived using Jensen's inequality:
\begin{equation}
    \begin{array}{ll}
     \log \pmf(\Yobs|\bx) &= \log \int \pmf(\Yobs|\bx, \tau)\cdot p(\tau) \dd\tau\\
    & = \log \int \frac{ \pmf(\Yobs|\bx, \tau)\cdot p(\tau) } {q(\tau)} q(\tau)\dd\tau  \\
                         & \ge \Ex{q(\tau)}{\log \left(\frac{ \pmf(\Yobs|\bx, \tau)\cdot p(\tau)} {q(\tau)}\right)} \qquad \textrm{(Jensen's~ inequality)}
    \end{array}
\end{equation}
The optimal $q(\tau)$ is the posterior $p(\tau|\Yobs,\bx)=\frac{\pmf(\Yobs|\bx, \tau)\cdot p(\tau)}{\pmf(\Yobs|\bx)}$, which, upon substitution, converts the inequality to an equality.


We furthermore adopt an uninformative Gamma prior for $\tau$:
\begin{equation}
p(\tau)=\Gamma(\tau|a_0,b_0), \quad a_0=b_0=10^{-9},
\end{equation}
preferring small precision values and thus larger variance in the likelihood.

Since the Gaussian multi-fidelity log-likelihood has $\tau$ as an additive term in its covariance matrix (see Equation \eqref{eqn:margMFGauss}):
\begin{equation*}
\lmf(\bx, \tau) = \log\pmf(\Yobs|\bx,\tau)=\log\left(\mathcal{N}\left(\Yobs \Big| M\left(\Zlf(\bx)\right), \underbrace{\tau^{-1}\cdot I + \Kmat\left(\Zlf(\bx)\right)}_{\Kmf(\Zlf(\bx),\tau)}\right)\right),
\end{equation*}
a conjugate prior and therefore an analytical posterior solution for $p(\tau|\Yobs,\bx)$ is unavailable. Instead of fixing or heuristically estimating $\tau$, approaches known to cause instability, we utilize the Variational Bayes Expectation-Maximization (VB-EM) \cite{dempster1977maximum, beal2003variational} framework. VB-EM iteratively computes the expectation with respect to the posterior $p(\tau|\Yobs,\bx)$, effectively capturing the average impact of $\tau$ on the MF log-likelihood. This probabilistic and iterative averaging leads to more robust inference outcomes.

Specifically, in the \textbf{E-step} of Algorithm~\ref{alg:vb_em_tau}, we approximate the posterior $p(\tau|\Yobs,\bx)$ variationally using a log-normal distribution:
\begin{equation}
q(\tau | \bphi_{\tau}) \approx p(\tau | \Yobs, \bx), \quad \tau = \exp(\tilde{\tau}), \quad q(\tilde{\tau} | \bphi_{\tau}) = \mathcal{N}(\tilde{\tau} | \mu_{\tau}(\bphi_{\tau}), \sigma_{\tau}^2(\bphi_{\tau})).
\end{equation}
We iteratively optimize the variational parameters $\bphi_{\tau}$ by (see Algorithm \ref{alg:vb_em_tau}):
\begin{enumerate}
\item Sampling $\tau_j \sim q(\tau | \bphi_{\tau})$ via the reparameterization trick.
\item Computing gradients of the MF log-likelihood $\lmf(\bx, \tau)$ and prior $p(\tau)$ with respect to $\tau$.
\item Applying the chain rule to derive gradients with respect to $\bphi_{\tau}$.
\item Updating $\bphi_{\tau}$ using stochastic optimization (e.g., ADAM optimizer).
\end{enumerate}

After convergence, we use the optimized variational posterior samples $\{\tau_j\}|_{j=1}^{\ntau} \sim q(\tau|\bphi_{\tau})$ in the \textbf{M-step} of Algorithm~\ref{alg:vb_em_tau}. Here, we marginalize over $\tau$ per sample $\bx_i$ to estimate the gradients of the MF log-likelihood with respect to the low-fidelity outputs $\Ylf$. Note that at this point we already have LF samples $\Zlf_i=\Zlf(\bx_i)$, so that we can drop the dependence on $\bx$ in the following (using Fisher's identity\cite{fisher1925theory} for the gradient\footnote{$\Ex{p(\bz|\bw)}{\nabla_{\bw}\log p(\bz|\bw)}=0$, the gradient (or \emph{score function}) of a log-density, when averaged over its own distribution, equals zero.}):
\begin{equation}
\nabla_{\Ylf}\lmf(\Zlf_i) \approx \frac{1}{n_{\tau}}\sum_{j=1}^{n_{\tau}} \nabla_{\Ylf}\lmf(\Zlf_i,\tau_j), \quad \{\tau_j\}|_{j=1}^{\ntau} \sim q(\tau | \bphi_{\tau}).
\end{equation}
Thus, the VB-EM algorithm effectively captures the probabilistic uncertainty in $\tau$ by averaging its influence on the MF log-likelihood. This method ensures stable inference and accurate parameter updates within our variational inference framework. Further methodological details can be found in \cite{nitzler2025highdimsvi} and Section~\ref{sec: algo_summary}.
% ----------------- VB EM tau --------------------------
\begin{algorithm}[htbp]
\SetAlgoLined
Approximate posterior of lik. precision $\tau$ with SVI: $q(\tau|\bphi_{\tau})\approx p(\tau|\Yobs,\bx_i)$ \textbf{[E-step]}

\While{not converged}{
    Sample $\ntau$ samples from variational distribution $q(\tau|\bphi_\tau)$ using the reparameterization trick:
    \[
    \{\tau_j\}_{j=1}^{\ntau} =\mu_\tau(\bphi_\tau) + \sigma_\tau(\bphi)\cdot \{r_{\tau_j}\}|_{i=j}^{\ntau} \gets \{r_{\tau,j}\}|_{i=j}^{\ntau}\sim \mathcal{N}\left(r|0,1\right)
    \]

    Plug $\tau$-samples into precision prior and MF log-likelihood:
    \[
        \{\nabla_\tau\lmf\left(\Zlf_i,\tau_j\right), \nabla_\tau p(\tau_j)\}|_{j=1}^{n_\tau}\gets \Zlf_i, \{\tau_j\}|_{j=1}^{\ntau}
    \]

    Apply chain rule form reparameterization to yield gradients \wrt $\bphi_\tau$:
    \[
    \{\nabla_{\bphi_\tau}\lmf\left(\Zlf_i,\tau_j\right), \nabla_{\bphi_\tau} p(\tau_j)\}|_{j=1}^{n_\tau}\gets \{\nabla_\tau\lmf\left(\Zlf_i,\tau_j\right) + \nabla_\tau p(\tau_j)\}|_{j=1}^{\ntau}
    \]

    Formalize and evaluate $\tau$-ELBO gradients:
    \[\nabla_{\bphi_\tau}\mathrm{ELBO}^{q(\tau|\bphi_{\tau})}\gets \{\nabla_\tau\lmf\left(\Yobs|\Zlf_i,\tau_j\right) + \nabla_\tau p(\tau_j)\}|_{j=1}^{n_\tau}\]

    Update variational parameters $\bphi_\tau$ (\eg SGD, ADAM):

    \[\bphi_{\tau}\gets \text{Stochastic optimizer step }\left(\bphi_\tau,\nabla_{\bphi_\tau}\mathrm{ELBO}^{q(\tau|\bphi_{\tau})}\right)\]
}
Sample from (converged) variational posterior approximation for precision $q(\tau|\bphi_\tau)$:
\[\{\tau_j\}_{j=1}^{n_\tau}\sim q(\tau|\bphi_{\tau})\]

Evaluate partial gradient of MF log-likelihood \wrt $\Ylf$, then marginalize $\tau$ \textbf{[M-step]}:
\[
\nabla_{\Ylf}\lmf(\Zlf_i)\gets \{\nabla_{\Ylf} \lmf(\Zlf_i,\tau_j)\}|_{j=1}^{n_\tau}\gets \Zlf_i, \{\tau_j\}|_{j=1}^{n_\tau}
\]
\Return $\nabla_{\Ylf}\lmf(\Zlf_i)$
\caption{VB-EM for MF log-likelihood precision hyper-parameter $\tau$, per sample $\bx_i$}
\label{alg:vb_em_tau}
\end{algorithm}

